# ---------------------------------------------------------------------------
# ADDITIVE EXTRACTION STATUS CONTRACT v92
# ---------------------------------------------------------------------------
#
# extract_transactions() keeps its historical return type: list[dict].
# This side-channel allows the caller/handler to distinguish:
#   - truly unsupported / no recognized structural authority;
#   - recognized statement whose accounting evidence is inconsistent;
#   - reconciled financial ledger.
#
# No transaction is created or promoted by this metadata.
_FINANCE_EXTRACTION_STATUS: dict = {
    "status": "not_run",
    "recognized": False,
    "financial_authority": False,
    "reason": None,
    "details": {},
}

# ADDITIVE v147 — restore non-authoritative audit candidate side-channel.
# This API existed in v144/v145 and is required by the finance handler.
# It does not change routing, parser selection, or financial authority.
_FINANCE_AUDIT_CANDIDATE: dict | None = None
_FINANCE_OBSERVED_ANALYSIS_CANDIDATE: dict | None = None
_FINANCE_SCOPE_REJECTION_EVIDENCE: dict | None = None


def _set_finance_audit_candidate(candidate: dict | None) -> None:
    global _FINANCE_AUDIT_CANDIDATE
    _FINANCE_AUDIT_CANDIDATE = (
        dict(candidate)
        if isinstance(candidate, dict)
        else None
    )


def _set_finance_observed_analysis_candidate(candidate: dict | None) -> None:
    global _FINANCE_OBSERVED_ANALYSIS_CANDIDATE
    _FINANCE_OBSERVED_ANALYSIS_CANDIDATE = (
        dict(candidate)
        if isinstance(candidate, dict)
        else None
    )


def _set_finance_scope_rejection_evidence(evidence: dict | None) -> None:
    global _FINANCE_SCOPE_REJECTION_EVIDENCE
    _FINANCE_SCOPE_REJECTION_EVIDENCE = (
        dict(evidence)
        if isinstance(evidence, dict)
        else None
    )


def get_finance_scope_rejection_evidence() -> dict | None:
    if not isinstance(_FINANCE_SCOPE_REJECTION_EVIDENCE, dict):
        return None
    return dict(_FINANCE_SCOPE_REJECTION_EVIDENCE)


def get_finance_observed_analysis_candidate() -> dict | None:
    if not isinstance(_FINANCE_OBSERVED_ANALYSIS_CANDIDATE, dict):
        return None

    result = dict(_FINANCE_OBSERVED_ANALYSIS_CANDIDATE)
    if isinstance(result.get('transactions'), list):
        result['transactions'] = [
            dict(tx)
            for tx in result['transactions']
            if isinstance(tx, dict)
        ]
    return result


def get_finance_audit_candidate() -> dict | None:
    """Return a defensive copy of the latest audit-only candidate."""
    if not isinstance(_FINANCE_AUDIT_CANDIDATE, dict):
        return None

    result = dict(_FINANCE_AUDIT_CANDIDATE)
    result["transactions"] = [
        dict(tx)
        for tx in (result.get("transactions") or [])
        if isinstance(tx, dict)
    ]
    return result



def _set_finance_extraction_status(
    status: str,
    *,
    recognized: bool,
    financial_authority: bool,
    reason: str | None = None,
    details: dict | None = None,
) -> None:
    global _FINANCE_EXTRACTION_STATUS

    _FINANCE_EXTRACTION_STATUS = {
        "status": str(status or "unknown"),
        "recognized": bool(recognized),
        "financial_authority": bool(financial_authority),
        "reason": reason,
        "details": dict(details or {}),
    }


def get_finance_extraction_status() -> dict:
    """Return a copy of the latest extraction status.

    Backward-compatible: callers that ignore this helper keep receiving the
    historical list-only extract_transactions() result.
    """
    return {
        "status": _FINANCE_EXTRACTION_STATUS.get("status"),
        "recognized": bool(
            _FINANCE_EXTRACTION_STATUS.get("recognized")
        ),
        "financial_authority": bool(
            _FINANCE_EXTRACTION_STATUS.get("financial_authority")
        ),
        "reason": _FINANCE_EXTRACTION_STATUS.get("reason"),
        "details": dict(
            _FINANCE_EXTRACTION_STATUS.get("details") or {}
        ),
    }


# RUNEXA_FINANCE_LOG_ONCE_V1
_FINANCE_PRINTED_LOG_KEYS: set[str] = set()


def _update_official_summary_non_destructive(
    current_summary,
    new_summary,
):
    """Merge statement totals without losing stronger existing values."""
    return merge_official_summaries(
        current_summary,
        new_summary,
    )


def _finance_log_once(*args) -> None:
    """
    Affiche un événement de diagnostic une seule fois par processus.

    La sortie est rendue compatible avec les consoles Windows dont
    l'encodage ne peut pas représenter certains caractères Unicode.
    Ce mécanisme ne modifie aucune extraction.
    """
    try:
        key = repr(args)
    except Exception:
        key = str(tuple(type(value).__name__ for value in args))

    if key in _FINANCE_PRINTED_LOG_KEYS:
        return

    _FINANCE_PRINTED_LOG_KEYS.add(key)

    try:
        print(*args)
    except UnicodeEncodeError:
        safe_args = []

        for value in args:
            try:
                rendered = str(value)
            except Exception:
                rendered = repr(value)

            encoding = getattr(sys.stdout, "encoding", None) or "utf-8"

            safe_rendered = rendered.encode(
                encoding,
                errors="backslashreplace",
            ).decode(
                encoding,
                errors="strict",
            )

            safe_args.append(safe_rendered)

        print(*safe_args)


