def looks_like_neutral_inbound_transfer(line: str, amount: float | None = None) -> bool:
    """Detect positive transfer rows that should be income when not outgoing.

    Standard international FR / EN / AR rule, not bank-specific:
    if a row describes a transfer/remittance and there is no explicit outgoing
    marker, a positive amount extracted from a credit/debit table is treated
    as income. This covers OCR rows such as:
        VIREMENT MANN ... 118.00
        VIREMENT ETRANGER ... 630.00
    while preserving outgoing rows like virement emis / transfer sent / تحويل صادر.
    """
    if amount is not None and amount <= 0:
        return False

    lower = str(line or "").lower()

    transfer_markers = [
        # FR
        "virement",
        "vir ",
        "vir.",
        "virement etranger",
        "virement étranger",

        # EN / international
        "transfer",
        "wire transfer",
        "bank transfer",
        "remittance",

        # AR
        "تحويل",
        "حوالة",
    ]

    outgoing_markers = [
        # FR
        "virement emis",
        "virement émis",
        "vir emis",
        "vir émis",
        "vir.emis",
        "vers ",
        "a destination de",
        "à destination de",

        # EN / international
        "outgoing transfer",
        "transfer sent",
        "sent transfer",
        "transfer to",
        "payment to",
        "debit transfer",

        # AR
        "تحويل صادر",
        "حوالة صادرة",
        "إلى",
        "الى",
    ]

    has_transfer = any(marker in lower for marker in transfer_markers)
    has_outgoing = any(marker in lower for marker in outgoing_markers)

    return has_transfer and not has_outgoing


def extract_debit_credit_from_description(line: str) -> tuple[float | None, str | None]:
    """Infer amount/type from debit-credit bank tables.

    This is still general: many bank PDFs expose separate debit and credit
    columns, but OCR often flattens the row into one line. When the
    description clearly says incoming/received, the single visible amount is a
    credit. When it clearly says card/ATM/debit/fee/outgoing, the single
    visible amount is a debit.

    Amount selection uses extract_transaction_money_numbers() so short
    statement/value dates such as 22.11 or 05.11.21 are not mistaken for money.
    """
    numbers = extract_transaction_money_numbers(line)

    if not numbers:
        return None, None

    amount = pick_transaction_amount_from_tabular_numbers(numbers, line)

    if looks_like_credit_description(line) or any(
        marker in line.lower() for marker in UNIVERSAL_INCOME_MARKERS
    ):
        return abs(amount), "income"

    if looks_like_debit_description(line) or any(
        marker in line.lower() for marker in UNIVERSAL_EXPENSE_MARKERS
    ):
        return -abs(amount), "expense"

    return None, None




def is_probable_running_balance_token(token: str, line: str) -> bool:
    """Detect tokens likely to be balances, not transaction movements."""
    try:
        value = abs(parse_amount(token))
    except Exception:
        return False

    lower = str(line or "").lower()
    has_movement_marker = any(marker in lower for marker in [
        "apple pay", "purchase", "achat", "شراء", "حواله", "حوالة",
        "transfer", "virement", "paiement", "card", "carte", "gab", "atm",
    ])

    # Very large terminal values after a movement marker are commonly running balances.
    return has_movement_marker and value >= 1000


def select_transaction_money_token(numbers: list[str], line: str) -> str | None:
    """Choose transaction amount, not balance, from OCR-flattened rows.

    Standard bank rule: when amount and running balance are both present, the
    running balance is usually the last monetary token. Prefer the penultimate
    token, unless there is only one visible amount. For Arabic/GCC rows where
    OCR exposes a clear purchase/transfer amount before a terminal balance,
    avoid selecting the terminal balance.
    """
    if not numbers:
        return None

    if len(numbers) == 1:
        return numbers[0]

    # Prefer penultimate token in amount/balance rows.
    candidate = numbers[-2]
    terminal = numbers[-1]

    if is_probable_running_balance_token(candidate, line) and len(numbers) >= 3:
        return numbers[-3]

    if is_probable_running_balance_token(terminal, line):
        return candidate

    return candidate

def pick_bank_amount(
    numbers: list[str],
    line: str,
    account_currency: str | None = None,
) -> float:
    text = normalize_line_for_amount_detection(line.upper())

    currency_amounts = re.findall(
        r"\b(?:USD|EUR|GBP|AED|MAD|CAD|JOD|SAR|QAR|KWD|BHD|OMR|دينار|دولار|درهم|ريال)\s*([+-]?\d[\d,]*(?:[.,]\d{1,2})?)",
        text,
        flags=re.IGNORECASE,
    )

    if currency_amounts:
        return parse_amount(currency_amounts[-1])

    if account_currency:
        matches = re.findall(
            rf"{account_currency}\s*([\d,]+(?:[.,]\d{{1,2}})?)",
            text,
        )

        if matches:
            return parse_amount(matches[-1])

    money_numbers = extract_money_numbers_safely(line)

    if money_numbers:
        return parse_amount(money_numbers[-1])

    raise ValueError(
        "No reliable money amount found in transaction line."
    )




def pick_transaction_amount_from_tabular_numbers(
    numbers: list[str],
    line: str,
    account_currency: str | None = None,
) -> float:
    safe_numbers = extract_transaction_money_numbers(line)

    selected_token = select_transaction_money_token(safe_numbers, line)

    if selected_token is not None:
        return parse_terminal_amount(selected_token, line)

    return pick_bank_amount(
        numbers,
        line,
        account_currency=account_currency,
    )



def is_reasonable_year(year: int) -> bool:
    return 2000 <= year <= datetime.now().year + 1


def detect_document_year(text: str) -> int:
    """Detect the statement year from structural document-date evidence.

    Priority is given to statement metadata such as ``As at``, ``Statement
    Date``, ``Statement Period`` and ``Period Ending``. This prevents the
    current year, legal dates, form identifiers, or footer dates from
    overriding the actual statement year.

    The existing generic date-frequency fallback is preserved unchanged.
    """
    raw = normalize_arabic_digits(str(text or ""))

    month_names = (
        r"january|jan(?:uary)?|february|feb(?:ruary)?|march|mar(?:ch)?|"
        r"april|apr(?:il)?|may|june|jun(?:e)?|july|jul(?:y)?|"
        r"august|aug(?:ust)?|september|sept?(?:ember)?|"
        r"october|oct(?:ober)?|november|nov(?:ember)?|"
        r"december|dec(?:ember)?|"
        r"janvier|février|fevrier|mars|avril|mai|juin|juillet|"
        r"août|aout|septembre|octobre|novembre|décembre|decembre"
    )

    structural_patterns = [
        rf"\bas\s+at\s+\d{{1,2}}\s+(?:{month_names})\s+(20\d{{2}})\b",
        rf"\bstatement\s+date\s*[:|]?\s*"
        rf"(?:\d{{1,2}}\s+(?:{month_names})\s+)?(20\d{{2}})\b",
        rf"\b(?:statement\s+period|period\s+ending|period\s+ended)\b"
        rf"[^\n]{{0,120}}?\b(20\d{{2}})\b",
        rf"\b(?:date\s+du\s+relev[eé]|p[eé]riode\s+du\s+relev[eé]|"
        rf"fin\s+de\s+p[eé]riode)\b[^\n]{{0,120}}?\b(20\d{{2}})\b",
    ]

    for pattern in structural_patterns:
        match = re.search(pattern, raw, flags=re.IGNORECASE)
        if not match:
            continue

        year = int(match.group(1))
        if is_reasonable_year(year):
            return year

    years = []

    for match in re.findall(r"\b(20\d{2})-\d{2}-\d{2}\b", raw):
        year = int(match)
        if is_reasonable_year(year):
            years.append(year)

    for match in re.findall(r"\b(20\d{2})\d{4}\b", raw):
        year = int(match)
        if is_reasonable_year(year):
            years.append(year)

    for match in re.findall(r"\b\d{2}[./-]\d{2}[./-](20\d{2})\b", raw):
        year = int(match)
        if is_reasonable_year(year):
            years.append(year)

    for match in re.findall(r"\b\d{2}[./-]\d{2}[./-](\d{2})\b", raw):
        year = 2000 + int(match)
        if is_reasonable_year(year):
            years.append(year)

    if not years:
        return datetime.now().year

    return Counter(years).most_common(1)[0][0]


def remove_weekday_prefix(text: str) -> str:
    value = str(text or "").strip()

    weekday_aliases = [
        "lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche",
        "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
        "الاثنين", "الإثنين", "الثلاثاء", "الأربعاء", "الاربعاء",
        "الخميس", "الجمعة", "الجمعه", "السبت", "الأحد", "الاحد",
    ]

    aliases_pattern = "|".join(re.escape(alias) for alias in weekday_aliases)

    return re.sub(
        rf"^(?:{aliases_pattern}),?\s+",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()


def extract_day(value: str) -> int | None:
    match = re.search(r"\d{1,2}", normalize_arabic_digits(str(value or "")))

    if not match:
        return None

    day = int(match.group(0))

    if 1 <= day <= 31:
        return day

    return None


def extract_year(value: str) -> int | None:
    match = re.search(r"\d{2,4}", normalize_arabic_digits(str(value or "")))

    if not match:
        return None

    year = int(match.group(0))

    if year < 100:
        year += 2000

    if is_reasonable_year(year):
        return year

    return None


def parse_localized_date(text: str) -> str | None:
    normalized = normalize_arabic_digits(str(text or ""))
    normalized = remove_weekday_prefix(normalized)
    normalized = normalized.replace(".", " ")
    normalized = re.sub(r"[,،]+", " ", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip().lower()

    tokens = normalized.split()

    if len(tokens) >= 3:
        day = extract_day(tokens[0])
        month = MONTH_ALIASES.get(tokens[1])
        year = extract_year(tokens[2])

        if day and month and year:
            return f"{year}-{month}-{day:02d}"

    return None



def try_parse_date(raw: str):
    raw = raw.strip()

    formats = [
        "%Y-%m-%d",
        "%Y/%m/%d",
        "%Y.%m.%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d.%m.%Y",
        "%d/%m/%y",
        "%d-%m-%y",
        "%d.%m.%y",
        "%m/%d/%Y",
        "%m-%d-%Y",
        "%m.%d.%Y",
        "%m/%d/%y",
        "%m-%d-%y",
        "%m.%d.%y",
        "%d %b %Y",
        "%d %B %Y",
        "%d %b %y",
        "%d %B %y",
        "%d-%b-%Y",
        "%d-%B-%Y",
        "%d-%b-%y",
        "%d-%B-%y",
        "%b %d %Y",
        "%B %d %Y",
        "%b %d %y",
        "%B %d %y",
        "%b-%d-%Y",
        "%B-%d-%Y",
        "%b-%d-%y",
        "%B-%d-%y",
    ]

    for fmt in formats:
        try:
            parsed = datetime.strptime(raw, fmt)

            if is_reasonable_year(parsed.year):
                return parsed.date().isoformat()
        except ValueError:
            continue

    return None


def extract_date(
    line: str,
    default_year: int | None = None,
    prefer_us_date: bool = False,
):
    line = str(line or "")

    date_candidates = re.findall(
        r"\b(?:"
        r"\d{4}[-/.]\d{1,2}[-/.]\d{1,2}"
        r"|"
        r"\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}"
        r"|"
        r"\d{1,2}[- ](?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)[- ]\d{2,4}"
        r"|"
        r"(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)[- ]\d{1,2}[- ]\d{2,4}"
        r")\b",
        line,
        flags=re.IGNORECASE,
    )

    for raw_date in date_candidates:
        parsed = try_parse_date(raw_date)
        if parsed:
            return parsed

    iso_match = re.search(r"\b(\d{4}-\d{2}-\d{2})\b", line)

    if iso_match:
        try:
            parsed = datetime.strptime(iso_match.group(1), "%Y-%m-%d")
            if not is_reasonable_year(parsed.year):
                return None
            return parsed.date().isoformat()
        except ValueError:
            pass

    compact_match = re.search(r"\b(20\d{2})(\d{2})(\d{2})\b", line)

    if compact_match:
        try:
            parsed = datetime(
                int(compact_match.group(1)),
                int(compact_match.group(2)),
                int(compact_match.group(3)),
            )
            if not is_reasonable_year(parsed.year):
                return None
            return parsed.date().isoformat()
        except ValueError:
            return None

    compact_dmy_match = re.search(r"\b([0-3]\d)([0-1]\d)(20\d{2})\b", line)

    if compact_dmy_match:
        try:
            parsed = datetime(
                int(compact_dmy_match.group(3)),
                int(compact_dmy_match.group(2)),
                int(compact_dmy_match.group(1)),
            )
            if not is_reasonable_year(parsed.year):
                return None
            return parsed.date().isoformat()
        except ValueError:
            return None

    spaced_dmy_match = re.search(
        r"(?<!\d)([0-3]?\d)\s+([01]?\d)\s+(20\d{2})(?!\d)",
        line,
    )

    if spaced_dmy_match:
        day, month, year = spaced_dmy_match.groups()
        try:
            parsed = datetime(int(year), int(month), int(day))
            if is_reasonable_year(parsed.year):
                return parsed.date().isoformat()
        except ValueError:
            return None

    text_month_us_match = re.search(
        r"\b("
        r"jan|january|feb|february|mar|march|apr|april|may|"
        r"jun|june|jul|july|aug|august|sep|sept|september|"
        r"oct|october|nov|november|dec|december"
        r")\s+(\d{1,2})\s+(\d{2,4})\b",
        line,
        flags=re.IGNORECASE,
    )

    if text_month_us_match:
        month_key = text_month_us_match.group(1).lower()
        day = int(text_month_us_match.group(2))
        year = int(text_month_us_match.group(3))

        if year < 100:
            year += 2000

        month = int(MONTH_ALIASES[month_key])

        try:
            parsed = datetime(year, month, day)
            if not is_reasonable_year(parsed.year):
                return None
            return parsed.date().isoformat()
        except ValueError:
            return None

    text_month_match = re.search(
        r"\b(\d{1,2})\s+"
        r"(january|jan|february|feb|march|mar|april|apr|may|"
        r"june|jun|july|jul|august|aug|september|sept|sep|"
        r"october|oct|november|nov|december|dec)"
        r"\s+(\d{2,4})\b",
        line,
        flags=re.IGNORECASE,
    )

    if text_month_match:
        day = int(text_month_match.group(1))
        month_key = text_month_match.group(2).lower()
        year = int(text_month_match.group(3))

        if year < 100:
            year += 2000

        month = int(MONTH_ALIASES[month_key])

        try:
            parsed = datetime(year, month, day)
            if parsed.year < 2000 or parsed.year > datetime.now().year + 1:
                return None
            return parsed.date().isoformat()
        except ValueError:
            return None

    # Important: remove money amounts before detecting bank-table split dates.
    # Example: "10.09 PRLV ... 10.09 10,00"
    # The amount "10,00" must not be interpreted as a date-like pair.
    line_without_money = re.sub(
        r"(?<!\d)\d{1,3}(?:[ .]\d{3})*[,.]\d{2}(?!\d)",
        " ",
        line,
    )

    bank_table_dates = re.findall(
        r"(?<!\d)([0-3]?\d)\s+([01]?\d)(?!\d)",
        line_without_money,
    )

    if bank_table_dates:
        for day_text, month_text in reversed(bank_table_dates):
            day = int(day_text)
            month = int(month_text)

            year_match = re.search(r"\b(20\d{2})\b", line_without_money)
            year = int(year_match.group(1)) if year_match else (default_year or datetime.now().year)

            try:
                parsed = datetime(year, month, day)
                if is_reasonable_year(parsed.year):
                    return parsed.date().isoformat()
            except ValueError:
                continue

    match = re.search(
        r"\b(\d{2}[./-]\d{2}(?:[./-]\d{2,4})?)\b",
        line,
    )

    if not match:
        return None

    raw = match.group(1)

    dmy_formats_with_year = (
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d.%m.%Y",
        "%d/%m/%y",
        "%d-%m-%y",
        "%d.%m.%y",
    )

    us_formats_with_year = (
        "%m/%d/%Y",
        "%m-%d-%Y",
        "%m.%d.%Y",
        "%m/%d/%y",
        "%m-%d-%y",
        "%m.%d.%y",
    )

    formats_with_year = (
        us_formats_with_year + dmy_formats_with_year
        if prefer_us_date
        else dmy_formats_with_year + us_formats_with_year
    )

    for fmt in formats_with_year:
        try:
            parsed = datetime.strptime(raw, fmt)
            if not is_reasonable_year(parsed.year):
                return None
            return parsed.date().isoformat()
        except ValueError:
            continue

    formats_without_year = (
        "%d/%m",
        "%d-%m",
        "%d.%m",
    )

    for fmt in formats_without_year:
        try:
            parsed = datetime.strptime(raw, fmt)
            year = default_year or datetime.now().year
            parsed = parsed.replace(year=year)

            if not is_reasonable_year(parsed.year):
                return None

            return parsed.date().isoformat()
        except ValueError:
            continue

    return None

def is_date_only_line(
    line: str,
    default_year: int | None = None,
    prefer_us_date: bool = False,
) -> bool:
    if not extract_date(line, default_year=default_year, prefer_us_date=prefer_us_date):
        return False

    remaining = re.sub(
        r"\b\d{1,2}\s+"
        r"(january|jan|february|feb|march|mar|april|apr|may|"
        r"june|jun|july|jul|august|aug|september|sept|sep|"
        r"october|oct|november|nov|december|dec)"
        r"\s+\d{2,4}\b",
        "",
        line,
        flags=re.IGNORECASE,
    )

    remaining = re.sub(
        r"\b\d{4}-\d{2}-\d{2}\b",
        "",
        remaining,
    )

    remaining = re.sub(
        r"\b(?:[0-3]\d[0-1]\d20\d{2}|20\d{2}[0-1]\d[0-3]\d)\b",
        "",
        remaining,
    )

    remaining = re.sub(
        r"\b\d{2}[./-]\d{2}(?:[./-]\d{2,4})?\b",
        "",
        remaining,
    )

    return remaining.strip() == ""



def split_compact_multi_transaction_lines(
    lines: list[str],
    default_year: int | None = None,
    prefer_us_date: bool = False,
) -> list[str]:
    """Split compact OCR lines that contain multiple dated transactions.

    Some PDFs/OCR outputs compress several rows into one physical line, e.g.:
        01/03/2026 Salary +3200,00 02/03/2026 Carrefour -84,56

    This structural normalization is intentionally language-neutral and does
    not change French, English, or Arabic classification rules. It only turns
    compact non-Arab rows into normal one-transaction-per-line candidates so
    the existing parser can process them safely.
    """
    date_token_re = re.compile(
        r"(?<!\d)(?:"
        r"\d{4}-\d{2}-\d{2}"
        r"|\d{1,2}[./-]\d{1,2}[./-]\d{2,4}"
        r"|\d{1,2}[- ](?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)[- ]\d{2,4}"
        r"|(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)[- ]\d{1,2}[- ]\d{2,4}"
        r")(?!\d)",
        flags=re.IGNORECASE,
    )

    rebuilt: list[str] = []

    for line in lines:
        if is_statement_footer_or_verification_block(line):
            continue

        if is_arabic_text(line):
            rebuilt.append(line)
            continue

        matches = list(date_token_re.finditer(line))

        if len(matches) <= 1:
            rebuilt.append(line)
            continue

        prefix = line[:matches[0].start()].strip()

        if prefix:
            previous_needs_prefix = (
                rebuilt
                and extract_date(
                    rebuilt[-1],
                    default_year=default_year,  # noqa: F841
                    prefer_us_date=prefer_us_date,
                ) is not None
                and not re.search(MONEY_NUMBER_PATTERN, rebuilt[-1])
            )

            if previous_needs_prefix:
                rebuilt[-1] = f"{rebuilt[-1]} {prefix}".strip()
                debug_log(
                    "TX_DEBUG: compact_prefix_attached",
                    {"prefix": prefix, "combined": rebuilt[-1]},
                )

                for idx, match in enumerate(matches):
                    start = match.start()
                    end = matches[idx + 1].start() if idx + 1 < len(matches) else len(line)
                    segment = line[start:end].strip()

                    if segment:
                        rebuilt.append(segment)
                        debug_log(
                            "TX_DEBUG: compact_multi_tx_split",
                            {"segment": segment},
                        )

                continue
            else:
                first_segment = line[matches[0].start():matches[1].start()].strip()
                rebuilt.append(f"{prefix} {first_segment}".strip())
                debug_log(
                    "TX_DEBUG: compact_multi_tx_split",
                    {"segment": rebuilt[-1]},
                )

                start_index = 1
                for idx in range(start_index, len(matches)):
                    start = matches[idx].start()
                    end = matches[idx + 1].start() if idx + 1 < len(matches) else len(line)
                    segment = line[start:end].strip()

                    if segment:
                        rebuilt.append(segment)
                        debug_log(
                            "TX_DEBUG: compact_multi_tx_split",
                            {"segment": segment},
                        )

                continue

        for idx, match in enumerate(matches):
            start = match.start()
            end = matches[idx + 1].start() if idx + 1 < len(matches) else len(line)
            segment = line[start:end].strip()

            if segment:
                rebuilt.append(segment)
                debug_log(
                    "TX_DEBUG: compact_multi_tx_split",
                    {"segment": segment},
                )

    return rebuilt


def has_transaction_signal(
    line: str,
    default_year: int | None = None,
    prefer_us_date: bool = False,
) -> bool:
    if is_document_metadata_line(line):
        return False

    lower = line.lower()

    metadata_check = (
        lower
        .replace("5", "s")
        .replace("0", "o")
        .replace("1", "l")
    )

    metadata_balance_only = any(
        keyword in metadata_check
        for keyword in BALANCE_KEYWORDS
    )

    date_found = extract_date(
        line,
        default_year=default_year,  # noqa: F841
        prefer_us_date=prefer_us_date,
    ) is not None

    amounts = extract_money_numbers_safely(line)

    signed_amount_found = bool(
        re.search(
            r"[+-]\s*\d",
            line,
        )
    )

    if metadata_balance_only and not (
        date_found and (signed_amount_found or len(amounts) >= 2)
    ):
        return False

    amount_found = bool(amounts)

    signal_found = any(
        keyword in lower
        for keyword in TRANSACTION_SIGNALS
    )

    return date_found and amount_found and (
        signal_found or amount_found
    )



def is_income_priority_description(text: str) -> bool:
    """Return True for income phrases that must override broad expense words.

    This is intentionally general, not bank-specific. Many banks describe
    inbound cashflow with words that also appear in expense rows, for example
    "Salary Payment" or "Payment In". These income phrases must be
    evaluated before generic expense terms such as "payment" or "transfer".
    """
    lower = text.lower()
    unicode_normalized = unicodedata.normalize("NFKC", lower)
    arabic_normalized = normalize_arabic_ocr_lines(unicode_normalized)
    searchable = f"{lower} {unicode_normalized} {arabic_normalized}"

    priority_phrases = [
        "salary payment",
        "salary deposit",
        "salary credit",
        "payroll",
        "salary",
        "wage",
        "wages",
        "pay credit",
        "payment in",
        "payment received",
        "osko payment in",
        "incoming transfer",
        "transfer received",
        "transfer in",
        "deposit",
        "versement",
        "versement espece",
        "versement espèce",
        "versement espèces",
        "dépôt",
        "depot",
        "received",
        "refund",
        "rebate",
        "cashback",
        "اعادة",
        "إعادة",
        "اعاده",
        "إعاده",
        "استرجاع",
        "مرتجع",
        "مبلغ اعادة",
        "مبلغ إعادة",
        "remboursement",
        "retour carte",
        "freelance",
        "client",
        "virement reçu",
        "virement recu",
        "vir recu",
        "vir reçu",
        "vir inst recu",
        "vir inst reçu",
        "virement instantané reçu",
        "virement instantane recu",
        "virement sepa reçu",
        "virement sepa recu",
        "vir inst re",
        "wero de:",
        "wero de ",
        "vir.web recu",
        "vir.web reçu",
        "vir web recu",
        "vir web reçu",
        "vrst",
        "vrst ref",
        "recu de",
        "reçu de",
        "دائن",
        "إيداع",
        "ايداع",
        "راتب",
        "دخل",
        "تحويل وارد",
        "حوالة واردة",
    ]

    return any(phrase in searchable for phrase in priority_phrases)

def is_administrative_statement_line(text: str) -> bool:
    lower = text.lower()

    return any(
        marker in lower
        for marker in [
            # FR
            "relevé",
            "releve",
            "identité bancaire",
            "identite bancaire",
            "numéro de compte",
            "numero de compte",
            "rib",
            "extrait de compte",

            # EN
            "bank statement",
            "account number",
            "account details",
            "iban",
            "swift",
            "sort code",

            # AR
            "كشف حساب",
            "رقم الحساب",
            "رقم الحساب الرئيسي",
            "بيان الحساب",
            "رقم ريب",
        ]
    )


def is_universal_fee_tax_or_charge(description: str) -> bool:
    text = str(description or "").lower()

    return any(
        marker in text
        for marker in [
            # EN
            "tax", "vat", "gst", "hst", "duty", "withholding tax",
            "tax deduction", "vat deduction",
            "fee", "fees", "charge", "charges", "commission",
            "stamp duty", "stamp tax", "fiscal stamp",

            # FR
            "taxe", "tva", "impôt", "impot", "retenue",
            "déduction taxe", "deduction taxe", "déduction tva", "deduction tva",
            "frais", "commission",
            "droit de timbre", "timbre fiscal",

            # ES/PT/IT common
            "impuesto", "iva", "imposto", "imposta",
            "impuesto de timbre", "imposto de selo", "imposta di bollo",

            # DE/NL
            "steuer", "mwst", "gebühr", "gebuhr",

            # AR
            "ضريبة", "ضريبه", "الضريبة", "القيمة المضافة", "القيمه المضافه",
            "خصم ضريبة", "خصم ضريبه",
            "رسوم", "رسم", "عمولة",
            "رسم الطابع", "رسوم الطابع", "طابع مالي",
        ]
    )


def detect_type(line: str, amount: float) -> str | None:
    """
    Detect transaction direction using international FR / EN / AR rules.

    Priority:
        1. Explicit signed monetary value
        2. Explicit inbound/outbound phrases
        3. Universal fee/tax rules
        4. Universal keyword markers
        5. Already established negative amount
        6. Unknown

    Important:
        A positive unsigned amount never defaults to income.
        A neutral transfer never gets a direction without structural evidence.
    """
    import re

    text = str(line or "")
    lower = text.lower()

    try:
        numeric_amount = float(amount or 0)
    except (TypeError, ValueError):
        numeric_amount = 0.0

    # ------------------------------------------------------------
    # 1. Explicit signed monetary values
    # ------------------------------------------------------------
    #
    # Avoid interpreting hyphens inside ISO dates as negative signs.
    #
    signed_positive_amount = bool(
        re.search(
            r"(?<![\d/.\-])\+\s*"
            r"(?:\d{1,3}(?:[ ,]\d{3})+|\d+)"
            r"(?:[.,]\d{1,3})?",
            text,
        )
    )

    signed_negative_amount = bool(
        re.search(
            r"(?<![\d/.\-])-\s*"
            r"(?:\d{1,3}(?:[ ,]\d{3})+|\d+)"
            r"(?:[.,]\d{1,3})?",
            text,
        )
    )

    if signed_positive_amount and not signed_negative_amount:
        return "income"

    if signed_negative_amount and not signed_positive_amount:
        return "expense"

    # ------------------------------------------------------------
    # 2. Explicit inbound phrases
    # ------------------------------------------------------------
    #
    # Income expressions must be checked before broad words such as
    # "payment", "transfer", "credit" or "card".
    #
    explicit_income_markers = [
        # English
        "salary payment",
        "salary deposit",
        "salary credit",
        "salary transfer",
        "payroll",
        "wages",
        "wage payment",
        "incoming transfer",
        "transfer received",
        "payment received",
        "payment in",
        "received from",
        "cash deposit",
        "deposit received",
        "credit transfer received",
        "refund received",
        "cashback",
        "rebate",
        "interest credit",

        # French
        "salaire",
        "paie",
        "virement reçu",
        "virement recu",
        "virement entrant",
        "versement",
        "versement espèces",
        "versement especes",
        "dépôt",
        "depot",
        "remboursement",
        "retour carte",
        "intérêts créditeurs",
        "interets crediteurs",

        # Arabic
        "راتب",
        "إيداع",
        "ايداع",
        "تحويل وارد",
        "حوالة واردة",
        "تحويل مستلم",
        "مبلغ مستلم",
        "دائن",
        "استرداد",
        "مرتجع",
        "إعادة مبلغ",
        "اعادة مبلغ",
    ]

    if any(marker in lower for marker in explicit_income_markers):
        return "income"

    # Keep the existing centralized priority helper.
    if is_income_priority_description(lower):
        return "income"

    # ------------------------------------------------------------
    # 3. Explicit outbound phrases
    # ------------------------------------------------------------
    explicit_expense_markers = [
        # English
        "outgoing transfer",
        "transfer sent",
        "sent transfer",
        "transfer to",
        "payment to",
        "loan payment",
        "loan repayment",
        "mortgage payment",
        "rent payment",
        "card payment",
        "debit card purchase",
        "cash withdrawal",
        "atm withdrawal",
        "direct debit",
        "standing order",
        "bill payment",
        "purchase",
        "merchant payment",
        "service fee",
        "bank fee",
        "transfer fee",
        "commission charged",

        # French
        "virement émis",
        "virement emis",
        "virement sortant",
        "vir émis",
        "vir emis",
        "paiement carte",
        "paiement facture",
        "prélèvement",
        "prelevement",
        "retrait",
        "retrait dab",
        "achat",
        "loyer",
        "mensualité prêt",
        "mensualite pret",
        "remboursement prêt",
        "remboursement pret",
        "frais bancaires",
        "commission prélevée",
        "commission prelevee",

        # Arabic
        "تحويل صادر",
        "حوالة صادرة",
        "تحويل إلى",
        "تحويل الى",
        "دفع فاتورة",
        "دفع بطاقة",
        "شراء",
        "سحب",
        "سحب نقدي",
        "اقتطاع",
        "خصم مباشر",
        "مدين",
        "رسوم",
        "عمولة",
    ]

    if any(marker in lower for marker in explicit_expense_markers):
        return "expense"

    # ------------------------------------------------------------
    # 4. Taxes, fees and charges
    # ------------------------------------------------------------
    #
    # A fee reversal or tax refund has already been caught by the
    # income-priority rules above.
    #
    if is_universal_fee_tax_or_charge(lower):
        return "expense"

    if any(
        marker in lower
        for marker in [
            "vat",
            "tax",
            "tva",
            "taxe",
            "gst",
            "hst",
            "withholding tax",
            "ضريبة",
            "ضريبه",
            "القيمة المضافة",
            "القيمه المضافه",
        ]
    ):
        return "expense"

    # ------------------------------------------------------------
    # 5. Neutral transfer guard
    # ------------------------------------------------------------
    #
    # A generic word such as "transfer" is not enough to decide direction.
    #
    if looks_like_neutral_inbound_transfer(
        text,
        numeric_amount if numeric_amount > 0 else None,
    ):
        return None

    # ------------------------------------------------------------
    # 6. Universal multilingual marker sets
    # ------------------------------------------------------------
    #
    # Use the curated universal lists before the wider legacy lists.
    #
    if any(marker in lower for marker in UNIVERSAL_INCOME_MARKERS):
        return "income"

    if any(marker in lower for marker in UNIVERSAL_EXPENSE_MARKERS):
        return "expense"

    # ------------------------------------------------------------
    # 7. Legacy lists as conservative fallback
    # ------------------------------------------------------------
    #
    # Avoid broad ambiguous terms being used alone.
    #
    ambiguous_income_markers = {
        "credit",
        "client",
        "incoming",
        "received",
        "payment",
        "transfer",
    }

    ambiguous_expense_markers = {
        "payment",
        "card",
        "debit",
        "transfer",
        "bill",
        "market",
    }

    for keyword in INCOME_KEYWORDS:
        normalized_keyword = str(keyword or "").strip().lower()

        if not normalized_keyword:
            continue

        if normalized_keyword in ambiguous_income_markers:
            continue

        if normalized_keyword in lower:
            return "income"

    for keyword in EXPENSE_KEYWORDS:
        normalized_keyword = str(keyword or "").strip().lower()

        if not normalized_keyword:
            continue

        if normalized_keyword in ambiguous_expense_markers:
            continue

        if normalized_keyword in lower:
            return "expense"

    # ------------------------------------------------------------
    # 8. Preserve an already established negative sign
    # ------------------------------------------------------------
    #
    # This comes late because explicit semantic evidence is stronger than
    # a potentially provisional sign produced by an earlier parser.
    #
    if numeric_amount < 0:
        return "expense"

    # Positive unsigned values do not imply income.
    return None
def extract_transaction_amount(line: str) -> float | None:
    numbers = extract_transaction_money_numbers(line)

    if not numbers:
        return None

    signed_match = re.search(
        r"([+-])\s*("
        r"(?:\d{1,3}(?:[ ,]\d{3})+|\d+)"
        r"(?:[.,]\d{2,3})"
        r")",
        remove_short_bank_date_noise(normalize_line_for_amount_detection(line)),
    )

    if signed_match:
        amount = parse_terminal_amount(signed_match.group(2), line)
        return amount if signed_match.group(1) == "+" else -amount

    tx_amount, _balance = extract_terminal_amount_balance_pair(line)

    if tx_amount is not None:
        return tx_amount

    selected_token = select_transaction_money_token(numbers, line)
    if selected_token is not None:
        return parse_terminal_amount(selected_token, line)

    amount = parse_terminal_amount(numbers[0], line)

    # HOTFIX_V2_ZERO_AMOUNT_REPAIR:
    # Avoid accepting 0.0 when the line contains a visible non-zero amount.
    if amount == 0 and len(numbers) >= 1:
        parsed_candidates = []
        for token in numbers:
            try:
                value = parse_terminal_amount(token, line)
                if value != 0:
                    parsed_candidates.append(value)
            except Exception:
                pass
        if parsed_candidates:
            amount = max(parsed_candidates, key=lambda x: abs(x))

    return amount



def extract_us_debit_credit_balance(line: str):
    numbers = extract_money_numbers_safely(line)

    terminal_amount_balance = extract_terminal_amount_balance_pair(line)
    if terminal_amount_balance[0] is not None and terminal_amount_balance[1] is not None:
        return None, None

    if len(numbers) < 3:
        return None, None

    debit = parse_amount(numbers[-3])
    credit = parse_amount(numbers[-2])
    balance = parse_amount(numbers[-1])

    debug_log(
        "TX_DEBUG: us_debit_credit_balance",
        {"debit": debit, "credit": credit, "balance": balance},
    )

    if credit > 0 and debit == 0:
        return credit, "income"

    if debit > 0 and credit == 0:
        return -debit, "expense"

    return None, None


def extract_tabular_bank_amount(
    line: str,
) -> tuple[float | None, str | None]:
    if is_document_metadata_line(line):
        return None, None

    normalized = line.lower()

    NON_TRANSACTION_KEYWORDS = [
        "account number",
        "account holder",
        "account name",
        "customer name",
        "client name",
        "statement date",
        "statement period",
        "period",
        "date range",
        "periode",
        "période",
        "du ",
        " au ",
        "bank statement",
        "example bank",
        "iban",
        "swift",
        "sort code",
    ]

    if any(keyword in normalized for keyword in NON_TRANSACTION_KEYWORDS):
        return None, None

    if any(
        keyword in normalized
        for keyword in [
            "balance carried forward",
            "closing balance",
            "opening balance",
        ]
    ):
        return None, None

    # First-pass direction extraction on the original line.
    # This avoids losing valid international decimal amounts such as 15.00
    # when degraded OCR/date cleanup could confuse them with date-like tokens.
    original_dc_amount, original_dc_type = extract_debit_credit_from_description(line)

    if original_dc_amount is not None:
        debug_log(
            "TX_DEBUG: original_line_debit_credit_description",
            {"amount": original_dc_amount, "type": original_dc_type, "line": line},
        )
        return original_dc_amount, original_dc_type

    without_date = re.sub(
        r"\b\d{4}-\d{2}-\d{2}\b",
        "",
        line,
        count=1,
    )

    without_date = re.sub(
        r"\b(?:[0-3]\d[0-1]\d20\d{2}|20\d{2}[0-1]\d[0-3]\d)\b",
        "",
        without_date,
        count=1,
    )

    without_date = re.sub(
        r"\b\d{2}[./-]\d{2}(?:[./-]\d{2,4})?\b",
        "",
        without_date,
        count=1,
    )

    without_date = re.sub(
        r"\b\d{1,2}\s+"
        r"(january|jan|february|feb|march|mar|april|apr|may|"
        r"june|jun|july|jul|august|aug|september|sept|sep|"
        r"october|oct|november|nov|december|dec)"
        r"\s+\d{2,4}\b",
        "",
        without_date,
        count=1,
        flags=re.IGNORECASE,
    )


    numbers = extract_money_numbers_safely(without_date)

    if not numbers:
        return None, None

    dc_amount, dc_type = extract_debit_credit_from_description(line)

    if dc_amount is not None:
        debug_log(
            "TX_DEBUG: debit_credit_description",
            {"amount": dc_amount, "type": dc_type, "line": line},
        )
        return dc_amount, dc_type

    # General rule: when the statement shows an explicit + / - sign,
    # the sign is more reliable than generic words such as "payment".
    # Example: "Client Payment +7200.00" must be income, not expense.
    signed_match = re.search(
        r"([+-])\s*("
        r"(?:\d{1,3}(?:[ ,]\d{3})+|\d+)"
        r"(?:[.,]\d{2})"
        r")",
        line,
    )

    if signed_match:
        sign = signed_match.group(1)
        signed_amount = parse_amount(signed_match.group(2))

        debug_log(
            "TX_DEBUG: signed_amount_priority",
            {"sign": sign, "amount": signed_amount},
        )

        if sign == "+":
            return abs(signed_amount), "income"

        return -abs(signed_amount), "expense"

    tabular_us_amount, tabular_us_type = extract_us_debit_credit_balance(line)

    if tabular_us_amount is not None:
        return tabular_us_amount, tabular_us_type

    description = normalized

    if any(
        keyword in description
        for keyword in [
            "fx conversion",
            "fx exchange",
            "currency exchange",
            "currency conversion",
            "wallet credit",
            "wallet",
            "internal transfer",
        ]
    ):
        return None, None

    if any(
        keyword in description
        for keyword in [
            "retour carte",
            "refund",
            "reversal",
            "remboursement",
        ]
    ):
        amount = pick_transaction_amount_from_tabular_numbers(numbers, line)

        return amount, "income"

    # Income keywords must be evaluated before generic outgoing words such as
    # "payment". This is a general rule, not a bank-specific exception.
    if is_income_priority_description(description) or any(
        keyword in description for keyword in UNIVERSAL_INCOME_MARKERS
    ):
        amount = pick_transaction_amount_from_tabular_numbers(numbers, line)

        return abs(amount), "income"

    if any(keyword in description for keyword in UNIVERSAL_EXPENSE_MARKERS):
        amount = pick_transaction_amount_from_tabular_numbers(numbers, line)

        return -abs(amount), "expense"

    if any(
        keyword in description
        for keyword in [
            "atm",
            "visa",
            "card",
            "debit",
            "direct debit",
            "sepa direct debit",
            "prlv",
            "prlv sepa",
            "prel",
            "prel sepa",
            "prelevement",
            "prélèvement",
            "prelevement sepa",
            "prélèvement sepa",
            "standing order",
            "withdrawal",
            "payment",
            "purchase",
            "recurring",
            "fee",
            "card payment",
            "sepa direct debit",
            "outgoing transfer",
            "vir emis",
            "vir émis",
            "vir.emis",
            "vir emis web",
            "virement emis",
            "virement émis",
            "ticket",
            "e-ticket",
            "restaurant",
            "supermarket",
            "pharmacy",
            "pharmacie",
            "fuel",
            "uber",
            "transport",
            "rent",
            "arabic ocr transaction",
        ]
    ):
        amount = pick_transaction_amount_from_tabular_numbers(numbers, line)

        return -abs(amount), "expense"

    if any(
        keyword in description
        for keyword in [
            "incoming transfer",
            "transfer received",
            "virement reçu",
            "virement recu",
            "vir recu",
            "vir reçu",
            "vir inst recu",
            "vir inst reçu",
            "vir.web recu",
            "vir.web reçu",
            "vir web recu",
            "vir web reçu",
            "recu de",
            "reçu de",
            "salary",
            "payroll",
            "wage",
            "deposit",
            "received",
            "freelance",
            "client",
        ]
    ):
        amount = pick_transaction_amount_from_tabular_numbers(numbers, line)

        return amount, "income"

    # A neutral unsigned transfer has no reliable accounting direction.
    # Explicit inbound markers, signs, columns, or balance deltas are handled
    # earlier; without that evidence the row must remain untyped.
    if looks_like_neutral_inbound_transfer(line):
        return None, None

    return None, None


def extract_amount_balance_line(line: str):
    if is_document_metadata_line(line):
        return None, None

    # Use the terminal movement/balance pair, never the running balance.
    # This is the core international FR / EN / AR rule for table rows with
    # Debit/Credit/Balance or Amount/Balance columns.
    tx_amount, balance = extract_terminal_amount_balance_pair(line)

    if tx_amount is None or balance is None:
        return None, None

    debug_log(
        "TX_DEBUG: amount_balance_line",
        {"tx_amount": tx_amount, "balance": balance},
    )

    text = line.lower()

    if is_income_priority_description(text):
        return abs(tx_amount), "income"

    if any(k in text for k in EXPENSE_KEYWORDS):
        return -abs(tx_amount), "expense"

    if any(k in text for k in INCOME_KEYWORDS):
        return abs(tx_amount), "income"

    # General safety rule for rows shaped like:
    #     date description transaction_amount running_balance
    # The transaction amount is the penultimate money value and the balance is
    # the last money value. Never return the balance as the row amount.
    # Type can remain unknown here; infer_balance_delta_rows() can later use
    # the running balance delta to set income/expense safely.
    return abs(tx_amount), None


def extract_line_balance(line: str) -> float | None:
    """Return running balance only when a terminal movement/balance pair exists.

    This avoids treating a single visible amount, duplicated card amount, fee,
    VAT, or FX amount as a running balance.
    """
    _tx_amount, balance = extract_terminal_amount_balance_pair(line)

    return balance


def is_balance_only_line(
    line: str,
    default_year: int | None = None,
    prefer_us_date: bool = False,
) -> bool:
    """Return True for OCR lines that look like a standalone running balance.

    This supports vertical bank tables where OCR splits:
        date
        description
        transaction amount
        running balance

    into separate physical lines. We only treat a line as balance-only when:
    - it has no date;
    - it contains exactly one money value;
    - after removing that money value, no meaningful letters remain.

    This avoids merging normal transaction rows or metadata into the previous row.
    """
    if extract_date(
        line,
        default_year=default_year,  # noqa: F841
        prefer_us_date=prefer_us_date,
    ):
        return False

    amounts = re.findall(MONEY_NUMBER_PATTERN, line)

    if len(amounts) != 1:
        return False

    remainder = re.sub(
        MONEY_NUMBER_PATTERN,
        "",
        line,
    )

    remainder = re.sub(
        r"[\s|:;,\-–—_/()]+",
        "",
        remainder,
    )

    return remainder == ""


def is_amount_balance_only_row(
    line: str,
    default_year: int | None = None,
    prefer_us_date: bool = False,
) -> bool:
    if not extract_date(line, default_year=default_year, prefer_us_date=prefer_us_date):
        return False

    amounts = extract_money_numbers_safely(line)

    if len(amounts) != 2:
        return False

    cleaned = normalize_line_for_amount_detection(line)
    cleaned = re.sub(MONEY_NUMBER_PATTERN, " ", cleaned)
    cleaned = re.sub(r"[\s|:;,\-–—_/().]+", "", cleaned)

    return cleaned == ""


def attach_following_balance_lines(
    lines: list[str],
    default_year: int | None = None,
    prefer_us_date: bool = False,
) -> list[str]:
    """Attach OCR standalone balance lines to the previous transaction line.

    General case:
        2026-02-05 Interest Credit 9.85
        12,828.45

    becomes:
        2026-02-05 Interest Credit 9.85 12,828.45

    Then infer_balance_delta_rows() can use the balance delta as the authority.
    """
    rebuilt = []
    i = 0

    while i < len(lines):
        current = lines[i]

        current_has_date = extract_date(
            current,
            default_year=default_year,  # noqa: F841
            prefer_us_date=prefer_us_date,
        ) is not None

        current_amounts = extract_money_numbers_safely(current)

        if (
            current_has_date
            and current_amounts
            and i + 1 < len(lines)
            and is_balance_only_line(
                lines[i + 1],
                default_year=default_year,  # noqa: F841
                prefer_us_date=prefer_us_date,
            )
        ):
            combined = f"{current} {lines[i + 1]}"

            debug_log(
                "TX_DEBUG: vertical_balance_attached",
                {
                    "transaction_line": current,
                    "balance_line": lines[i + 1],
                    "combined": combined,
                },
            )

            rebuilt.append(combined)
            i += 2
            continue

        rebuilt.append(current)
        i += 1

    return rebuilt



def _coerce_optional_money(value) -> float | None:
    """Return a finite rounded monetary value, or None."""
    if value in (None, ""):
        return None

    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return None

    if not math.isfinite(parsed):
        return None

    return round(parsed, 2)


def _explicit_column_signed_amount(tx: dict) -> tuple[float | None, str | None]:
    """Resolve sign only from explicit Debit/Credit-style columns.

    Supported structural aliases:
    - debit / debit_amount / withdrawal / withdrawals
    - credit / credit_amount / deposit / deposits

    Description keywords are deliberately ignored.
    """
    debit_keys = (
        "debit_amount",
        "debit",
        "withdrawal_amount",
        "withdrawal",
        "withdrawals",
    )
    credit_keys = (
        "credit_amount",
        "credit",
        "deposit_amount",
        "deposit",
        "deposits",
    )

    debit = next(
        (
            _coerce_optional_money(tx.get(key))
            for key in debit_keys
            if _coerce_optional_money(tx.get(key)) is not None
        ),
        None,
    )
    credit = next(
        (
            _coerce_optional_money(tx.get(key))
            for key in credit_keys
            if _coerce_optional_money(tx.get(key)) is not None
        ),
        None,
    )

    debit = abs(debit) if debit not in (None, 0) else None
    credit = abs(credit) if credit not in (None, 0) else None

    if debit is not None and credit is None:
        return round(-debit, 2), "debit_column"

    if credit is not None and debit is None:
        return round(credit, 2), "credit_column"

    return None, None


def _lock_transaction(
    tx: dict,
    signed_amount: float,
    *,
    classification_source: str,
    balance_authority: bool,
    balance_delta: float | None = None,
) -> dict:
    """Apply the permanent transaction lock contract."""
    signed = round(float(signed_amount), 2)
    tx_type = "income" if signed > 0 else "expense"

    tx["amount"] = signed
    tx["signed_amount"] = signed
    tx["type"] = tx_type
    tx["locked_amount"] = signed
    tx["_locked_amount"] = signed
    tx["locked_type"] = tx_type
    tx["classification_source"] = classification_source
    tx["_balance_locked"] = bool(balance_authority)
    tx["balance_authority"] = bool(balance_authority)

    if balance_delta is not None:
        tx["balance_delta"] = round(float(balance_delta), 2)

    return tx


def lock_transaction_from_balance_delta(
    tx: dict,
    previous_balance: float | None,
    current_balance: float | None,
) -> dict:
    """Lock sign and type from the running-balance equation.

    International authority:

        previous_balance + signed_movement = current_balance

    The visible movement amount must reconcile with the balance delta.
    No bank, country, currency, language, or merchant rule is used.
    """
    previous = _coerce_optional_money(previous_balance)
    current = _coerce_optional_money(current_balance)

    if previous is None or current is None:
        return tx

    visible_candidates = (
        tx.get("visible_amount"),
        tx.get("amount"),
        tx.get("locked_amount"),
        tx.get("_locked_amount"),
    )
    amount_abs = None

    for candidate in visible_candidates:
        parsed = _coerce_optional_money(candidate)
        if parsed not in (None, 0):
            amount_abs = abs(parsed)
            break

    if amount_abs is None:
        return tx

    delta = round(current - previous, 2)
    tolerance = max(0.02, amount_abs * 0.002)

    if abs(abs(delta) - amount_abs) > tolerance:
        tx["balance_delta_mismatch"] = True
        tx["observed_balance_delta"] = delta
        tx["visible_amount"] = round(amount_abs, 2)
        return tx

    tx.pop("balance_delta_mismatch", None)
    tx.pop("observed_balance_delta", None)

    return _lock_transaction(
        tx,
        delta,
        classification_source="balance_delta",
        balance_authority=True,
        balance_delta=delta,
    )


def is_balance_locked_transaction(tx: dict) -> bool:
    """Return True only for a complete balance-authority lock."""
    return bool(
        tx.get("_balance_locked")
        and tx.get("balance_authority")
        and tx.get("locked_type") in {"income", "expense"}
        and tx.get("locked_amount") is not None
    )


def preserve_balance_locked_transaction(tx: dict) -> dict:
    """Restore every immutable field of a balance-authoritative row."""
    if not is_balance_locked_transaction(tx):
        return tx

    locked_type = tx.get("locked_type")
    locked_amount = _coerce_optional_money(
        tx.get("_locked_amount", tx.get("locked_amount"))
    )

    if locked_type not in {"income", "expense"} or locked_amount is None:
        return tx

    signed = abs(locked_amount) if locked_type == "income" else -abs(locked_amount)

    tx["amount"] = round(signed, 2)
    tx["signed_amount"] = round(signed, 2)
    tx["type"] = locked_type
    tx["locked_amount"] = round(signed, 2)
    tx["_locked_amount"] = round(signed, 2)
    tx["locked_type"] = locked_type
    tx["classification_source"] = "balance_delta"
    tx["_balance_locked"] = True
    tx["balance_authority"] = True

    return tx


def apply_explicit_debit_credit_authority(tx: dict) -> dict:
    """Apply explicit Debit/Credit or Withdrawals/Deposits authority.

    Explicit accounting columns establish sign before any semantic stage.
    They are not marked as balance-authoritative until the running balance
    independently confirms the same movement.
    """
    fixed = dict(tx)
    signed, source = _explicit_column_signed_amount(fixed)

    if signed is None or source is None:
        return fixed

    fixed = _lock_transaction(
        fixed,
        signed,
        classification_source=source,
        balance_authority=False,
    )
    fixed["_explicit_column_locked"] = True
    return fixed


def detect_statement_transaction_order(
    rows: list[dict],
) -> str:
    """Detect ascending or descending physical transaction order.

    Equal dates are neutral votes. The function observes only normalized
    transaction dates and never inspects bank, country, language, or currency.
    """
    dated_positions: list[tuple[int, datetime]] = []

    for index, row in enumerate(rows or []):
        if not isinstance(row, dict):
            continue

        raw_date = str(row.get("date") or "").strip()
        if not raw_date:
            continue

        try:
            parsed_date = datetime.strptime(raw_date[:10], "%Y-%m-%d")
        except (TypeError, ValueError):
            continue

        dated_positions.append((index, parsed_date))

    if len(dated_positions) < 2:
        return "unknown"

    ascending_votes = 0
    descending_votes = 0

    for (_, previous_date), (_, current_date) in zip(
        dated_positions,
        dated_positions[1:],
    ):
        if current_date > previous_date:
            ascending_votes += 1
        elif current_date < previous_date:
            descending_votes += 1

    if ascending_votes > descending_votes:
        return "ascending"

    if descending_votes > ascending_votes:
        return "descending"

    return "unknown"


# Explicit accounting roles that must participate in balance continuity
# but must never be converted into transaction movements.
#
# Compatibility contract:
# - only rows that explicitly declare one of these roles are affected;
# - historical parsers that do not emit row_role/role remain unchanged.
_NON_TRANSACTION_ACCOUNTING_ROLES = frozenset({
    "HEADER",
    "CONTINUATION",
    "BALANCE",
    "TOTAL",
    "SUMMARY",
    "FOOTER",
    "LEGAL",
})


def _accounting_observation_role(row: dict) -> str:
    if not isinstance(row, dict):
        return ""

    return str(
        row.get("row_role")
        or row.get("role")
        or ""
    ).strip().upper()


def _is_explicit_non_transaction_observation(row: dict) -> bool:
    """Return True only for an explicitly classified non-transaction row.

    This function is intentionally conservative. Missing roles do not trigger
    filtering, preserving every historical parser path.
    """
    if not isinstance(row, dict):
        return True

    role = _accounting_observation_role(row)

    if role in _NON_TRANSACTION_ACCOUNTING_ROLES:
        return True

    balance_role = str(
        row.get("balance_role") or ""
    ).strip().lower()

    return balance_role in {"opening", "closing"}


def _apply_explicit_authority_to_transaction_observation(row: dict) -> dict:
    """Apply Debit/Credit authority only to transaction observations."""
    copied = dict(row)

    if _is_explicit_non_transaction_observation(copied):
        return copied

    return apply_explicit_debit_credit_authority(copied)


def infer_balance_delta_rows(rows: list[dict]) -> list[dict]:
    """Apply explicit columns and running-balance authority in accounting order.

    Priority:
    1. explicit Debit/Credit or Withdrawals/Deposits columns;
    2. running-balance reconciliation;
    3. conservative recovery from already locked accounting fields;
    4. no semantic sign guess.

    Descending statements are temporarily reversed, then restored to their
    original physical display order.
    """
    if not rows:
        return []

    original_rows = [
        _apply_explicit_authority_to_transaction_observation(row)
        for row in rows
        if isinstance(row, dict)
    ]

    if not original_rows:
        return []

    statement_order = detect_statement_transaction_order(original_rows)

    accounting_rows = (
        list(reversed(original_rows))
        if statement_order == "descending"
        else list(original_rows)
    )

    previous_balance: float | None = None
    processed_rows: list[dict] = []

    # ------------------------------------------------------------------
    # PASS 1
    # Existing authoritative behavior.
    # ------------------------------------------------------------------
    for index, original_row in enumerate(accounting_rows):
        row = preserve_balance_locked_transaction(dict(original_row))

        current_balance = _coerce_optional_money(
            row.get("_balance", row.get("balance"))
        )

        if previous_balance is None:
            previous_balance = _coerce_optional_money(
                row.get("_opening_balance")
            )

        is_non_transaction_observation = (
            _is_explicit_non_transaction_observation(row)
        )

        if (
            not is_non_transaction_observation
            and current_balance is not None
            and previous_balance is not None
        ):
            delta = round(current_balance - previous_balance, 2)

            explicit_signed, explicit_source = (
                _explicit_column_signed_amount(row)
            )

            if explicit_signed is not None:
                tolerance = max(
                    0.02,
                    abs(explicit_signed) * 0.002,
                )

                if abs(delta - explicit_signed) <= tolerance:
                    row = _lock_transaction(
                        row,
                        delta,
                        classification_source="balance_delta",
                        balance_authority=True,
                        balance_delta=delta,
                    )
                    row["_explicit_column_locked"] = True
                    row["explicit_column_source"] = explicit_source

                else:
                    # Explicit columns remain authoritative.
                    # Record the reconciliation mismatch without changing
                    # their accounting direction.
                    row = apply_explicit_debit_credit_authority(row)
                    row["balance_reconciliation_error"] = True
                    row["expected_balance_delta"] = delta

            else:
                row = lock_transaction_from_balance_delta(
                    row,
                    previous_balance,
                    current_balance,
                )

        if current_balance is not None:
            previous_balance = current_balance

        processed_rows.append(
            preserve_balance_locked_transaction(row)
        )

    # ------------------------------------------------------------------
    # PASS 2
    # Additive normalization.
    #
    # Recover canonical amount fields from accounting fields that may
    # already have been locked by another structural layer.
    #
    # This pass never derives direction from transaction wording.
    # ------------------------------------------------------------------
    normalized_rows: list[dict] = []

    for original_row in processed_rows:
        row = preserve_balance_locked_transaction(dict(original_row))

        if _is_explicit_non_transaction_observation(row):
            normalized_rows.append(row)
            continue

        amount = _coerce_optional_money(row.get("amount"))
        signed_amount = _coerce_optional_money(
            row.get("signed_amount")
        )

        locked_amount = _coerce_optional_money(
            row.get(
                "locked_amount",
                row.get(
                    "_locked_amount",
                    row.get("_balance_locked_amount"),
                ),
            )
        )

        # A locked signed value is authoritative.
        if signed_amount is None and locked_amount is not None:
            signed_amount = locked_amount
            row["signed_amount"] = locked_amount

        # Keep the existing signed convention when amount itself is signed.
        if signed_amount is None and amount is not None:
            tx_type = str(row.get("type") or "").strip().lower()

            if amount < 0:
                signed_amount = amount
                row["signed_amount"] = amount

            elif tx_type == "income":
                signed_amount = abs(amount)
                row["signed_amount"] = signed_amount

            elif tx_type == "expense":
                signed_amount = -abs(amount)
                row["signed_amount"] = signed_amount

        # Some standardizers expect amount to be present even when
        # signed_amount is the primary accounting value.
        if amount is None and signed_amount is not None:
            row["amount"] = signed_amount
            amount = signed_amount

        # Keep type synchronized only when the signed value is already
        # structurally known.
        if signed_amount is not None:
            if signed_amount > 0:
                row["type"] = "income"
            elif signed_amount < 0:
                row["type"] = "expense"

        normalized_rows.append(
            preserve_balance_locked_transaction(row)
        )

    processed_rows = normalized_rows

    # ------------------------------------------------------------------
    # PASS 3
    # Conservative second balance pass.
    #
    # This only helps when an earlier row lacked a usable previous balance
    # during pass 1 but the accounting chain has since been normalized.
    # Existing locked rows are preserved.
    # ------------------------------------------------------------------
    previous_balance = None
    recovered_rows: list[dict] = []

    for original_row in processed_rows:
        row = preserve_balance_locked_transaction(dict(original_row))

        current_balance = _coerce_optional_money(
            row.get("_balance", row.get("balance"))
        )

        if previous_balance is None:
            previous_balance = _coerce_optional_money(
                row.get("_opening_balance")
            )

        existing_signed = _coerce_optional_money(
            row.get("signed_amount")
        )

        existing_locked = _coerce_optional_money(
            row.get(
                "locked_amount",
                row.get("_locked_amount"),
            )
        )

        explicit_signed, explicit_source = (
            _explicit_column_signed_amount(row)
        )

        # Never overwrite an already resolved transaction.
        unresolved = (
            existing_signed is None
            and existing_locked is None
        )

        is_non_transaction_observation = (
            _is_explicit_non_transaction_observation(row)
        )

        if (
            not is_non_transaction_observation
            and unresolved
            and current_balance is not None
            and previous_balance is not None
        ):
            delta = round(current_balance - previous_balance, 2)

            if explicit_signed is not None:
                tolerance = max(
                    0.02,
                    abs(explicit_signed) * 0.002,
                )

                if abs(delta - explicit_signed) <= tolerance:
                    row = _lock_transaction(
                        row,
                        delta,
                        classification_source="balance_delta",
                        balance_authority=True,
                        balance_delta=delta,
                    )
                    row["_explicit_column_locked"] = True
                    row["explicit_column_source"] = explicit_source

                else:
                    row = apply_explicit_debit_credit_authority(row)
                    row["balance_reconciliation_error"] = True
                    row["expected_balance_delta"] = delta

            elif abs(delta) >= 0.005:
                row = lock_transaction_from_balance_delta(
                    row,
                    previous_balance,
                    current_balance,
                )

        row = preserve_balance_locked_transaction(row)

        # Final canonical synchronization after the retry.
        # Explicit non-transaction observations remain neutral.
        if not is_non_transaction_observation:
            signed_amount = _coerce_optional_money(
                row.get("signed_amount")
            )

            if signed_amount is None:
                signed_amount = _coerce_optional_money(
                    row.get(
                        "locked_amount",
                        row.get("_locked_amount"),
                    )
                )

                if signed_amount is not None:
                    row["signed_amount"] = signed_amount

            if (
                _coerce_optional_money(row.get("amount")) is None
                and signed_amount is not None
            ):
                row["amount"] = signed_amount

            if signed_amount is not None:
                if signed_amount > 0:
                    row["type"] = "income"
                elif signed_amount < 0:
                    row["type"] = "expense"

        if current_balance is not None:
            previous_balance = current_balance

        recovered_rows.append(
            preserve_balance_locked_transaction(row)
        )

    processed_rows = recovered_rows

    if statement_order == "descending":
        processed_rows.reverse()

    # Additive output boundary:
    # balance/summary/legal observations informed the accounting chain above,
    # but they are not transaction records. Rows without an explicit role keep
    # the historical behavior unchanged.
    transaction_rows = [
        row
        for row in processed_rows
        if not _is_explicit_non_transaction_observation(row)
    ]

    return transaction_rows

def extract_first_amount_after_date(line: str) -> float | None:
    text = re.sub(
        r"\b\d{4}-\d{2}-\d{2}\b",
        "",
        line,
        count=1,
    )

    text = re.sub(
        r"\b(?:[0-3]\d[0-1]\d20\d{2}|20\d{2}[0-1]\d[0-3]\d)\b",
        "",
        text,
        count=1,
    )


    tx_amount, _balance = extract_terminal_amount_balance_pair(line)

    if tx_amount is not None:
        return tx_amount

    numbers = extract_money_numbers_safely(text)

    if not numbers:
        return None

    if len(numbers) >= 3:
        return parse_terminal_amount(numbers[-2], line)

    return parse_terminal_amount(numbers[-1], line)


def normalize_arabic_digits(value: str) -> str:
    return value.translate(
        str.maketrans(
            "٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹",
            "01234567890123456789",
        )
    )




