def apply_mercury_internal_transfer_guard(transactions: list[dict]) -> list[dict]:
    for tx in transactions or []:
        desc = str(tx.get("description") or "").lower()
        tx_type_raw = str(tx.get("type") or "").lower()

        is_mercury_internal = (
            "mercury checking" in desc
            and (
                "transfer from" in desc
                or "transfer to" in desc
                or tx_type_raw in {"transfer in", "transfer out", "transfer"}
            )
        )

        if is_mercury_internal:
            tx["type"] = "transfer"
            tx["is_internal_transfer"] = True
            tx["excluded_from_financial_kpis"] = True
            tx["exclude_from_income"] = True
            tx["exclude_from_expense"] = True
            tx["exclude_from_score"] = True
            tx["exclude_from_savings"] = True
            tx["exclude_from_cashflow"] = True
            tx["excluded_reason"] = "mercury_own_account_transfer"

    return transactions




def debug_print_finance_transactions_for_audit(transactions: list[dict]) -> list[dict]:
    print("FINANCE_TX_DEBUG_START", {"count": len(transactions or [])})
    for i, tx in enumerate(transactions or []):
        print("FINANCE_TX_DEBUG", {
            "i": i,
            "date": tx.get("date"),
            "description": tx.get("description"),
            "type": tx.get("type"),
            "amount": tx.get("amount"),
            "signed_amount": tx.get("signed_amount"),
            "excluded_from_financial_kpis": tx.get("excluded_from_financial_kpis"),
            "excluded_reason": tx.get("excluded_reason"),
            "is_internal_transfer": tx.get("is_internal_transfer"),
        })
    print("FINANCE_TX_DEBUG_END")
    return transactions




def extract_snb_arabic_statement_summary(text: str) -> dict:
    """
    SNB / AlAhli Arabic statement summary fallback.

    Fixes the case where the generic summary reads الرصيد السابق
    as both deposits and withdrawals.

    Uses transaction ledger rows:
    - ايداع رواتب / PAYROLL = deposit
    - purchase, transfer out, SADAD, loan installment, fees/VAT = withdrawals
    - الرصيد السابق is opening balance, not income
    """
    import re

    raw = str(text or "")
    compact = raw.replace("\u200f", "").replace("\u200e", "")

    has_arabic_ledger_structure = (
        ("Account Currency" in compact or "Date Transaction Type Description Credit Debit Balance" in compact)
        and ("ﺭﻳﺎﻝ" in compact or "ريال" in compact or "SAR" in compact)
        and (
            "PAYROLL" in compact
            or "SAMASARI" in compact
            or "ﺭﻭﺍﺗﺐ" in compact
            or "ايداع رواتب" in compact
            or "ﺣﻮﺍﻟﻪ" in compact
            or "حواله" in compact
        )
    )

    if not has_arabic_ledger_structure:
        return {}

    money = r"(?:\d{1,3}(?:,\d{3})+|\d+)(?:[.,]\d{2})"

    def amount(x):
        return float(str(x).replace(",", ""))

    opening_balance = None
    m_open = re.search(rf"(?:الرصيد السابق|ﺍﻟﺮﺻﻴﺪ\s*ﺍﻟﺴﺎﺑﻖ|ﺍﻟﺴﺎﺑﻖ)\s*({money})|({money})\s*(?:الرصيد السابق|ﺍﻟﺮﺻﻴﺪ\s*ﺍﻟﺴﺎﺑﻖ|ﺍﻟﺴﺎﺑﻖ)", compact)
    if m_open:
        opening_balance = amount(m_open.group(1) or m_open.group(2))

    deposits = 0.0
    withdrawals = 0.0  # noqa: F841

    for line in compact.splitlines():
        s = " ".join(line.split())
        if not s:
            continue

        nums = re.findall(money, s)
        if len(nums) < 2:
            continue

        movement = amount(nums[-2])

        is_header_noise = any(x in s for x in [
            "STATEMENT DATE",
            "Account Number",
            "Account Currency",
            "Date Transaction Type",
            "الرصيد السابق",
            "ﺍﻟﺮﺻﻴﺪ",
            "Page ",
        ])

        if is_header_noise:
            continue

        is_deposit = any(x in s for x in [
            "ايداع رواتب",
            "ﺭﻭﺍﺗﺐ ﺍﻳﺪﺍﻉ",
            "PAYROLL",
            "SAMASARI",
        ])

        if is_deposit:
            deposits += movement
        else:
            withdrawals += movement

    result = {
        "deposits": round(deposits, 2),
        "withdrawals": round(withdrawals, 2),
    }

    if opening_balance is not None:
        result["opening_balance"] = round(opening_balance, 2)

    return result




def extract_official_statement_movement_summary(text: str) -> dict:
    """
    Standard movement-summary extractor.

    Works for statements that expose:
    STARTING BALANCE TOTAL CREDITS TOTAL DEBITS END BALANCE
    7,808.58 + 30,839.84 - 38,647.75 = 0.67

    This is bank-neutral: it uses official movement totals when present.
    """
    import re

    raw = " ".join(str(text or "").replace("\n", " ").split())

    if not all(k in raw.upper() for k in [
        "STARTING BALANCE",
        "TOTAL CREDITS",
        "TOTAL DEBITS",
        "END BALANCE",
    ]):
        return {}

    money = r"(?:\d{1,3}(?:,\d{3})+|\d+)(?:[.,]\d{2})"

    m = re.search(
        rf"STARTING BALANCE\s+TOTAL CREDITS\s+TOTAL DEBITS\s+END BALANCE.*?"
        rf"({money})\s*\+\s*({money})\s*-\s*({money})\s*=\s*({money})",
        raw,
        flags=re.IGNORECASE,
    )

    if not m:
        return {}

    def amt(x):
        return round(float(str(x).replace(",", "")), 2)

    return {
        "opening_balance": amt(m.group(1)),
        "deposits": amt(m.group(2)),
        "withdrawals": amt(m.group(3)),
        "ending_balance": amt(m.group(4)),
    }




def extract_cbq_running_balance_summary(text: str) -> dict:
    import re
    raw = str(text or "")
    raw_upper = raw.upper()
    if not (
        "BROUGHT FORWARD" in raw_upper
        and "POSTING DATE" in raw_upper
        and "DEBIT" in raw_upper
        and "CREDIT" in raw_upper
        and "BALANCE" in raw_upper
    ):
        return {}

    money = r"(?:\d{1,3}(?:,\d{3})+|\d+)\.\d{2}"
    def amt(x): return round(float(str(x).replace(",", "")), 2)

    open_m = re.search(rf"BROUGHT FORWARD\s+({money})", raw)
    end_m = re.search(rf"\*\s*CREDIT BALANCE\s+({money})", raw)

    prev = amt(open_m.group(1)) if open_m else None
    opening = prev
    deposits = 0.0
    withdrawals = 0.0
    matched_movements = 0

    for line in raw.splitlines():
        s = " ".join(line.split())
        m = re.match(rf"^\d{{2}}-[A-Za-z]{{3}}-\d{{2}}\s+({money})\s+({money})$", s)
        if not m or prev is None:
            continue
        movement = amt(m.group(1))
        bal = amt(m.group(2))
        delta = round(bal - prev, 2)
        if abs(abs(delta) - movement) <= 0.05:
            if delta > 0:
                deposits += abs(delta)
            else:
                withdrawals += abs(delta)
            prev = bal
            matched_movements += 1

    ending = amt(end_m.group(1)) if end_m else None

    # ADDITIVE v184.5 — source flow totals are authoritative only when the
    # compact running-balance observations form a COMPLETE chain from the
    # independently printed opening balance to the independently printed
    # closing balance.
    #
    # Partial physical-text representations are common for multiline tables.
    # In those cases the accumulator may be 0.00 or a partial subtotal. Neither
    # is evidence of an official debit/credit total. Preserve opening/closing
    # anchors, but leave deposits/withdrawals unavailable unless the observed
    # chain reaches the printed closing balance.
    complete_flow_chain = bool(
        matched_movements > 0
        and ending is not None
        and prev is not None
        and abs(round(prev - ending, 2)) <= 0.05
    )

    out = {
        "opening_balance": opening,
    }

    if complete_flow_chain:
        out["deposits"] = round(deposits, 2)
        out["withdrawals"] = round(withdrawals, 2)
    else:
        print(
            "RUNNING_BALANCE_SUMMARY_FLOW_TOTALS_UNAVAILABLE",
            {
                "reason": (
                    "compact_flow_chain_does_not_reach_printed_closing_balance"
                ),
                "matched_movements": matched_movements,
                "opening_balance": opening,
                "last_observed_balance": prev,
                "ending_balance": ending,
                "partial_deposits": round(deposits, 2),
                "partial_withdrawals": round(withdrawals, 2),
                "deposits_published": False,
                "withdrawals_published": False,
            },
        )

    if ending is not None:
        out["ending_balance"] = ending

    return out





def extract_credit_card_statement_summary(text: str) -> dict:
    """
    Standard credit-card statement summary.

    EN/FR/AR compatible by structure:
    - Previous Balance / Solde précédent
    - Payments and Other Credits / Paiements et crédits
    - Purchases and Adjustments / Achats et ajustements
    - New Balance Total / Nouveau solde

    For KPI:
    - payments/credits are income/credits
    - purchases/fees/interest are expenses/debits
    """
    import re

    raw = " ".join(str(text or "").replace("\n", " ").split())
    low = raw.lower()  # noqa: F841

    has_credit_card_structure = (
        ("previous balance" in low or "solde précédent" in low or "solde precedent" in low)
        and (
            "payments and other credits" in low
            or "payments & other credits" in low
            or "paiements et crédits" in low
            or "paiements et credits" in low
        )
        and (
            "purchases and adjustments" in low
            or "achats et ajustements" in low
            or "purchases" in low
        )
        and ("new balance" in low or "nouveau solde" in low)
    )

    if not has_credit_card_structure:
        return {}

    money = r"-?\$?\s*(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{2})"

    def find_amount(labels):
        for label in labels:
            m = re.search(label + r"\s*(" + money + r")", raw, flags=re.I)
            if m:
                return round(abs(parse_amount(m.group(1))), 2)
        return None

    opening = find_amount([
        r"Previous Balance",
        r"Solde précédent",
        r"Solde precedent",
    ])

    credits = find_amount([
        r"Payments and Other Credits",
        r"Payments\s*&\s*Other Credits",
        r"Paiements et crédits",
        r"Paiements et credits",
    ])

    purchases = find_amount([
        r"Purchases and Adjustments",
        r"Achats et ajustements",
    ])

    fees = find_amount([
        r"Fees Charged",
        r"Frais facturés",
        r"Frais factures",
    ]) or 0.0

    interest = find_amount([
        r"Interest Charged",
        r"Intérêts facturés",
        r"Interets factures",
    ]) or 0.0

    ending = find_amount([
        r"New Balance Total",
        r"New Balance",
        r"Nouveau solde",
    ])

    if signed_debit_bucket_total > 0:
        withdrawals = round(signed_debit_bucket_total, 2)  # noqa: F841

    out = {}
    if opening is not None:
        out["opening_balance"] = opening
    if credits is not None:
        out["deposits"] = credits
    if purchases is not None:
        out["withdrawals"] = round(purchases + fees + interest, 2)
    if ending is not None:
        out["ending_balance"] = ending

    return out




def extract_standard_checking_statement_summary(text: str) -> dict:
    """
    Standard checking/current account summary extractor.

    Works for statement summaries such as:
    Beginning Balance
    Deposits and Additions
    ATM & Debit Card Withdrawals
    Ending Balance

    Generic principle:
    - opening/start/beginning balance => opening_balance
    - deposits/money in/credits/additions => deposits
    - withdrawals/money out/debits/payments => withdrawals
    - ending/end/closing balance => ending_balance
    """
    import re

    raw = " ".join(str(text or "").replace("\n", " ").split())
    low = raw.lower()  # noqa: F841

    if not (
        ("beginning balance" in low or "start balance" in low or "opening balance" in low)
        and ("ending balance" in low or "end balance" in low or "closing balance" in low)
        and (
            "deposits and additions" in low
            or "money in" in low
            or "total credits" in low
            or "credit" in low
        )
        and (
            "withdrawals" in low
            or "money out" in low
            or "total debits" in low
            or "debit" in low
        )
    ):
        return {}

    money = r"-?\$?\£?\€?\s*(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{2})"

    def clean(x):
        return round(abs(parse_amount(x)), 2)

    def find_amount(labels):
        for label in labels:
            m = re.search(
                label + r"\s+(" + money + r")(?P<credit_marker>\s*Cr\b)?",
                raw,
                flags=re.I,
            )
            if m:
                if m.group("credit_marker"):
                    continue

                return clean(m.group(1))

        return None

    opening = find_amount([
        r"Beginning Balance",
        r"Start balance",
        r"Opening balance",
        r"Solde initial",
        r"رصيد بداية",
    ])

    deposits = find_amount([
        r"Deposits and Additions",
        r"Money in",
        r"Total Credits",
        r"Credits",
        r"Crédits",
        r"Credits?",
        r"الإيداعات",
    ])

    # Standard account-summary aggregation:
    # If summary has multiple signed debit buckets, sum them directly.
    signed_debit_bucket_total = 0.0
    for bucket_re in [
        r"ATM\s+Withdrawals\s*&\s*Debits",
        r"Debit\s+Card\s+Purchases\s*&\s*Debits",
        r"Withdrawals\s*&\s*Other\s+Debits",
    ]:
        m_bucket = re.search(
            bucket_re + r"\s+(" + money + r")",
            raw,
            flags=re.I,
        )
        if m_bucket:
            signed_debit_bucket_total += clean(m_bucket.group(1))

    # Standard checking/current-account summary rule:
    # withdrawals = sum of all debit buckets in the account summary.
    # Example buckets: ATM withdrawals, debit-card purchases, other debits.
    debit_labels = [
        r"ATM\s+Withdrawals\s*&\s*Debits",
        r"ATM\s+Withdrawals\s+and\s+Debits",
        r"ATM\s*&\s*Debit Card Withdrawals",
        r"Debit\s+Card\s+Purchases\s*&\s*Debits",
        r"Debit\s+Card\s+Purchases\s+and\s+Debits",
        r"Withdrawals\s*&\s*Other\s+Debits",
        r"Withdrawals\s+and\s+Other\s+Debits",
        r"Money out",
        r"Total Debits",
        r"Débits",
        r"المدفوعات",
    ]

    withdrawals = 0.0  # noqa: F841
    for debit_label in debit_labels:
        value = find_amount([debit_label])
        if value is not None:
            withdrawals += abs(value)

    # Fallback only if no bucketed debit total was found.
    if signed_debit_bucket_total > 0:
        withdrawals = round(signed_debit_bucket_total, 2)  # noqa: F841
    elif withdrawals <= 0:
        withdrawals = find_amount([  # noqa: F841
            r"Withdrawals",
            r"Debits",
        ])
    else:
        withdrawals = round(withdrawals, 2)  # noqa: F841

    ending = find_amount([
        r"Ending Balance",
        r"End balance",
        r"Closing balance",
        r"Solde final",
        r"رصيد نهاية",
    ])

    out = {}

    if opening is not None:
        out["opening_balance"] = opening

    if deposits is not None:
        out["deposits"] = deposits

    if withdrawals is not None:
        out["withdrawals"] = withdrawals

    if ending is not None:
        out["ending_balance"] = ending

    if len(out) >= 3:
        return out

    return {}

def _parse_standard_date_description_amount_balance_historical(text: str) -> list[dict]:
    """
    Parse une famille structurelle internationale :

        DATE | DESCRIPTION | AMOUNT | BALANCE

    Règles :
    - une transaction commence par une date ;
    - la description peut continuer sur plusieurs lignes ;
    - les deux cellules monétaires terminales sont le mouvement et le solde ;
    - la direction vient du signe explicite ou de la variation du solde ;
    - aucun nom de banque, pays, devise, marchand ou formulation commerciale
      spécifique n'est utilisé ;
    - sans preuve structurelle suffisante, la ligne est rejetée.
    """
    import re
    import unicodedata
    from collections import Counter
    from datetime import datetime

    raw = str(text or "")
    if not raw.strip():
        return []

    # ------------------------------------------------------------------
    # Normalisation neutre
    # ------------------------------------------------------------------

    def compact(value: str) -> str:
        return re.sub(r"\s+", " ", str(value or "")).strip()

    def fold(value: str) -> str:
        normalized = unicodedata.normalize("NFKD", str(value or ""))
        normalized = "".join(
            character
            for character in normalized
            if not unicodedata.combining(character)
        )
        return compact(normalized).casefold()

    lines = [
        compact(line)
        for line in raw.splitlines()
        if compact(line)
    ]

    if not lines:
        return []

    # ------------------------------------------------------------------
    # Détection de la famille structurelle
    # ------------------------------------------------------------------

    HEADER_TERMS = {
        "date": {
            "date", "transaction date", "posting date", "value date",
            "datum", "fecha", "data", "تاريخ",
        },
        "description": {
            "description", "details", "narrative", "libelle", "libellé",
            "operation", "وصف", "البيان", "تفاصيل",
        },
        "amount": {
            "amount", "transaction amount", "movement", "mouvement",
            "montant", "betrag", "importe", "مبلغ",
        },
        "balance": {
            "balance", "running balance", "solde", "saldo",
            "kontostand", "رصيد",
        },
    }

    def has_role(value: str, role: str) -> bool:
        normalized = f" {fold(value)} "
        return any(
            f" {fold(term)} " in normalized
            for term in HEADER_TERMS[role]
        )

    def is_family_header(value: str) -> bool:
        return (
            has_role(value, "date")
            and has_role(value, "description")
            and has_role(value, "amount")
            and has_role(value, "balance")
        )

    header_indices = {
        index
        for index, line in enumerate(lines)
        if is_family_header(line)
    }

    if not header_indices:
        return []

    # ------------------------------------------------------------------
    # Dates
    # ------------------------------------------------------------------

    date_prefix_re = re.compile(
        r"^\s*"
        r"(?P<a>\d{1,2})"
        r"\s*[/.-]\s*"
        r"(?P<b>\d{1,2})"
        r"(?:\s*[/.-]\s*(?P<y>\d{2,4}))?"
        r"(?=\s|$)"
    )

    explicit_years = [
        int(value)
        for value in re.findall(r"\b(20\d{2})\b", raw)
    ]
    default_year = (
        Counter(explicit_years).most_common(1)[0][0]
        if explicit_years
        else datetime.now().year
    )

    day_first_evidence = 0
    month_first_evidence = 0

    for line in lines:
        match = date_prefix_re.match(line)
        if not match:
            continue

        first = int(match.group("a"))
        second = int(match.group("b"))

        if first > 12 >= second:
            day_first_evidence += 1
        elif second > 12 >= first:
            month_first_evidence += 1

    month_first = month_first_evidence > day_first_evidence

    def parse_transaction_date(value: str) -> tuple[str, int] | None:
        match = date_prefix_re.match(value)
        if not match:
            return None

        try:
            first = int(match.group("a"))
            second = int(match.group("b"))

            year_text = match.group("y")
            year = int(year_text) if year_text else default_year
            if year < 100:
                year += 2000

            if first > 12 >= second:
                day, month = first, second
            elif second > 12 >= first:
                month, day = first, second
            elif month_first:
                month, day = first, second
            else:
                day, month = first, second

            datetime(year, month, day)
            return f"{year:04d}-{month:02d}-{day:02d}", match.end()
        except Exception:
            return None

    # ------------------------------------------------------------------
    # Montants internationaux
    # ------------------------------------------------------------------

    # Dans cette famille, mouvement et solde sont des cellules monétaires
    # décimales. Exiger une fraction décimale évite de prendre les références,
    # numéros de carte, dates secondaires et identifiants pour des montants.
    MONEY_TOKEN = (
        r"[+-]?\s*"
        r"(?:"
        r"\d{1,3}(?:[\s\u00a0\u202f,'’]\d{3})+"
        r"|"
        r"\d{1,3}(?:\.\d{3})+(?:,\d{1,3})"
        r"|"
        r"\d{1,3}(?:,\d{3})+(?:\.\d{1,3})"
        r"|"
        r"\d+"
        r")"
        r"[.,]\d{1,3}"
    )

    money_token_re = re.compile(
        rf"(?<![\dA-Za-z])(?P<token>{MONEY_TOKEN})(?![\dA-Za-z])"
    )

    pair_re = re.compile(
        rf"(?<![\dA-Za-z])"
        rf"(?P<movement>{MONEY_TOKEN})"
        rf"\s+"
        rf"(?P<balance>{MONEY_TOKEN})"
        rf"(?![\dA-Za-z])"
    )

    def parse_money(token: str) -> float | None:
        value = str(token or "").strip()
        if not value:
            return None

        sign = -1.0 if value.startswith("-") else 1.0
        value = value.lstrip("+-").strip()
        value = (
            value.replace("\u00a0", " ")
            .replace("\u202f", " ")
            .replace("’", "'")
        )
        value = re.sub(r"[\s']", "", value)

        if "," in value and "." in value:
            if value.rfind(",") > value.rfind("."):
                value = value.replace(".", "").replace(",", ".")
            else:
                value = value.replace(",", "")
        elif "," in value:
            parts = value.split(",")
            if len(parts) > 2:
                value = "".join(parts[:-1]) + "." + parts[-1]
            elif len(parts) == 2:
                left, right = parts
                if len(right) in {1, 2, 3}:
                    value = left + "." + right
                else:
                    value = left + right
        elif "." in value:
            parts = value.split(".")
            if len(parts) > 2:
                value = "".join(parts[:-1]) + "." + parts[-1]

        try:
            return round(sign * float(value), 3)
        except Exception:
            return None

    def has_explicit_sign(token: str) -> bool:
        return bool(re.match(r"^\s*[+-]", str(token or "")))

    # ------------------------------------------------------------------
    # Frontières documentaires
    # ------------------------------------------------------------------

    marker_re = re.compile(
        r"^\[\[(?:PAGE|OCR_GEOMETRY_AUGMENTED_PAGE)\s+\d+\]\]$",
        re.I,
    )
    page_re = re.compile(r"^page\s+\d+\s+(?:of|sur)\s+\d+$", re.I)

    BALANCE_TERMS = {
        "opening balance", "beginning balance", "starting balance",
        "balance brought forward", "brought forward",
        "solde initial", "solde precedent", "solde précédent",
        "الرصيد الافتتاحي",
    }

    ENDING_TERMS = {
        "closing balance", "ending balance", "final balance",
        "balance carried forward", "carried forward",
        "solde final", "solde de cloture", "solde de clôture",
        "الرصيد الختامي",
    }

    TOTAL_TERMS = {
        "total", "subtotal", "totals", "summe",
        "total debit", "total credit", "total debits", "total credits",
        "المجموع", "الاجمالي", "الإجمالي",
    }

    def begins_with_term(value: str, terms: set[str]) -> bool:
        normalized = fold(value)
        return any(
            normalized == fold(term)
            or normalized.startswith(fold(term) + " ")
            or normalized.startswith(fold(term) + ":")
            for term in terms
        )

    def is_document_boundary(value: str) -> bool:
        line = compact(value)
        return bool(
            marker_re.match(line)
            or page_re.match(line)
            or fold(line) in {
                "ocr_augmented_text_start",
                "ocr augmented text start",
            }
        )

    # ------------------------------------------------------------------
    # Solde initial
    # ------------------------------------------------------------------

    opening_balance: float | None = None

    for line in lines:
        if not begins_with_term(line, BALANCE_TERMS):
            continue

        matches = list(money_token_re.finditer(line))
        if not matches:
            continue

        opening_balance = parse_money(matches[-1].group("token"))
        if opening_balance is not None:
            break

    # ------------------------------------------------------------------
    # Construction des blocs transactionnels
    # ------------------------------------------------------------------

    blocks: list[dict] = []
    current: dict | None = None
    table_active = False

    def flush() -> None:
        nonlocal current
        if current is not None:
            blocks.append(current)
            current = None

    for index, line in enumerate(lines):
        if index in header_indices:
            flush()
            table_active = True
            continue

        if not table_active:
            continue

        if is_document_boundary(line):
            flush()
            table_active = False
            continue

        if begins_with_term(line, ENDING_TERMS):
            flush()
            table_active = False
            continue

        if begins_with_term(line, TOTAL_TERMS):
            flush()
            continue

        if begins_with_term(line, BALANCE_TERMS):
            flush()
            continue

        date_info = parse_transaction_date(line)

        if date_info is not None:
            flush()
            iso_date, date_end = date_info
            current = {
                "date": iso_date,
                "source_line": index,
                "date_end": date_end,
                "lines": [line],
            }
            continue

        if current is not None:
            current["lines"].append(line)

    flush()

    # ------------------------------------------------------------------
    # Interprétation par montant + solde terminal
    # ------------------------------------------------------------------

    rows: list[dict] = []
    previous_balance = opening_balance

    rejected = {
        "no_money_pair": 0,
        "ambiguous_first_row": 0,
        "balance_mismatch": 0,
        "zero_amount": 0,
        "too_many_lines": 0,
    }
    balance_validated_pair_count = 0

    seen: set[tuple] = set()

    for block in blocks:
        block_lines = list(block["lines"])

        if len(block_lines) > 10:
            rejected["too_many_lines"] += 1
            continue

        joined = compact(" ".join(block_lines))

        pair_matches = list(pair_re.finditer(joined))
        if not pair_matches:
            rejected["no_money_pair"] += 1
            continue

        # ADDITIVE STRUCTURAL PAIR SELECTION V1
        #
        # Historical behavior remains the fallback: the last visible monetary
        # pair is still selected when no stronger balance proof exists.
        #
        # For multiline descriptions containing foreign amounts, exchange
        # rates, fees or references, several decimal pairs may appear before
        # the real Amount | Balance cells. When a previous running balance is
        # available, prefer the pair whose movement exactly explains the
        # observed balance delta.
        pair = None

        if previous_balance is not None:
            validated_pairs: list[tuple[float, int, object]] = []

            for candidate_index, candidate_pair in enumerate(pair_matches):
                candidate_movement = parse_money(
                    candidate_pair.group("movement")
                )
                candidate_balance = parse_money(
                    candidate_pair.group("balance")
                )

                if (
                    candidate_movement is None
                    or candidate_balance is None
                ):
                    continue

                candidate_delta = round(
                    candidate_balance - previous_balance,
                    3,
                )
                candidate_gap = abs(
                    abs(candidate_delta)
                    - abs(candidate_movement)
                )

                if candidate_gap <= 0.02:
                    validated_pairs.append(
                        (
                            candidate_gap,
                            -candidate_index,
                            candidate_pair,
                        )
                    )

            if validated_pairs:
                validated_pairs.sort(
                    key=lambda item: (
                        item[0],
                        item[1],
                    )
                )
                pair = validated_pairs[0][2]
                balance_validated_pair_count += 1

        if pair is None:
            pair = pair_matches[-1]

        movement_token = pair.group("movement")
        balance_token = pair.group("balance")

        movement_visible = parse_money(movement_token)
        balance = parse_money(balance_token)

        if movement_visible is None or balance is None:
            rejected["no_money_pair"] += 1
            continue

        if abs(movement_visible) < 0.0005:
            rejected["zero_amount"] += 1
            previous_balance = balance
            continue

        delta = (
            round(balance - previous_balance, 3)
            if previous_balance is not None
            else None
        )

        explicit_sign = has_explicit_sign(movement_token)

        if delta is not None and abs(abs(delta) - abs(movement_visible)) <= 0.02:
            # Le solde courant est l'autorité structurelle du signe.
            signed_amount = delta
        elif explicit_sign:
            # Un signe explicite reste acceptable, mais seulement lorsque
            # le couple mouvement/solde est clairement terminal.
            signed_amount = movement_visible
        elif previous_balance is None:
            rejected["ambiguous_first_row"] += 1
            previous_balance = balance
            continue
        else:
            rejected["balance_mismatch"] += 1
            previous_balance = balance
            continue

        transaction_type = "income" if signed_amount > 0 else "expense"

        date_info = parse_transaction_date(joined)
        description_start = date_info[1] if date_info else 0
        description = joined[description_start:pair.start()]
        description = compact(description)

        # Supprimer seulement les cellules monétaires terminales. Les nombres
        # internes à la description (références, dates de valeur) sont conservés.
        if not description:
            description = "Accounting transaction"

        dedupe_key = (
            block["date"],
            round(float(signed_amount), 2),
            round(float(balance), 2),
            fold(description),
        )

        if dedupe_key in seen:
            previous_balance = balance
            continue

        seen.add(dedupe_key)

        currency = "MULTI"
        try:
            detected = detect_currency(raw)
            if detected:
                currency = detected
        except Exception:
            pass

        rows.append({
            "date": block["date"],
            "description": description[:500],
            "amount": round(float(signed_amount), 2),
            "signed_amount": round(float(signed_amount), 2),
            "type": transaction_type,
            "currency": currency,
            "balance": round(float(balance), 2),
            "_balance": round(float(balance), 2),
            "locked_amount": round(float(signed_amount), 2),
            "_locked_amount": round(float(signed_amount), 2),
            "locked_type": transaction_type,
            "_balance_locked": True,
            "balance_authority": True,
            "source_line": block["source_line"],
            "parser_family": "standard_date_description_amount_balance",
        })

        previous_balance = balance

    print(
        "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_EXTRACTED",
        {
            "version": "v2-additive-balance-validated-pair-selection",
            "transactions": len(rows),
            "income": sum(
                1 for row in rows
                if row.get("type") == "income"
            ),
            "expenses": sum(
                1 for row in rows
                if row.get("type") == "expense"
            ),
            "income_total": round(
                sum(
                    abs(float(row["signed_amount"]))
                    for row in rows
                    if row.get("type") == "income"
                ),
                2,
            ),
            "expense_total": round(
                sum(
                    abs(float(row["signed_amount"]))
                    for row in rows
                    if row.get("type") == "expense"
                ),
                2,
            ),
            "blocks": len(blocks),
            "opening_balance": opening_balance,
            "balance_validated_pair_count": (
                balance_validated_pair_count
            ),
            "rejected": rejected,
        },
    )

    transactions = infer_balance_delta_rows(rows)
    return transactions


def _parse_standard_date_description_amount_balance_two_date_variant(
    text: str,
) -> list[dict]:
    """
    International structural family:

        Processed Date | Payment Made | Description | Signed Amount | Balance

    Additive evolution of:

        Date | Description | Signed Amount | Balance

    The historical implementation is executed first. The additive branch is
    activated only when the header exposes:
    - a transaction/processed date role;
    - a second payment/booking/value-date role;
    - description, signed amount and running balance roles.

    No institution, country, currency, merchant or network name is used.
    """
    import re
    import unicodedata
    from datetime import datetime

    raw = normalize_arabic_digits(str(text or ""))
    if not raw.strip():
        return []

    tolerance = float(
        globals().get("RUNEXA_STRICT_TOLERANCE", 0.02)
    )

    def compact(value: str) -> str:
        return re.sub(
            r"\s+",
            " ",
            str(value or "")
            .replace("\xa0", " ")
            .replace("\u202f", " "),
        ).strip()

    def fold(value: str) -> str:
        normalized = unicodedata.normalize(
            "NFKD",
            str(value or ""),
        )
        normalized = "".join(
            char
            for char in normalized
            if not unicodedata.combining(char)
        )
        return compact(normalized).casefold()

    physical_lines = raw.splitlines()

    lines = [
        compact(line)
        for line in physical_lines
        if compact(line)
    ]
    folded_lines = [fold(line) for line in lines]

    if not lines:
        return []

    # ADDITIVE v166 — physical blank-gap evidence for multiline rows.
    #
    # Some PDFs paint a DESCRIPTION continuation slightly above the physical
    # line that contains the transaction date/amount. Native text extraction
    # can therefore emit:
    #
    #     <blank gap>
    #     CONTINUATION
    #     DATE ... AMOUNT BALANCE
    #
    # while ordinary trailing continuations are emitted immediately after the
    # completed transaction line. We keep that distinction without using any
    # merchant/bank/country/language-specific term.
    compact_physical = [compact(line) for line in physical_lines]

    leading_continuation_occurrences: list[str] = []

    for physical_index, candidate in enumerate(compact_physical):
        if not candidate:
            continue

        previous_is_blank = (
            physical_index > 0
            and not compact_physical[physical_index - 1]
        )
        if not previous_is_blank:
            continue

        next_nonblank = None
        for probe in range(
            physical_index + 1,
            len(compact_physical),
        ):
            if compact_physical[probe]:
                next_nonblank = compact_physical[probe]
                break

        if next_nonblank is None:
            continue

        # Date parsing is defined below, so keep only the raw occurrence here.
        # The final structural check is performed in the block assembler.
        leading_continuation_occurrences.append(candidate)

    historical = (
        _parse_standard_date_description_amount_balance_historical(raw)
        or []
    )

    # ------------------------------------------------------------------
    # Additive structural guard
    # ------------------------------------------------------------------
    def is_variant_header(value: str) -> bool:
        normalized = f" {fold(value)} "

        has_primary_date = any(
            role in normalized
            for role in (
                " processed date ",
                " transaction date ",
                " posting date ",
                " date ",
            )
        )
        has_secondary_date_role = any(
            role in normalized
            for role in (
                " payment made ",
                " payment date ",
                " booking date ",
                " value date ",
                " effective date ",
                " settled date ",
            )
        )
        has_description = any(
            role in normalized
            for role in (
                " description ",
                " details ",
                " narrative ",
            )
        )
        has_amount = any(
            role in normalized
            for role in (
                " amount ",
                " movement ",
                " transaction amount ",
            )
        )
        has_balance = any(
            role in normalized
            for role in (
                " balance ",
                " running balance ",
            )
        )

        return (
            has_primary_date
            and has_secondary_date_role
            and has_description
            and has_amount
            and has_balance
        )

    header_indices = [
        index
        for index, line in enumerate(lines)
        if is_variant_header(line)
    ]

    if not header_indices:
        return historical

    first_header = header_indices[0]

    # ------------------------------------------------------------------
    # International money parsing
    # ------------------------------------------------------------------
    MONEY_TOKEN = (
        r"[+-]?\s*"
        r"(?:[$€£¥]\s*)?"
        r"(?:"
        r"\d{1,3}(?:[\s\u00a0\u202f,'’]\d{3})+"
        r"|"
        r"\d{1,3}(?:\.\d{3})+(?:,\d{1,3})"
        r"|"
        r"\d{1,3}(?:,\d{3})+(?:\.\d{1,3})"
        r"|"
        r"\d+"
        r")"
        r"[.,]\d{1,3}"
    )

    money_re = re.compile(
        rf"(?<![\dA-Za-z])(?P<token>{MONEY_TOKEN})(?![\dA-Za-z])"
    )
    pair_re = re.compile(
        rf"(?<![\dA-Za-z])"
        rf"(?P<movement>{MONEY_TOKEN})"
        rf"\s+"
        rf"(?P<balance>{MONEY_TOKEN})"
        rf"(?![\dA-Za-z])"
    )

    def parse_money(token: str) -> float | None:
        value = str(token or "").strip()
        if not value:
            return None

        sign = -1.0 if value.lstrip().startswith("-") else 1.0
        value = value.lstrip().lstrip("+-").strip()
        value = re.sub(r"^[£$€¥]\s*", "", value)
        value = (
            value.replace("\u00a0", " ")
            .replace("\u202f", " ")
            .replace("’", "'")
        )
        value = re.sub(r"[\s']", "", value)

        if "," in value and "." in value:
            if value.rfind(",") > value.rfind("."):
                value = value.replace(".", "").replace(",", ".")
            else:
                value = value.replace(",", "")
        elif "," in value:
            parts = value.split(",")
            if len(parts) > 2:
                value = "".join(parts[:-1]) + "." + parts[-1]
            elif len(parts) == 2:
                left, right = parts
                value = (
                    left + "." + right
                    if len(right) in {1, 2, 3}
                    else left + right
                )
        elif "." in value:
            parts = value.split(".")
            if len(parts) > 2:
                value = "".join(parts[:-1]) + "." + parts[-1]

        try:
            return round(sign * float(value), 3)
        except Exception:
            return None

    # ------------------------------------------------------------------
    # Official summary before the table
    # ------------------------------------------------------------------
    SUMMARY_TERMS = {
        "opening": (
            "opening balance",
            "beginning balance",
            "starting balance",
        ),
        "credits": (
            "payments in",
            "total deposits",
            "total credits",
            "money in",
        ),
        "debits": (
            "payments out",
            "total outgoings",
            "total debits",
            "money out",
        ),
        "closing": (
            "closing balance",
            "ending balance",
            "final balance",
        ),
    }

    def has_summary_role(value: str, role: str) -> bool:
        normalized = fold(value)
        return any(
            normalized == term
            or normalized.startswith(term + " ")
            or normalized.endswith(" " + term)
            for term in SUMMARY_TERMS[role]
        )

    def final_money(value: str) -> float | None:
        matches = list(money_re.finditer(value))
        if not matches:
            return None
        return parse_money(matches[-1].group("token"))

    opening_balance = None
    official_credits = None
    official_debits = None
    closing_balance = None

    for line in lines[:first_header]:
        if opening_balance is None and has_summary_role(line, "opening"):
            opening_balance = final_money(line)

        if official_credits is None and has_summary_role(line, "credits"):
            amount = final_money(line)
            if amount is not None:
                official_credits = abs(amount)

        if official_debits is None and has_summary_role(line, "debits"):
            amount = final_money(line)
            if amount is not None:
                official_debits = abs(amount)

        if closing_balance is None and has_summary_role(line, "closing"):
            closing_balance = final_money(line)

    has_summary = all(
        value is not None
        for value in (
            opening_balance,
            official_credits,
            official_debits,
            closing_balance,
        )
    )

    if not has_summary:
        return historical

    def totals(transactions: list[dict]) -> tuple[float, float]:
        credits = 0.0
        debits = 0.0

        for tx in transactions or []:
            if not isinstance(tx, dict) or not tx.get("date"):
                continue

            try:
                signed = float(
                    tx.get("signed_amount")
                    if tx.get("signed_amount") is not None
                    else tx.get("amount") or 0
                )
            except Exception:
                continue

            if signed > 0:
                credits += abs(signed)
            elif signed < 0:
                debits += abs(signed)

        return round(credits, 2), round(debits, 2)

    if historical:
        hist_credits, hist_debits = totals(historical)
        if (
            abs(hist_credits - float(official_credits)) <= tolerance
            and abs(hist_debits - float(official_debits)) <= tolerance
        ):
            return historical

    # ------------------------------------------------------------------
    # Dates and neutral roles
    # ------------------------------------------------------------------
    date_re = re.compile(
        r"^\s*"
        r"(?P<day>\d{1,2})"
        r"\s*[/.-]\s*"
        r"(?P<month>\d{1,2})"
        r"\s*[/.-]\s*"
        r"(?P<year>\d{2,4})"
        r"(?=\s|$)"
    )

    def parse_date_prefix(value: str) -> tuple[str, int] | None:
        match = date_re.match(value)
        if not match:
            return None

        year = int(match.group("year"))
        if year < 100:
            year += 2000

        try:
            parsed = datetime(
                year,
                int(match.group("month")),
                int(match.group("day")),
            )
        except ValueError:
            return None

        return parsed.strftime("%Y-%m-%d"), match.end()

    # Resolve the previously observed blank-gap candidates now that the
    # transaction-date role is available.
    leading_continuation_budget: Counter = Counter()

    for physical_index, candidate in enumerate(compact_physical):
        if not candidate:
            continue

        if candidate not in leading_continuation_occurrences:
            continue

        next_nonblank = None
        for probe in range(
            physical_index + 1,
            len(compact_physical),
        ):
            if compact_physical[probe]:
                next_nonblank = compact_physical[probe]
                break

        if (
            next_nonblank is not None
            and parse_date_prefix(next_nonblank) is not None
        ):
            leading_continuation_budget[candidate] += 1

    marker_re = re.compile(
        r"^\[\[(?:PAGE|OCR_GEOMETRY_AUGMENTED_PAGE)\s+\d+\]\]$",
        re.I,
    )
    page_re = re.compile(
        r"^page\s+\d+\s+(?:of|sur)\s+\d+$",
        re.I,
    )

    LEGAL_TERMS = (
        "registered office",
        "authorised by",
        "authorized by",
        "regulated by",
        "financial services register",
        "company registered",
    )
    FOOTER_TERMS = (
        "support@",
        "www.",
        "we are here for you",
    )

    def line_role(value: str) -> str:
        normalized = fold(value)

        if is_variant_header(value):
            return "HEADER"

        if marker_re.match(value) or page_re.match(value):
            return "FOOTER"

        if any(term in normalized for term in LEGAL_TERMS):
            return "LEGAL"

        if any(term in normalized for term in FOOTER_TERMS):
            return "FOOTER"

        if has_summary_role(value, "closing"):
            return "BALANCE"

        if any(
            has_summary_role(value, role)
            for role in ("opening", "credits", "debits")
        ):
            return "SUMMARY"

        if parse_date_prefix(value) is not None:
            return "TRANSACTION"

        return "CONTINUATION"

    # ------------------------------------------------------------------
    # OCR-aware transaction blocks
    # ------------------------------------------------------------------
    blocks: list[dict] = []
    current = None
    table_active = False
    pending_leading_continuations: list[str] = []

    def block_text(block: dict | None) -> str:
        if not block:
            return ""
        return compact(" ".join(block.get("lines") or []))

    def block_has_pair(block: dict | None) -> bool:
        return bool(pair_re.search(block_text(block)))

    def flush() -> None:
        nonlocal current
        if current is not None:
            blocks.append(current)
            current = None

    for index, line in enumerate(lines):
        role = line_role(line)

        if role == "HEADER":
            flush()
            table_active = True
            continue

        if not table_active:
            continue

        if role in {"BALANCE", "LEGAL", "FOOTER", "SUMMARY"}:
            flush()
            if role == "BALANCE":
                table_active = False
            continue

        date_info = parse_date_prefix(line)

        if date_info is not None:
            iso_date, date_end = date_info
            remainder = compact(line[date_end:])

            if current is None:
                current = {
                    "date": iso_date,
                    "source_line": index,
                    "lines": [
                        *pending_leading_continuations,
                        line,
                    ],
                }
                pending_leading_continuations = []
                continue

            # A date-only physical line followed by another dated line is the
            # two-date prefix of one transaction, not two transactions.
            current_text = block_text(current)
            current_date_only = bool(
                date_re.fullmatch(current_text)
            )
            current_without_pair = not block_has_pair(current)

            if current_date_only and current_without_pair:
                current["lines"].append(line)
                continue

            # Once the current block already exposes Amount + Balance, a new
            # dated line starts the next transaction.
            if block_has_pair(current):
                flush()
                current = {
                    "date": iso_date,
                    "source_line": index,
                    "lines": [
                        *pending_leading_continuations,
                        line,
                    ],
                }
                pending_leading_continuations = []
                continue

            # A second date can also be emitted on a separate line before the
            # amount/balance line. Keep it in the same block while the current
            # block contains no monetary pair.
            if current_without_pair and len(current["lines"]) <= 3:
                current["lines"].append(line)
                continue

            flush()
            current = {
                "date": iso_date,
                "source_line": index,
                "lines": [line],
            }
            continue

        if current is not None:
            if (
                block_has_pair(current)
                and leading_continuation_budget.get(line, 0) > 0
            ):
                # A completed transaction followed by a blank-gap DESCRIPTION
                # line immediately preceding the next dated row: keep that
                # line for the next transaction instead of contaminating the
                # previous transaction.
                flush()
                pending_leading_continuations.append(line)
                leading_continuation_budget[line] -= 1
                continue

            current["lines"].append(line)

    flush()

    if not blocks:
        return historical

    # ------------------------------------------------------------------
    # Parse observations
    # ------------------------------------------------------------------
    parsed_rows: list[dict] = []
    rejected = {
        "no_terminal_pair": 0,
        "invalid_money": 0,
        "empty_description": 0,
    }

    try:
        currency = detect_currency(raw) or "MULTI"
    except Exception:
        currency = "MULTI"

    for block in blocks:
        joined = block_text(block)
        pairs = list(pair_re.finditer(joined))

        if not pairs:
            rejected["no_terminal_pair"] += 1
            continue

        pair = pairs[-1]
        movement = parse_money(pair.group("movement"))
        balance = parse_money(pair.group("balance"))

        if movement is None or balance is None:
            rejected["invalid_money"] += 1
            continue

        prefix = compact(joined[:pair.start()])
        suffix = compact(joined[pair.end():])

        # Date cells are structural columns, not description content.
        # Remove at most two date tokens from the pre-money portion even when
        # a multiline DESCRIPTION fragment was physically painted before a
        # secondary date cell.
        for _ in range(2):
            date_match = re.search(
                r"(?<!\d)"
                r"\d{1,2}\s*[/.-]\s*\d{1,2}\s*[/.-]\s*\d{2,4}"
                r"(?!\d)",
                prefix,
            )
            if not date_match:
                break
            prefix = compact(
                prefix[:date_match.start()]
                + " "
                + prefix[date_match.end():]
            )

        description_parts = [
            part.strip(" |-")
            for part in (prefix, suffix)
            if part.strip(" |-")
        ]
        description = compact(" ".join(description_parts))

        if not description:
            rejected["empty_description"] += 1
            description = "Accounting transaction"

        parsed_rows.append({
            "date": block["date"],
            "description": description[:500],
            "visible_signed_amount": round(float(movement), 2),
            "balance": round(float(balance), 2),
            "_balance": round(float(balance), 2),
            "currency": currency,
            "row_role": "TRANSACTION",
            "source_line": block["source_line"],
            "parser_family": (
                "standard_date_description_amount_balance"
            ),
        })

    if not parsed_rows:
        return historical

    # ------------------------------------------------------------------
    # Running-balance validation
    # ------------------------------------------------------------------
    chain_rows: list[dict] = []
    previous_balance = round(float(opening_balance), 2)
    chain_rejected = 0

    for row in parsed_rows:
        current_balance = round(float(row["balance"]), 2)
        expected = round(current_balance - previous_balance, 2)
        visible = round(float(row["visible_signed_amount"]), 2)

        if abs(abs(expected) - abs(visible)) > tolerance:
            chain_rejected += 1
            # Preserve the chain state only when the visible signed amount
            # itself reconciles the next balance.
            continue

        signed = expected
        tx_type = "income" if signed > 0 else "expense"

        chain_rows.append({
            "date": row["date"],
            "description": row["description"],
            "debit": abs(signed) if signed < 0 else None,
            "credit": abs(signed) if signed > 0 else None,
            "amount": signed,
            "signed_amount": signed,
            "type": tx_type,
            "currency": currency,
            "balance": current_balance,
            "_balance": current_balance,
            "locked_amount": signed,
            "_locked_amount": signed,
            "locked_type": tx_type,
            "_balance_locked": True,
            "balance_authority": True,
            "row_role": "TRANSACTION",
            "source_line": row["source_line"],
            "parser_family": (
                "standard_date_description_amount_balance"
            ),
            "classification_source": (
                "two_date_ocr_block_plus_running_balance"
            ),
        })

        previous_balance = current_balance

    if not chain_rows:
        return historical

    rows: list[dict] = [
        {
            "balance": round(float(opening_balance), 2),
            "balance_role": "opening",
            "row_role": "BALANCE",
        },
        *chain_rows,
        {
            "debit_total": round(float(official_debits), 2),
            "credit_total": round(float(official_credits), 2),
            "row_role": "SUMMARY",
        },
        {
            "balance": round(float(closing_balance), 2),
            "balance_role": "closing",
            "row_role": "BALANCE",
        },
    ]

    transactions = infer_balance_delta_rows(rows) or []
    dated_transactions = [
        tx
        for tx in transactions
        if isinstance(tx, dict) and tx.get("date")
    ]

    extracted_credits, extracted_debits = totals(dated_transactions)

    credit_gap = round(
        extracted_credits - float(official_credits),
        2,
    )
    debit_gap = round(
        extracted_debits - float(official_debits),
        2,
    )
    balance_gap = round(
        float(opening_balance)
        + extracted_credits
        - extracted_debits
        - float(closing_balance),
        2,
    )

    reconciled = (
        abs(credit_gap) <= tolerance
        and abs(debit_gap) <= tolerance
        and abs(balance_gap) <= tolerance
    )

    print(
        "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_TWO_DATE_OCR_AUDIT",
        {
            "headers": len(header_indices),
            "blocks": len(blocks),
            "parsed_rows": len(parsed_rows),
            "chain_rows": len(chain_rows),
            "chain_rejected": chain_rejected,
            "transactions": len(dated_transactions),
            "official_credits": official_credits,
            "official_debits": official_debits,
            "extracted_credits": extracted_credits,
            "extracted_debits": extracted_debits,
            "opening_balance": opening_balance,
            "closing_balance": closing_balance,
            "credit_gap": credit_gap,
            "debit_gap": debit_gap,
            "balance_gap": balance_gap,
            "rejected": rejected,
            "reconciled": reconciled,
        },
    )

    if not reconciled:
        return historical

    for tx in transactions:
        if not isinstance(tx, dict):
            continue

        tx["parser_family"] = (
            "standard_date_description_amount_balance"
        )
        tx["_statement_opening_balance"] = round(
            float(opening_balance),
            2,
        )
        tx["_statement_closing_balance"] = round(
            float(closing_balance),
            2,
        )
        tx["_official_credit_total"] = round(
            float(official_credits),
            2,
        )
        tx["_official_debit_total"] = round(
            float(official_debits),
            2,
        )

        # ADDITIVE v165 — expose exact local accounting authority only after
        # the two-date structural branch has reconciled official credits,
        # official debits and opening/closing balances.
        if tx.get("date"):
            tx["accounting_reconciled"] = True
            tx["balance_reconciled"] = True

    return transactions


def parse_standard_date_description_amount_balance(
    text: str,
) -> list[dict]:
    """
    International structural family:

        DATE | DESCRIPTION | SIGNED AMOUNT | BALANCE

    Additive evolution:
    - the historical parser remains first;
    - the additive branch runs only when official accounting authority exists
      and the historical result does not reconcile;
    - no bank, country, currency, merchant, or network-specific rule is used;
    - repeated headers, multiline descriptions, FOOTER, LEGAL, SUMMARY and
      secondary non-transaction sections are handled structurally;
    - final accounting projection is delegated to infer_balance_delta_rows.
    """
    import re
    import unicodedata
    from datetime import datetime

    raw = normalize_arabic_digits(str(text or ""))
    if not raw.strip():
        return []

    tolerance = float(
        globals().get("RUNEXA_STRICT_TOLERANCE", 0.02)
    )

    def compact(value: str) -> str:
        return re.sub(
            r"\s+",
            " ",
            str(value or "")
            .replace("\xa0", " ")
            .replace("\u202f", " "),
        ).strip()

    def fold(value: str) -> str:
        normalized = unicodedata.normalize(
            "NFKD",
            str(value or ""),
        )
        normalized = "".join(
            char
            for char in normalized
            if not unicodedata.combining(char)
        )
        return compact(normalized).casefold()

    lines = [
        compact(line)
        for line in raw.splitlines()
        if compact(line)
    ]
    folded_lines = [fold(line) for line in lines]

    if not lines:
        return []

    # ------------------------------------------------------------------
    # Structural header detection
    # ------------------------------------------------------------------
    DATE_TERMS = {
        "date",
        "transaction date",
        "posting date",
        "datum",
        "fecha",
        "data",
        "تاريخ",
    }
    DESCRIPTION_TERMS = {
        "description",
        "details",
        "narrative",
        "libelle",
        "libellé",
        "operation",
        "وصف",
        "البيان",
        "تفاصيل",
    }
    AMOUNT_TERMS = {
        "amount",
        "transaction amount",
        "movement",
        "mouvement",
        "montant",
        "betrag",
        "importe",
        "مبلغ",
    }
    BALANCE_TERMS = {
        "balance",
        "running balance",
        "solde",
        "saldo",
        "kontostand",
        "رصيد",
    }

    def has_any_term(value: str, terms: set[str]) -> bool:
        normalized = f" {fold(value)} "
        return any(
            f" {fold(term)} " in normalized
            for term in terms
        )

    def is_family_header(value: str) -> bool:
        normalized = f" {fold(value)} "
        return (
            has_any_term(value, DATE_TERMS)
            and has_any_term(value, DESCRIPTION_TERMS)
            and has_any_term(value, AMOUNT_TERMS)
            and has_any_term(value, BALANCE_TERMS)
            and " debit " not in normalized
            and " credit " not in normalized
        )

    header_indices = [
        index
        for index, line in enumerate(lines)
        if is_family_header(line)
    ]

    if not header_indices:
        return []

    first_header_index = header_indices[0]

    # ------------------------------------------------------------------
    # Money parsing
    # ------------------------------------------------------------------
    MONEY_TOKEN = (
        r"[+-]?\s*"
        r"(?:[$€£¥]\s*)?"
        r"(?:"
        r"\d{1,3}(?:[\s\u00a0\u202f,'’]\d{3})+"
        r"|"
        r"\d{1,3}(?:\.\d{3})+(?:,\d{1,3})"
        r"|"
        r"\d{1,3}(?:,\d{3})+(?:\.\d{1,3})"
        r"|"
        r"\d+"
        r")"
        r"[.,]\d{1,3}"
    )

    money_token_re = re.compile(
        rf"(?<![\dA-Za-z])(?P<token>{MONEY_TOKEN})(?![\dA-Za-z])"
    )
    pair_re = re.compile(
        rf"(?<![\dA-Za-z])"
        rf"(?P<movement>{MONEY_TOKEN})"
        rf"\s+"
        rf"(?P<balance>{MONEY_TOKEN})"
        rf"(?![\dA-Za-z])"
    )

    def parse_money(token: str) -> float | None:
        value = str(token or "").strip()
        if not value:
            return None

        sign = -1.0 if value.lstrip().startswith("-") else 1.0
        value = value.lstrip().lstrip("+-").strip()
        value = re.sub(r"^[£$€¥]\s*", "", value)
        value = (
            value.replace("\u00a0", " ")
            .replace("\u202f", " ")
            .replace("’", "'")
        )
        value = re.sub(r"[\s']", "", value)

        if "," in value and "." in value:
            if value.rfind(",") > value.rfind("."):
                value = value.replace(".", "").replace(",", ".")
            else:
                value = value.replace(",", "")
        elif "," in value:
            parts = value.split(",")
            if len(parts) > 2:
                value = "".join(parts[:-1]) + "." + parts[-1]
            elif len(parts) == 2:
                left, right = parts
                value = (
                    left + "." + right
                    if len(right) in {1, 2, 3}
                    else left + right
                )
        elif "." in value:
            parts = value.split(".")
            if len(parts) > 2:
                value = "".join(parts[:-1]) + "." + parts[-1]

        try:
            return round(sign * float(value), 3)
        except Exception:
            return None

    # ------------------------------------------------------------------
    # Official authority scoped only to the summary before the first header
    # ------------------------------------------------------------------
    summary_lines = lines[:first_header_index]
    summary_folded = folded_lines[:first_header_index]

    POSITIVE_TOTAL_TERMS = {
        "total deposits",
        "total credits",
        "total money in",
        "total inflows",
    }
    NEGATIVE_TOTAL_TERMS = {
        "total outgoings",
        "total debits",
        "total withdrawals",
        "total money out",
        "total outflows",
    }
    CLOSING_TERMS = {
        "account balance",
        "closing balance",
        "ending balance",
        "current balance",
        "final balance",
    }

    def label_matches(value: str, terms: set[str]) -> bool:
        normalized = fold(value)
        return any(
            normalized == fold(term)
            or normalized.startswith(fold(term) + " ")
            or normalized.endswith(" " + fold(term))
            for term in terms
        )

    def nearest_summary_money(
        label_index: int,
        *,
        prefer_before: bool = True,
        radius: int = 3,
    ) -> float | None:
        offsets = []
        for distance in range(0, radius + 1):
            if prefer_before:
                offsets.extend([-distance, distance])
            else:
                offsets.extend([distance, -distance])

        visited = set()
        for offset in offsets:
            index = label_index + offset
            if index in visited:
                continue
            visited.add(index)

            if index < 0 or index >= len(summary_lines):
                continue

            matches = list(
                money_token_re.finditer(summary_lines[index])
            )
            if not matches:
                continue

            for match in matches:
                parsed = parse_money(match.group("token"))
                if parsed is not None:
                    return parsed

        return None

    official_credits = None
    official_debits = None
    closing_balance = None

    for index, value in enumerate(summary_folded):
        if (
            official_credits is None
            and label_matches(value, POSITIVE_TOTAL_TERMS)
        ):
            amount = nearest_summary_money(
                index,
                prefer_before=True,
                radius=2,
            )
            if amount is not None:
                official_credits = abs(amount)

        if (
            official_debits is None
            and label_matches(value, NEGATIVE_TOTAL_TERMS)
        ):
            amount = nearest_summary_money(
                index,
                prefer_before=True,
                radius=2,
            )
            if amount is not None:
                official_debits = abs(amount)

        if (
            closing_balance is None
            and label_matches(value, CLOSING_TERMS)
            and "pot" not in value
        ):
            amount = nearest_summary_money(
                index,
                prefer_before=True,
                radius=3,
            )
            if amount is not None:
                closing_balance = amount

    has_official_authority = (
        official_credits is not None
        and official_debits is not None
        and closing_balance is not None
    )

    def totals(transactions: list[dict]) -> tuple[float, float]:
        credits = 0.0
        debits = 0.0

        for tx in transactions or []:
            if not isinstance(tx, dict) or not tx.get("date"):
                continue

            try:
                signed = float(
                    tx.get("signed_amount")
                    if tx.get("signed_amount") is not None
                    else tx.get("amount") or 0
                )
            except Exception:
                continue

            if signed > 0:
                credits += abs(signed)
            elif signed < 0:
                debits += abs(signed)

        return round(credits, 2), round(debits, 2)

    # ------------------------------------------------------------------
    # Historical path remains first
    # ------------------------------------------------------------------
    historical = (
        _parse_standard_date_description_amount_balance_historical(raw)
        or []
    )

    if historical:
        historical_credits, historical_debits = totals(historical)

        historical_reconciled = (
            not has_official_authority
            or (
                abs(
                    historical_credits - float(official_credits)
                ) <= tolerance
                and abs(
                    historical_debits - float(official_debits)
                ) <= tolerance
            )
        )

        if historical_reconciled:
            print(
                "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_PATH",
                {
                    "mode": "historical",
                    "transactions": len(
                        [
                            tx
                            for tx in historical
                            if isinstance(tx, dict)
                            and tx.get("date")
                        ]
                    ),
                    "credits": historical_credits,
                    "debits": historical_debits,
                    "reconciled": True,
                },
            )
            return historical

    # The additive branch only activates with official authority.
    if not has_official_authority:
        return historical

    # ------------------------------------------------------------------
    # Date parsing
    # ------------------------------------------------------------------
    date_prefix_re = re.compile(
        r"^\s*"
        r"(?P<day>\d{1,2})"
        r"\s*[/.-]\s*"
        r"(?P<month>\d{1,2})"
        r"\s*[/.-]\s*"
        r"(?P<year>\d{2,4})"
        r"(?=\s|$)"
    )

    def parse_date(value: str) -> tuple[str, int] | None:
        match = date_prefix_re.match(value)
        if not match:
            return None

        try:
            year = int(match.group("year"))
            if year < 100:
                year += 2000

            parsed = datetime(
                year,
                int(match.group("month")),
                int(match.group("day")),
            )
            return parsed.strftime("%Y-%m-%d"), match.end()
        except Exception:
            return None

    # ------------------------------------------------------------------
    # Neutral role classification
    # ------------------------------------------------------------------
    marker_re = re.compile(
        r"^\[\[(?:PAGE|OCR_GEOMETRY_AUGMENTED_PAGE)\s+\d+\]\]$",
        re.I,
    )
    page_re = re.compile(
        r"^page\s+\d+\s+(?:of|sur)\s+\d+$",
        re.I,
    )

    LEGAL_TERMS = {
        "registered office",
        "authorised by",
        "authorized by",
        "regulated by",
        "financial services register",
        "compensation scheme",
        "eligible deposits",
        "depositors",
        "financial obligations",
        "information sheet",
        "exclusions list",
        "maximum amount",
        "for more information",
        "company registered",
    }
    FOOTER_TERMS = {
        "sort code",
        "account number",
        "iban",
        "bic",
        "swift",
    }
    SECONDARY_SECTION_TERMS = {
        "pot statement",
        "savings statement",
        "vault statement",
        "pocket statement",
        "there were no transactions during this period",
    }

    def line_role(value: str) -> str:
        normalized = fold(value)

        if is_family_header(value):
            return "HEADER"

        if marker_re.match(value) or page_re.match(value):
            return "FOOTER"

        if any(
            normalized == term
            or normalized.startswith(term + ":")
            for term in FOOTER_TERMS
        ):
            return "FOOTER"

        if any(term in normalized for term in LEGAL_TERMS):
            return "LEGAL"

        if any(
            normalized == term
            or normalized.startswith(term + " ")
            for term in SECONDARY_SECTION_TERMS
        ):
            return "SUMMARY"

        if parse_date(value) is not None:
            return "TRANSACTION"

        return "CONTINUATION"

    # ------------------------------------------------------------------
    # Build only the main ledger blocks
    # ------------------------------------------------------------------
    blocks: list[dict] = []
    current = None
    table_active = False
    main_table_seen = False

    def flush() -> None:
        nonlocal current
        if current is not None:
            blocks.append(current)
            current = None

    for index, line in enumerate(lines):
        role = line_role(line)

        if role == "HEADER":
            flush()
            table_active = True
            main_table_seen = True
            continue

        if not table_active:
            continue

        if role == "SUMMARY":
            flush()
            table_active = False
            if main_table_seen:
                break
            continue

        if role in {"LEGAL", "FOOTER"}:
            flush()
            continue

        date_info = parse_date(line)

        if date_info is not None:
            flush()
            iso_date, date_end = date_info
            current = {
                "date": iso_date,
                "source_line": index,
                "date_end": date_end,
                "lines": [line],
            }
            continue

        if current is not None and role == "CONTINUATION":
            current["lines"].append(line)

    flush()

    if not blocks:
        return historical

    # ------------------------------------------------------------------
    # Parse signed amount + running balance
    # ------------------------------------------------------------------
    parsed_rows: list[dict] = []
    seen = set()

    rejected = {
        "no_terminal_pair": 0,
        "invalid_money": 0,
        "empty_description": 0,
    }

    try:
        currency = detect_currency(raw) or "MULTI"
    except Exception:
        currency = "MULTI"

    for block in blocks:
        joined = compact(" ".join(block["lines"]))
        pairs = list(pair_re.finditer(joined))

        if not pairs:
            rejected["no_terminal_pair"] += 1
            continue

        pair = pairs[-1]
        movement = parse_money(pair.group("movement"))
        balance = parse_money(pair.group("balance"))

        if movement is None or balance is None:
            rejected["invalid_money"] += 1
            continue

        date_info = parse_date(joined)
        description_start = date_info[1] if date_info else 0
        description = compact(
            joined[description_start:pair.start()]
        ).strip(" |-")

        if not description:
            rejected["empty_description"] += 1
            description = "Accounting movement"

        key = (
            block["date"],
            round(float(movement), 2),
            round(float(balance), 2),
            fold(description),
            block["source_line"],
        )
        if key in seen:
            continue
        seen.add(key)

        parsed_rows.append({
            "date": block["date"],
            "description": description[:500],
            "visible_signed_amount": round(
                float(movement),
                2,
            ),
            "balance": round(float(balance), 2),
            "_balance": round(float(balance), 2),
            "currency": currency,
            "row_role": "TRANSACTION",
            "source_line": block["source_line"],
            "parser_family": (
                "standard_date_description_amount_balance"
            ),
        })

    if not parsed_rows:
        return historical

    # ------------------------------------------------------------------
    # Statement order and balance-chain authority
    # ------------------------------------------------------------------
    date_values = [
        datetime.strptime(row["date"], "%Y-%m-%d")
        for row in parsed_rows
    ]
    descending_pairs = sum(
        left >= right
        for left, right in zip(
            date_values,
            date_values[1:],
        )
    )
    ascending_pairs = sum(
        left <= right
        for left, right in zip(
            date_values,
            date_values[1:],
        )
    )
    statement_order = (
        "descending"
        if descending_pairs >= ascending_pairs
        else "ascending"
    )

    opening_balance = round(
        float(closing_balance)
        - float(official_credits)
        + float(official_debits),
        2,
    )

    chain_rows: list[dict] = []
    chain_rejected = 0

    for index, row in enumerate(parsed_rows):
        visible = round(
            float(row["visible_signed_amount"]),
            2,
        )
        current_balance = round(
            float(row["balance"]),
            2,
        )

        if statement_order == "descending":
            older_balance = (
                round(
                    float(parsed_rows[index + 1]["balance"]),
                    2,
                )
                if index + 1 < len(parsed_rows)
                else opening_balance
            )
            expected = round(
                current_balance - older_balance,
                2,
            )
        else:
            previous_balance = (
                round(
                    float(parsed_rows[index - 1]["balance"]),
                    2,
                )
                if index > 0
                else opening_balance
            )
            expected = round(
                current_balance - previous_balance,
                2,
            )

        # Running balance is authoritative for direction. The visible amount
        # must still have the same absolute value. This also repairs OCR where
        # "-" is split from the number on the preceding physical line.
        if (
            abs(abs(expected) - abs(visible))
            > tolerance
        ):
            chain_rejected += 1
            continue

        signed = expected
        tx_type = "income" if signed > 0 else "expense"

        chain_rows.append({
            "date": row["date"],
            "description": row["description"],
            "debit": abs(signed) if signed < 0 else None,
            "credit": abs(signed) if signed > 0 else None,
            "amount": signed,
            "signed_amount": signed,
            "visible_amount": abs(signed),
            "type": tx_type,
            "currency": currency,
            "balance": current_balance,
            "_balance": current_balance,
            "locked_amount": signed,
            "_locked_amount": signed,
            "locked_type": tx_type,
            "_balance_locked": True,
            "balance_authority": True,
            "row_role": "TRANSACTION",
            "source_line": row["source_line"],
            "parser_family": (
                "standard_date_description_amount_balance"
            ),
            "classification_source": (
                "signed_amount_plus_running_balance"
            ),
        })

    if not chain_rows:
        return historical

    rows: list[dict] = [
        {
            "balance": opening_balance,
            "balance_role": "opening",
            "row_role": "BALANCE",
        },
        *chain_rows,
        {
            "debit_total": round(
                float(official_debits),
                2,
            ),
            "credit_total": round(
                float(official_credits),
                2,
            ),
            "row_role": "SUMMARY",
        },
        {
            "balance": round(
                float(closing_balance),
                2,
            ),
            "balance_role": "closing",
            "row_role": "BALANCE",
        },
    ]

    transactions = infer_balance_delta_rows(rows) or []
    dated_transactions = [
        tx
        for tx in transactions
        if isinstance(tx, dict) and tx.get("date")
    ]

    extracted_credits, extracted_debits = totals(
        dated_transactions
    )
    credit_gap = round(
        extracted_credits - float(official_credits),
        2,
    )
    debit_gap = round(
        extracted_debits - float(official_debits),
        2,
    )
    balance_gap = round(
        opening_balance
        + extracted_credits
        - extracted_debits
        - float(closing_balance),
        2,
    )

    reconciled = (
        abs(credit_gap) <= tolerance
        and abs(debit_gap) <= tolerance
        and abs(balance_gap) <= tolerance
    )

    print(
        "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_ADDITIVE_AUDIT",
        {
            "statement_order": statement_order,
            "physical_blocks": len(blocks),
            "parsed_rows": len(parsed_rows),
            "chain_rows": len(chain_rows),
            "chain_rejected": chain_rejected,
            "transactions": len(dated_transactions),
            "opening_balance": opening_balance,
            "closing_balance": closing_balance,
            "official_credits": official_credits,
            "official_debits": official_debits,
            "extracted_credits": extracted_credits,
            "extracted_debits": extracted_debits,
            "credit_gap": credit_gap,
            "debit_gap": debit_gap,
            "balance_gap": balance_gap,
            "rejected": rejected,
            "reconciled": reconciled,
        },
    )

    if not reconciled:
        return historical

    for tx in transactions:
        if not isinstance(tx, dict):
            continue

        tx["parser_family"] = (
            "standard_date_description_amount_balance"
        )
        tx["_statement_opening_balance"] = opening_balance
        tx["_statement_closing_balance"] = round(
            float(closing_balance),
            2,
        )
        tx["_official_credit_total"] = round(
            float(official_credits),
            2,
        )
        tx["_official_debit_total"] = round(
            float(official_debits),
            2,
        )

    return transactions


def parse_standard_date_description_amount_balance(
    text: str,
) -> list[dict]:
    """
    International structural family:

        Date | Description | Signed Amount | Balance

    Evolution strategy:
    1. Run the historical parser first.
    2. Keep it unchanged when it reconciles with the statement authority.
    3. Otherwise, activate an additive branch for the real variant with:
       - descending statement order;
       - multiline descriptions;
       - repeated page headers;
       - repeated FOOTER / LEGAL blocks;
       - a separate non-transaction account section after the main ledger;
       - official total outgoings, total deposits and closing balance.

    No bank, country, currency, merchant or network name is used.
    """
    import re
    import unicodedata
    from datetime import datetime

    raw = normalize_arabic_digits(str(text or ""))

    # ADDITIVE v163 — family-local native-text sidecar.
    # Historical behavior is unchanged when the sidecar is absent.
    sidecar_match = re.search(
        r"^RUNEXA_STANDARD_AMOUNT_BALANCE_NATIVE_V1\s+"
        r"(?P<payload>[A-Za-z0-9+/=]+)\s*$",
        raw,
        re.MULTILINE,
    )

    if sidecar_match:
        try:
            import base64 as _base64
            native_raw = _base64.b64decode(
                sidecar_match.group("payload")
            ).decode("utf-8", errors="replace")

            native_folded = " ".join(native_raw.casefold().split())

            if re.search(
                r"\bdate\b.*\bdescription\b.*\bamount\b.*\bbalance\b",
                native_folded,
                re.S,
            ):
                raw = normalize_arabic_digits(native_raw)
                print(
                    "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_NATIVE_SIDECAR_USED",
                    {
                        "characters": len(native_raw),
                        "reason": "exact_family_header_present",
                    },
                )
        except Exception as exc:
            print(
                "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_NATIVE_SIDECAR_REJECTED",
                str(exc)[:160],
            )

    if not raw.strip():
        return []

    tolerance = float(
        globals().get("RUNEXA_STRICT_TOLERANCE", 0.02)
    )

    def _compact(value: str) -> str:
        return re.sub(
            r"\s+",
            " ",
            str(value or "").replace("\xa0", " ").replace("\u202f", " "),
        ).strip()

    def _fold(value: str) -> str:
        normalized = unicodedata.normalize(
            "NFKD",
            str(value or ""),
        )
        normalized = "".join(
            char
            for char in normalized
            if not unicodedata.combining(char)
        )
        return _compact(normalized).casefold()

    lines = [
        _compact(line)
        for line in raw.splitlines()
        if _compact(line)
    ]
    folded_lines = [_fold(line) for line in lines]

    if not lines:
        return []

    money_token = (
        r"[+-]?\s*(?:[$€£¥]\s*)?"
        r"(?:"
        r"\d{1,3}(?:[ ,\u00a0\u202f]\d{3})+"
        r"|"
        r"\d{1,3}(?:,\d{3})+(?:\.\d{1,3})"
        r"|"
        r"\d{1,3}(?:\.\d{3})+(?:,\d{1,3})"
        r"|"
        r"\d+"
        r")"
        r"[.,]\d{2}"
    )
    money_re = re.compile(
        rf"(?<![\dA-Za-z])(?P<token>{money_token})(?![\dA-Za-z])"
    )
    pair_re = re.compile(
        rf"(?<![\dA-Za-z])"
        rf"(?P<movement>{money_token})\s+"
        rf"(?P<balance>{money_token})"
        rf"(?![\dA-Za-z])"
    )

    def _parse_money(token: str) -> float | None:
        try:
            return round(float(parse_amount(token)), 2)
        except Exception:
            return None

    def _nearest_money(
        label_index: int,
        *,
        before: int = 3,
        after: int = 3,
    ) -> float | None:
        candidates = []

        for distance in range(0, max(before, after) + 1):
            for index in (
                label_index - distance,
                label_index + distance,
            ):
                if index < 0 or index >= len(lines):
                    continue
                if index == label_index and distance == 0:
                    pass
                if index < label_index and distance > before:
                    continue
                if index > label_index and distance > after:
                    continue

                matches = list(money_re.finditer(lines[index]))
                if not matches:
                    continue

                # Prefer a currency-signed value when available.
                for match in matches:
                    token = match.group("token")
                    parsed = _parse_money(token)
                    if parsed is not None:
                        candidates.append(
                            (
                                distance,
                                0 if re.search(r"[$€£¥]", token) else 1,
                                parsed,
                            )
                        )

            if candidates:
                break

        if not candidates:
            return None

        candidates.sort(key=lambda item: (item[0], item[1]))
        return candidates[0][2]

    def _summary_role_money(
        label_index: int | None,
        *,
        role: str,
        radius: int = 4,
    ) -> float | None:
        """Resolve a summary amount from local structural evidence.

        This is intentionally local to the Date|Description|Amount|Balance
        family.  It uses only the summary role, adjacency, sign and currency
        formatting.  It does not use any bank/country/merchant knowledge.

        The additive branch protects against flattened/OCR line ordering where
        a nearer unrelated zero balance can otherwise outrank the actual
        explicitly-signed Total deposits / Total outgoings amount.
        """
        if label_index is None:
            return None

        role = str(role or "").strip().lower()
        candidates: list[tuple] = []

        for index in range(
            max(0, label_index - radius),
            min(len(lines), label_index + radius + 1),
        ):
            distance = abs(index - label_index)

            for match in money_re.finditer(lines[index]):
                token = match.group("token")
                parsed = _parse_money(token)

                if parsed is None:
                    continue

                normalized_token = re.sub(r"\s+", "", token)
                explicit_plus = normalized_token.startswith("+")
                explicit_minus = normalized_token.startswith("-")
                has_currency = bool(re.search(r"[$€£¥]", token))
                nonzero = abs(float(parsed)) > tolerance

                if role == "credit":
                    # Total deposits / money-in: explicit '+' is the strongest
                    # local observation, followed by a positive unsigned value.
                    if explicit_minus:
                        continue
                    sign_rank = (
                        0 if explicit_plus
                        else 1 if float(parsed) > 0
                        else 2
                    )
                elif role == "debit":
                    # Total outgoings / withdrawals can be printed either as a
                    # negative signed amount or as an unsigned positive total.
                    if explicit_plus:
                        continue
                    sign_rank = (
                        0 if explicit_minus
                        else 1 if float(parsed) > 0
                        else 2
                    )
                else:
                    sign_rank = 1

                candidates.append(
                    (
                        sign_rank,
                        0 if nonzero else 1,
                        distance,
                        0 if has_currency else 1,
                        -abs(float(parsed)),
                        abs(float(parsed)),
                    )
                )

        if not candidates:
            return None

        candidates.sort()
        return round(float(candidates[0][-1]), 2)

    # ------------------------------------------------------------------
    # Neutral structural authority from summary roles
    # ------------------------------------------------------------------
    deposit_index = next(
        (
            i for i, value in enumerate(folded_lines)
            if (
                value in {
                    "total deposits",
                    "total credits",
                    "total money in",
                    "total inflows",
                }
                or re.search(r"\btotal\s+deposits\b", value)
                or re.search(r"\btotal\s+credits\b", value)
                or re.search(r"\btotal\s+money\s+in\b", value)
                or re.search(r"\btotal\s+inflows\b", value)
            )
        ),
        None,
    )
    outgoing_index = next(
        (
            i for i, value in enumerate(folded_lines)
            if (
                value in {
                    "total outgoings",
                    "total debits",
                    "total money out",
                    "total withdrawals",
                    "total outflows",
                }
                or re.search(r"\btotal\s+outgoings\b", value)
                or re.search(r"\btotal\s+debits\b", value)
                or re.search(r"\btotal\s+money\s+out\b", value)
                or re.search(r"\btotal\s+withdrawals\b", value)
                or re.search(r"\btotal\s+outflows\b", value)
            )
        ),
        None,
    )

    role_credit_total = _summary_role_money(
        deposit_index,
        role="credit",
    )
    role_debit_total = _summary_role_money(
        outgoing_index,
        role="debit",
    )

    nearest_credit_total = (
        _nearest_money(deposit_index)
        if deposit_index is not None
        else None
    )
    nearest_debit_total = (
        _nearest_money(outgoing_index)
        if outgoing_index is not None
        else None
    )

    official_credits = (
        role_credit_total
        if role_credit_total is not None
        else (
            abs(nearest_credit_total)
            if nearest_credit_total is not None
            else None
        )
    )
    official_debits = (
        role_debit_total
        if role_debit_total is not None
        else (
            abs(nearest_debit_total)
            if nearest_debit_total is not None
            else None
        )
    )

    closing_balance = None
    closing_index = next(
        (
            i for i, value in enumerate(folded_lines)
            if (
                "account balance" in value
                or value in {
                    "closing balance",
                    "ending balance",
                    "current balance",
                    "final balance",
                }
            )
            and "pot" not in value
        ),
        None,
    )
    if closing_index is not None:
        closing_balance = _nearest_money(
            closing_index,
            before=3,
            after=3,
        )

    has_official_authority = (
        official_credits is not None
        and official_debits is not None
        and closing_balance is not None
    )

    def _totals(transactions: list[dict]) -> tuple[float, float]:
        credits = 0.0
        debits = 0.0

        for tx in transactions or []:
            if not isinstance(tx, dict) or not tx.get("date"):
                continue
            try:
                signed = float(
                    tx.get("signed_amount")
                    if tx.get("signed_amount") is not None
                    else tx.get("amount") or 0
                )
            except Exception:
                continue

            if signed > 0:
                credits += abs(signed)
            elif signed < 0:
                debits += abs(signed)

        return round(credits, 2), round(debits, 2)

    # ------------------------------------------------------------------
    # Historical path remains first and authoritative when reconciled.
    # ------------------------------------------------------------------
    historical = (
        _parse_standard_date_description_amount_balance_historical(raw)
        or []
    )

    if historical:
        hist_credits, hist_debits = _totals(historical)

        historical_reconciled = (
            not has_official_authority
            or (
                abs(hist_credits - official_credits) <= tolerance
                and abs(hist_debits - official_debits) <= tolerance
            )
        )

        if historical_reconciled:
            print(
                "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_PATH",
                {
                    "mode": "historical",
                    "transactions": len(
                        [tx for tx in historical if isinstance(tx, dict) and tx.get("date")]
                    ),
                    "credits": hist_credits,
                    "debits": hist_debits,
                    "reconciled": True,
                },
            )
            return historical

    # ADDITIVE v165 — same international structural family with a secondary
    # transaction date role:
    #
    #   Processed/Transaction Date | Payment/Booking/Value Date
    #   | Description | Signed Amount | Balance
    #
    # The helper has its own strict structural header guard and exact
    # reconciliation against opening, credits, debits and closing balance.
    # It is accepted only when that branch itself proves accounting + balance
    # reconciliation. No bank/country/currency/merchant/network rule is used.
    two_date_variant = (
        _parse_standard_date_description_amount_balance_two_date_variant(raw)
        or []
    )
    two_date_dated = [
        tx
        for tx in two_date_variant
        if isinstance(tx, dict) and tx.get("date")
    ]

    if (
        two_date_dated
        and all(
            tx.get("accounting_reconciled") is True
            and tx.get("balance_reconciled") is True
            for tx in two_date_dated
        )
    ):
        print(
            "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_PATH",
            {
                "mode": "two_date_structural_variant",
                "transactions": len(two_date_dated),
                "credits": round(
                    sum(
                        float(
                            tx.get("signed_amount")
                            if tx.get("signed_amount") is not None
                            else tx.get("amount") or 0
                        )
                        for tx in two_date_dated
                        if float(
                            tx.get("signed_amount")
                            if tx.get("signed_amount") is not None
                            else tx.get("amount") or 0
                        ) > 0
                    ),
                    2,
                ),
                "debits": round(
                    sum(
                        abs(
                            float(
                                tx.get("signed_amount")
                                if tx.get("signed_amount") is not None
                                else tx.get("amount") or 0
                            )
                        )
                        for tx in two_date_dated
                        if float(
                            tx.get("signed_amount")
                            if tx.get("signed_amount") is not None
                            else tx.get("amount") or 0
                        ) < 0
                    ),
                    2,
                ),
                "reconciled": True,
            },
        )
        return two_date_variant

    # The additive variant requires official accounting authority. This
    # prevents it from broadening the historical family speculatively.
    if not has_official_authority:
        return historical

    # ------------------------------------------------------------------
    # Additive family guard
    # ------------------------------------------------------------------
    def _is_family_header(value: str) -> bool:
        folded = f" {_fold(value)} "
        return (
            " date " in folded
            and any(
                marker in folded
                for marker in (
                    " description ",
                    " details ",
                    " narrative ",
                    " libelle ",
                    " operation ",
                )
            )
            and " amount " in folded
            and " balance " in folded
            and " debit " not in folded
            and " credit " not in folded
        )

    header_indices = {
        index
        for index, line in enumerate(lines)
        if _is_family_header(line)
    }

    if not header_indices:
        return historical

    date_re = re.compile(
        r"^\s*(?P<day>\d{1,2})[./-]"
        r"(?P<month>\d{1,2})[./-]"
        r"(?P<year>\d{2,4})(?=\s|$)"
    )

    def _parse_date(value: str) -> tuple[str, int] | None:
        match = date_re.match(value)
        if not match:
            return None

        try:
            year = int(match.group("year"))
            if year < 100:
                year += 2000
            parsed = datetime(
                year,
                int(match.group("month")),
                int(match.group("day")),
            )
            return parsed.strftime("%Y-%m-%d"), match.end()
        except Exception:
            return None

    # ------------------------------------------------------------------
    # Role classification
    # ------------------------------------------------------------------
    marker_re = re.compile(
        r"^\[\[(?:PAGE|OCR_GEOMETRY_AUGMENTED_PAGE)\s+\d+\]\]$",
        re.I,
    )

    legal_markers = (
        "registered office",
        "authorised by",
        "authorized by",
        "regulated by",
        "financial services register",
        "compensation scheme",
        "eligible deposits",
        "depositors",
        "financial obligations",
        "information sheet",
        "exclusions list",
        "maximum amount",
        "for more information",
        "company registered",
    )
    footer_markers = (
        "sort code",
        "account number",
        "iban",
        "bic",
        "swift",
        "page ",
    )
    non_transaction_section_markers = (
        "pot statement",
        "savings statement",
        "vault statement",
        "pocket statement",
        "there were no transactions during this period",
    )

    def _line_role(value: str) -> str:
        folded = _fold(value)

        if marker_re.match(value):
            return "FOOTER"

        if any(marker in folded for marker in non_transaction_section_markers):
            return "SUMMARY"

        if any(marker in folded for marker in legal_markers):
            return "LEGAL"

        if any(
            folded == marker
            or folded.startswith(marker + ":")
            for marker in footer_markers
        ):
            return "FOOTER"

        if _is_family_header(value):
            return "HEADER"

        if _parse_date(value) is not None:
            return "TRANSACTION"

        return "CONTINUATION"

    # ------------------------------------------------------------------
    # Build physical transaction blocks only inside the main ledger.
    # ------------------------------------------------------------------
    blocks: list[dict] = []
    current = None
    table_active = False
    main_ledger_started = False

    def _flush() -> None:
        nonlocal current
        if current is not None:
            blocks.append(current)
            current = None

    for index, line in enumerate(lines):
        role = _line_role(line)

        if role == "HEADER":
            _flush()
            table_active = True
            main_ledger_started = True
            continue

        if not table_active:
            continue

        if role == "SUMMARY":
            _flush()
            table_active = False
            # A second account/section after the main ledger is not part of
            # this account's transaction table.
            if main_ledger_started:
                break
            continue

        if role in {"LEGAL", "FOOTER"}:
            # Footer/legal text may occur on every page. It ends the current
            # physical row but not the whole repeated-header table.
            _flush()
            continue

        date_info = _parse_date(line)

        if date_info is not None:
            _flush()
            iso_date, date_end = date_info
            current = {
                "date": iso_date,
                "source_line": index,
                "date_end": date_end,
                "lines": [line],
            }
            continue

        if current is not None and role == "CONTINUATION":
            current["lines"].append(line)

    _flush()

    if not blocks:
        return historical

    # ------------------------------------------------------------------
    # Neutral observations: visible signed amount + running balance.
    # ------------------------------------------------------------------
    parsed_rows: list[dict] = []
    seen = set()
    rejected = {
        "no_terminal_pair": 0,
        "invalid_money": 0,
        "empty_description": 0,
    }

    currency = "MULTI"
    try:
        detected_currency = detect_currency(raw)
        if detected_currency:
            currency = detected_currency
    except Exception:
        pass

    for block in blocks:
        joined = _compact(" ".join(block["lines"]))
        pairs = list(pair_re.finditer(joined))

        if not pairs:
            rejected["no_terminal_pair"] += 1
            continue

        pair = pairs[-1]
        movement = _parse_money(pair.group("movement"))
        balance = _parse_money(pair.group("balance"))

        if movement is None or balance is None:
            rejected["invalid_money"] += 1
            continue

        date_info = _parse_date(joined)
        description_start = date_info[1] if date_info else 0
        description = _compact(
            joined[description_start:pair.start()]
        ).strip(" |-")

        if not description:
            rejected["empty_description"] += 1
            description = "Accounting movement"

        key = (
            block["date"],
            round(movement, 2),
            round(balance, 2),
            _fold(description),
            block["source_line"],
        )
        if key in seen:
            continue
        seen.add(key)

        parsed_rows.append({
            "date": block["date"],
            "description": description[:500],
            "visible_signed_amount": round(movement, 2),
            "balance": round(balance, 2),
            "_balance": round(balance, 2),
            "currency": currency,
            "row_role": "TRANSACTION",
            "source_line": block["source_line"],
            "parser_family": "standard_date_description_amount_balance",
        })

    if not parsed_rows:
        return historical

    # Statement order is determined structurally from dates.
    date_values = [
        datetime.strptime(row["date"], "%Y-%m-%d")
        for row in parsed_rows
    ]
    descending_pairs = sum(
        left >= right
        for left, right in zip(date_values, date_values[1:])
    )
    ascending_pairs = sum(
        left <= right
        for left, right in zip(date_values, date_values[1:])
    )
    statement_order = (
        "descending"
        if descending_pairs >= ascending_pairs
        else "ascending"
    )

    # Official opening balance is derived from the common accounting
    # equation; no synthetic transaction is created.
    opening_balance = round(
        float(closing_balance)
        - float(official_credits)
        + float(official_debits),
        2,
    )

    # Validate every visible signed amount against adjacent running balances.
    chain_rows: list[dict] = []
    chain_rejected = 0

    for index, row in enumerate(parsed_rows):
        visible = round(
            float(row["visible_signed_amount"]),
            2,
        )
        current_balance = round(float(row["balance"]), 2)

        expected = None

        if statement_order == "descending":
            older_balance = (
                round(float(parsed_rows[index + 1]["balance"]), 2)
                if index + 1 < len(parsed_rows)
                else opening_balance
            )
            expected = round(
                current_balance - older_balance,
                2,
            )
        else:
            previous_balance = (
                round(float(parsed_rows[index - 1]["balance"]), 2)
                if index > 0
                else opening_balance
            )
            expected = round(
                current_balance - previous_balance,
                2,
            )

        # The amount column is signed. Missing '+' is still a positive amount.
        if abs(expected - visible) > tolerance:
            chain_rejected += 1
            continue

        tx_type = "income" if visible > 0 else "expense"

        chain_rows.append({
            "date": row["date"],
            "description": row["description"],
            "debit": abs(visible) if visible < 0 else None,
            "credit": abs(visible) if visible > 0 else None,
            "amount": visible,
            "signed_amount": visible,
            "visible_amount": abs(visible),
            "type": tx_type,
            "currency": currency,
            "balance": current_balance,
            "_balance": current_balance,
            "locked_amount": visible,
            "_locked_amount": visible,
            "locked_type": tx_type,
            "_balance_locked": True,
            "balance_authority": True,
            "row_role": "TRANSACTION",
            "source_line": row["source_line"],
            "parser_family": "standard_date_description_amount_balance",
            "classification_source": (
                "signed_amount_plus_running_balance"
            ),
        })

    if not chain_rows:
        return historical

    rows: list[dict] = [
        {
            "balance": opening_balance,
            "balance_role": "opening",
            "row_role": "BALANCE",
        },
        *chain_rows,
        {
            "debit_total": round(float(official_debits), 2),
            "credit_total": round(float(official_credits), 2),
            "row_role": "SUMMARY",
        },
        {
            "balance": round(float(closing_balance), 2),
            "balance_role": "closing",
            "row_role": "BALANCE",
        },
    ]

    transactions = infer_balance_delta_rows(rows) or []
    dated_transactions = [
        tx
        for tx in transactions
        if isinstance(tx, dict) and tx.get("date")
    ]

    extracted_credits, extracted_debits = _totals(
        dated_transactions
    )
    credit_gap = round(
        extracted_credits - float(official_credits),
        2,
    )
    debit_gap = round(
        extracted_debits - float(official_debits),
        2,
    )
    balance_gap = round(
        opening_balance
        + extracted_credits
        - extracted_debits
        - float(closing_balance),
        2,
    )

    reconciled = (
        abs(credit_gap) <= tolerance
        and abs(debit_gap) <= tolerance
        and abs(balance_gap) <= tolerance
    )

    print(
        "STANDARD_DATE_DESCRIPTION_AMOUNT_BALANCE_ADDITIVE_AUDIT",
        {
            "statement_order": statement_order,
            "physical_blocks": len(blocks),
            "parsed_rows": len(parsed_rows),
            "chain_rows": len(chain_rows),
            "chain_rejected": chain_rejected,
            "transactions": len(dated_transactions),
            "opening_balance": opening_balance,
            "closing_balance": closing_balance,
            "official_credits": official_credits,
            "official_debits": official_debits,
            "extracted_credits": extracted_credits,
            "extracted_debits": extracted_debits,
            "credit_gap": credit_gap,
            "debit_gap": debit_gap,
            "balance_gap": balance_gap,
            "rejected": rejected,
            "reconciled": reconciled,
        },
    )

    if not reconciled:
        return historical

    for tx in transactions:
        if not isinstance(tx, dict):
            continue

        tx["parser_family"] = (
            "standard_date_description_amount_balance"
        )
        tx["_statement_opening_balance"] = opening_balance
        tx["_statement_closing_balance"] = round(
            float(closing_balance),
            2,
        )
        tx["_official_credit_total"] = round(
            float(official_credits),
            2,
        )
        tx["_official_debit_total"] = round(
            float(official_debits),
            2,
        )

        # ADDITIVE v164 — expose the parser's exact local reconciliation to
        # the existing candidate-evidence contract. This executes only after
        # credit_gap, debit_gap and balance_gap all passed the strict tolerance.
        if tx.get("date"):
            tx["accounting_reconciled"] = True
            tx["balance_reconciled"] = True

    return transactions



def extract_td_account_summary(text: str) -> dict:
    """
    TD / standard account summary extractor.

    Reads the ACCOUNT SUMMARY block only.
    Prevents mixing later check-image pages or old statement sections.
    """
    import re

    raw_full = str(text or "")
    raw = " ".join(raw_full.replace("\n", " ").split())
    low = raw.lower()  # noqa: F841

    if not (
        "account summary" in low
        and "beginning balance" in low
        and "electronic payments" in low
        and "other withdrawals" in low
    ):
        return {}

    money = r"\$?\s*(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{2})"

    def clean(x):
        return round(float(str(x).replace("$", "").replace(",", "").strip()), 2)

    # Limit extraction from ACCOUNT SUMMARY until DAILY ACCOUNT ACTIVITY.
    m_block = re.search(r"ACCOUNT SUMMARY(.+?)(?:DAILY ACCOUNT ACTIVITY|How to Balance your Account|Page 2)", raw, flags=re.I)
    block = m_block.group(1) if m_block else raw

    def find(label, source=None):
        source = source or block
        m = re.search(label + r"\s+(" + money + r")", source, flags=re.I)
        if m:
            return clean(m.group(1))
        return None

    opening = find(r"Beginning Balance")
    deposits = find(r"\bDeposits\b") or 0.0
    electronic_deposits = find(r"Electronics? Deposits") or 0.0
    electronic_payments = find(r"Electronic Payments") or 0.0
    other_withdrawals = find(r"Other Withdrawals") or 0.0

    ending = find(r"Ending Balance")
    if ending is None:
        # TD sometimes prints the ending balance on the next "How to Balance" page.
        m_end = re.search(
            r"Your ending balance shown on this\s+statement is:\s*.*?Ending\s+Balance\s+(" + money + r")",
            raw,
            flags=re.I,
        )
        if not m_end:
            m_end = re.search(
                r"Ending\s+Balance\s+(" + money + r")\s+(?:Total\s+Deposits|DEPOSITS\s+NOT\s+ON\s+STATEMENT)",
                raw,
                flags=re.I,
            )
        if m_end:
            ending = clean(m_end.group(1))

    total_deposits = round(deposits + electronic_deposits, 2)
    total_withdrawals = round(electronic_payments + other_withdrawals, 2)

    out = {}
    if opening is not None:
        out["opening_balance"] = opening
    if total_deposits:
        out["deposits"] = total_deposits
    if total_withdrawals:
        out["withdrawals"] = total_withdrawals
    if ending is not None:
        out["ending_balance"] = ending

    return out if len(out) >= 3 else {}



def parse_standard_date_particulars_debit_credit_balance(text: str) -> list[dict]:
    """Parse the international structural family:

        Date | Particulars/Description | Debit | Credit | Balance

    Evolution policy:
      * historical paths remain first;
      * every path is validated before it can return;
      * additive paths use only table geometry, line roles, balances and totals;
      * no institution, country, currency, merchant or commercial-label rule;
      * all successful paths finish through infer_balance_delta_rows(rows);
      * flattened multiline blocks use deterministic balance-window recovery.

    Required shared helpers:
      parse_amount, clean_db_text, infer_balance_delta_rows,
      extract_official_movement_totals, extract_global_statement_summary.
    """
    import re
    import unicodedata
    from datetime import datetime

    raw = str(text or "")
    if not raw.strip():
        return []

    # Synthetic geometry observations are not document text. They are available
    # only to the final additive fallback.
    document_raw = "\n".join(
        line
        for line in raw.splitlines()
        if not str(line or "").lstrip().upper().startswith(
            "MONEY_LEDGER_POSITION_TX "
        )
    )

    tolerance = float(globals().get("RUNEXA_STRICT_TOLERANCE", 0.02))
    family = "standard_date_particulars_debit_credit_balance"

    def compact(value: str) -> str:
        return re.sub(
            r"\s+",
            " ",
            str(value or "").replace("\xa0", " ").replace("\u202f", " "),
        ).strip()

    def fold(value: str) -> str:
        normalized = unicodedata.normalize("NFKD", str(value or ""))
        normalized = "".join(
            character
            for character in normalized
            if not unicodedata.combining(character)
        )
        return compact(normalized).casefold()

    # Structural labels only. These labels identify column/row roles and never
    # classify a transaction by its commercial description.
    DATE_LABELS = ("date", "تاريخ", "التاريخ")
    DESCRIPTION_LABELS = (
        "particulars", "description", "details", "narrative",
        "libelle", "libellé", "operation", "opération", "البيان", "الوصف",
    )
    DEBIT_LABELS = (
        "debit", "debits", "débit", "débits", "withdraw", "withdrawal", "withdrawals",
        "money out", "مدين", "خصم",
    )
    CREDIT_LABELS = (
        "credit", "credits", "crédit", "crédits", "deposit", "deposits",
        "money in", "دائن", "إيداع", "ايداع",
    )
    BALANCE_LABELS = (
        "balance", "solde", "running balance", "الرصيد",
    )

    def first_label_position(value: str, labels: tuple[str, ...]) -> int | None:
        folded = fold(value)
        positions = [folded.find(fold(label)) for label in labels]
        positions = [position for position in positions if position >= 0]
        return min(positions) if positions else None

    def header_columns(value: str) -> dict | None:
        positions = {
            "date": first_label_position(value, DATE_LABELS),
            "description": first_label_position(value, DESCRIPTION_LABELS),
            "debit": first_label_position(value, DEBIT_LABELS),
            "credit": first_label_position(value, CREDIT_LABELS),
            "balance": first_label_position(value, BALANCE_LABELS),
        }
        if any(position is None for position in positions.values()):
            return None

        ordered = [
            positions["date"], positions["description"], positions["debit"],
            positions["credit"], positions["balance"],
        ]
        if ordered == sorted(ordered):
            positions["direction"] = "LTR"
            return positions

        reverse_ordered = [
            positions["balance"], positions["credit"], positions["debit"],
            positions["description"], positions["date"],
        ]
        if reverse_ordered == sorted(reverse_ordered):
            positions["direction"] = "RTL"
            return positions

        return None

    physical_lines = [str(line or "").rstrip("\n") for line in document_raw.splitlines()]
    headers = [
        (index, header_columns(line))
        for index, line in enumerate(physical_lines)
        if header_columns(line) is not None
    ]
    if not headers:
        return []

    # English/French month names are structural date syntax. Numeric dates and
    # Arabic-digit numeric dates are also accepted independently of locale.
    month_numbers = {
        "jan": 1, "january": 1, "janv": 1, "janvier": 1,
        "feb": 2, "february": 2, "fev": 2, "fevr": 2, "fevrier": 2,
        "mar": 3, "march": 3, "mars": 3,
        "apr": 4, "april": 4, "avr": 4, "avril": 4,
        "may": 5, "mai": 5,
        "jun": 6, "june": 6, "juin": 6,
        "jul": 7, "july": 7, "juil": 7, "juillet": 7,
        "aug": 8, "august": 8, "aout": 8,
        "sep": 9, "sept": 9, "september": 9, "septembre": 9,
        "oct": 10, "october": 10, "octobre": 10,
        "nov": 11, "november": 11, "novembre": 11,
        "dec": 12, "december": 12, "decembre": 12,
    }
    textual_date_re = re.compile(
        r"\b(?P<day>\d{1,2})\s+"
        r"(?P<month>Jan(?:uary|v(?:ier)?)?|Feb(?:ruary)?|Fev(?:r(?:ier)?)?|"
        r"Mar(?:ch|s)?|Apr(?:il)?|Avr(?:il)?|May|Mai|Jun(?:e|in)?|"
        r"Jul(?:y|let)?|Juil(?:let)?|Aug(?:ust)?|Aout|Sep(?:t(?:ember|embre)?)?|"
        r"Oct(?:ober|obre)?|Nov(?:ember|embre)?|Dec(?:ember|embre)?)"
        r"\s+(?P<year>\d{2}|\d{4})\b",
        re.IGNORECASE,
    )
    hyphen_textual_date_re = re.compile(
        r"\b(?P<day>\d{1,2})[-–—](?P<month>"
        r"Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|"
        r"Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|"
        r"Nov(?:ember)?|Dec(?:ember)?)"
        r"[-–—](?P<year>\d{2}|\d{4})\b",
        re.IGNORECASE,
    )
    numeric_date_re = re.compile(
        r"\b(?P<a>\d{1,2})[./-](?P<b>\d{1,2})[./-](?P<year>\d{2}|\d{4})\b"
    )
    money_re = re.compile(
        r"(?<![\d/])(?:[$€£¥]\s*)?"
        r"(?:\d{1,3}(?:[,.]\d{3})+|\d+)(?:[.,]\d{2})(?!\d)"
    )
    balance_re = re.compile(
        r"(?P<amount>(?:\d{1,3}(?:[,.]\d{3})+|\d+)(?:[.,]\d{2}))"
        r"\s*(?P<role>Cr|Dr|C|D)\b",
        re.IGNORECASE,
    )

    # ADDITIVE v136 — compact posting dates with statement-period year authority.
    #
    # Structural variants such as 31OCT / 01NOV / 27 FEB omit the year from
    # each transaction row while the statement period supplies exact bounds.
    # Resolve a compact date only when exactly one candidate calendar date lies
    # inside the printed statement period.  This makes the 2023 -> 2024 rollover
    # deterministic without bank, country, currency, merchant, or language
    # assumptions.
    compact_date_re = re.compile(
        r"^\s*(?P<day>\d{1,2})\s*"
        r"(?P<month>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)"
        r"(?=\s|$|[^A-Za-z])",
        re.IGNORECASE,
    )

    statement_period_bounds = None
    period_match = re.search(
        r"(?i)statement\s+period[^\d]{0,20}"
        r"(?P<d1>\d{1,2})[./-](?P<m1>\d{1,2})[./-](?P<y1>\d{4})"
        r"\s*(?:to|[-–—])\s*"
        r"(?P<d2>\d{1,2})[./-](?P<m2>\d{1,2})[./-](?P<y2>\d{4})",
        document_raw,
    )
    if period_match:
        try:
            period_start = datetime(
                int(period_match.group("y1")),
                int(period_match.group("m1")),
                int(period_match.group("d1")),
            )
            period_end = datetime(
                int(period_match.group("y2")),
                int(period_match.group("m2")),
                int(period_match.group("d2")),
            )
            if period_start <= period_end and (period_end - period_start).days <= 550:
                statement_period_bounds = (period_start, period_end)
        except (TypeError, ValueError):
            statement_period_bounds = None

    def normalize_year(year: int) -> int:
        if year < 100:
            return year + (2000 if year < 70 else 1900)
        return year

    def parse_date_match(value: str):
        compact_match = compact_date_re.search(value)
        if compact_match and statement_period_bounds is not None:
            month = month_numbers.get(
                fold(compact_match.group("month"))[:3]
            )
            day = int(compact_match.group("day"))
            if month is not None and 1 <= day <= 31:
                period_start, period_end = statement_period_bounds
                candidates = []
                for year in range(period_start.year, period_end.year + 1):
                    try:
                        candidate = datetime(year, month, day)
                    except ValueError:
                        continue
                    if period_start <= candidate <= period_end:
                        candidates.append(candidate)
                if len(candidates) == 1:
                    return (
                        candidates[0].strftime("%Y-%m-%d"),
                        compact_match,
                    )

        hyphen_textual = hyphen_textual_date_re.search(value)
        if hyphen_textual:
            month_key = fold(hyphen_textual.group("month"))
            month = month_numbers.get(month_key)
            if month is None:
                month = month_numbers.get(month_key[:4]) or month_numbers.get(month_key[:3])
            if month is not None:
                year = normalize_year(int(hyphen_textual.group("year")))
                day = int(hyphen_textual.group("day"))
                if 1 <= day <= 31:
                    return f"{year:04d}-{month:02d}-{day:02d}", hyphen_textual

        textual = textual_date_re.search(value)
        if textual:
            month_key = fold(textual.group("month"))
            month = month_numbers.get(month_key)
            if month is None:
                # Try stable prefixes after accent folding.
                month = month_numbers.get(month_key[:4]) or month_numbers.get(month_key[:3])
            if month is not None:
                year = normalize_year(int(textual.group("year")))
                day = int(textual.group("day"))
                if 1 <= day <= 31:
                    return f"{year:04d}-{month:02d}-{day:02d}", textual

        numeric = numeric_date_re.search(value)
        if numeric:
            first = int(numeric.group("a"))
            second = int(numeric.group("b"))
            year = normalize_year(int(numeric.group("year")))
            # International neutral rule: resolve only unambiguous DMY/MDY.
            if first > 12 and 1 <= second <= 12:
                day, month = first, second
            elif second > 12 and 1 <= first <= 12:
                month, day = first, second
            else:
                return None
            if 1 <= day <= 31:
                return f"{year:04d}-{month:02d}-{day:02d}", numeric
        return None

    def parse_money(value: str) -> float | None:
        try:
            return round(abs(float(parse_amount(value))), 2)
        except Exception:
            return None

    summary = extract_global_statement_summary(document_raw) or {}
    movements = extract_official_movement_totals(document_raw) or {}

    # ADDITIVE v140 — incomplete one-sided summary observations are not
    # accounting authority for this structural family.  A certificate/footer
    # can legitimately contain a labelled credit balance without providing
    # the statement's debit/credit movement totals.  Use flow totals only as
    # a complete debit+credit pair and balances only as an opening+closing pair.
    raw_opening = summary.get("opening_balance")
    raw_closing = summary.get("ending_balance")
    raw_debits = movements.get("debit_total", summary.get("withdrawals"))
    raw_credits = movements.get("credit_total", summary.get("deposits"))

    if not (raw_debits is not None and raw_credits is not None):
        raw_debits = None
        raw_credits = None
    if not (raw_opening is not None and raw_closing is not None):
        raw_opening = None
        raw_closing = None

    official = {
        "opening": raw_opening,
        "closing": raw_closing,
        "debits": raw_debits,
        "credits": raw_credits,
    }

    def transaction_totals(transactions: list[dict]) -> tuple[float, float]:
        debits = 0.0
        credits = 0.0
        for transaction in transactions or []:
            if not isinstance(transaction, dict) or not transaction.get("date"):
                continue
            try:
                debits += abs(float(transaction.get("debit") or 0))
                credits += abs(float(transaction.get("credit") or 0))
            except Exception:
                continue
        return round(debits, 2), round(credits, 2)

    def reconciles(transactions: list[dict]) -> bool:
        if not transactions:
            return False
        debits, credits = transaction_totals(transactions)
        if official["debits"] is not None:
            if abs(debits - abs(float(official["debits"]))) > tolerance:
                return False
        if official["credits"] is not None:
            if abs(credits - abs(float(official["credits"]))) > tolerance:
                return False
        if (
            official["opening"] is not None
            and official["closing"] is not None
        ):
            identity_gap = (
                float(official["opening"])
                + credits
                - debits
                - float(official["closing"])
            )
            if abs(identity_gap) > tolerance:
                return False
        return True

    def normalize_terminal_balances(rows: list[dict]) -> list[dict]:
        """Keep a repeated group balance only on the final transaction row."""
        normalized = [dict(row) for row in rows if isinstance(row, dict)]
        index = 0
        while index < len(normalized):
            row = normalized[index]
            balance = row.get("balance")
            if balance is None or not row.get("date"):
                index += 1
                continue
            end = index
            while end + 1 < len(normalized):
                following = normalized[end + 1]
                if following.get("date") != row.get("date"):
                    break
                next_balance = following.get("balance")
                if next_balance is None:
                    break
                try:
                    same = abs(float(next_balance) - float(balance)) <= tolerance
                except Exception:
                    same = next_balance == balance
                if not same:
                    break
                end += 1
            for current in range(index, end):
                normalized[current]["balance"] = None
                normalized[current]["_balance"] = None
            index = end + 1
        return normalized

    def finalize(rows: list[dict], source: str) -> list[dict]:
        if not rows:
            return []

        observations = normalize_terminal_balances(rows)
        if not observations:
            return []

        for observation in observations:
            observation["parser_family"] = family
            observation["classification_source"] = source
            observation["_statement_opening_balance"] = official["opening"]
            observation["_statement_closing_balance"] = official["closing"]
            observation["_official_debit_total"] = official["debits"]
            observation["_official_credit_total"] = official["credits"]

        transactions = infer_balance_delta_rows(observations) or []
        dated = [
            transaction
            for transaction in transactions
            if isinstance(transaction, dict) and transaction.get("date")
        ]
        valid = reconciles(dated)
        debits, credits = transaction_totals(dated)
        print("STANDARD_DATE_PARTICULARS_DCB_AUDIT", {
            "source": source,
            "observations": len(observations),
            "transactions": len(dated),
            "debits": debits,
            "credits": credits,
            "official_debits": official["debits"],
            "official_credits": official["credits"],
            "reconciled": valid,
        })

        # When official totals exist, an unreconciled branch must abstain.
        if official["debits"] is not None or official["credits"] is not None:
            return transactions if valid else []
        return transactions

    def line_role(value: str) -> str:
        folded = fold(value)
        if header_columns(value) is not None:
            return "HEADER"
        if re.search(r"\b(?:page|pagina|صفحة)\s*\d+", folded):
            return "FOOTER"
        if any(marker in folded for marker in (
            "statement number", "account number", "numero de compte",
            "رقم الحساب", "iban", "swift", "bic",
        )):
            return "FOOTER"
        if any(marker in folded for marker in (
            "terms and conditions", "for your information", "legal notice",
            "mentions legales", "الشروط والاحكام", "معلومات قانونية",
        )):
            return "LEGAL"
        if any(marker in folded for marker in (
            "total debit", "total debits", "total credit", "total credits",
            "total des debits", "total des credits", "اجمالي المدين",
            "اجمالي الدائن",
        )):
            return "TOTAL"
        if any(marker in folded for marker in (
            "account summary", "balance summary", "resume du compte",
            "ملخص الحساب",
        )):
            return "SUMMARY"
        if any(marker in folded for marker in (
            "opening balance", "closing balance", "ending balance",
            "brought forward", "carried forward", "solde initial",
            "solde final", "report a nouveau", "الرصيد الافتتاحي",
            "الرصيد الختامي",
        )):
            return "BALANCE"
        if parse_date_match(value) is not None:
            return "TRANSACTION"
        return "CONTINUATION"

    # ------------------------------------------------------------------
    # 1. Historical compact rows. This path remains first, but it can return
    #    only after common accounting inference and reconciliation.
    # ------------------------------------------------------------------
    historical_rows: list[dict] = []
    active_columns = None
    for source_index, source_line in enumerate(physical_lines):
        role = line_role(source_line)
        if role == "HEADER":
            active_columns = header_columns(source_line)
            continue
        if active_columns is None or role in {
            "BALANCE", "TOTAL", "SUMMARY", "FOOTER", "LEGAL"
        }:
            continue

        date_info = parse_date_match(source_line)
        if date_info is None:
            continue
        iso_date, date_match = date_info
        matches = list(money_re.finditer(source_line))
        if not matches:
            continue

        description_position = active_columns["description"]
        debit_position = active_columns["debit"]
        credit_position = active_columns["credit"]
        balance_position = active_columns["balance"]
        debit_credit_boundary = (debit_position + credit_position) / 2.0
        credit_balance_boundary = (credit_position + balance_position) / 2.0

        movement_match = None
        movement_role = None
        running_balance = None
        for match in matches:
            value = parse_money(match.group(0))
            if value is None:
                continue
            if match.start() >= credit_balance_boundary:
                running_balance = value
                suffix = source_line[match.end():match.end() + 6]
                if re.search(r"\b(?:Dr|D)\b", suffix, re.IGNORECASE):
                    running_balance = -running_balance
            elif match.start() >= description_position:
                movement_match = match
                movement_role = (
                    "credit" if match.start() >= debit_credit_boundary else "debit"
                )

        if movement_match is None:
            continue
        movement = parse_money(movement_match.group(0))
        if movement is None:
            continue
        description = clean_db_text(
            source_line[date_match.end():movement_match.start()]
        )[:500] or "accounting movement"
        historical_rows.append({
            "date": iso_date,
            "description": description,
            "debit": movement if movement_role == "debit" else None,
            "credit": movement if movement_role == "credit" else None,
            "balance": running_balance,
            "_balance": running_balance,
            "row_role": "TRANSACTION",
            "_source_line_index": source_index,
        })

    historical = finalize(historical_rows, "historical_compact_geometry")
    if historical:
        return historical

    # ------------------------------------------------------------------
    # ADDITIVE v184.3 — EARLY structural-family abstention.
    #
    # This generic parser represents:
    #     Date | Description | Debit | Credit | Balance
    #
    # When the header exposes a SECOND explicit date role between Description
    # and Debit, the structure belongs to the more specific family:
    #     Date | Description | Transaction/Value Date | Debit | Credit | Balance
    #
    # The historical path above remains first and unchanged. If it abstains,
    # this generic parser must not enter either:
    #   - its layout-preserving sign-assignment solver, or
    #   - its later flattened subset solver.
    #
    # The rule is purely structural and uses no institution/country/currency/
    # merchant/network identity.
    def _header_has_secondary_date_role_early(header_line: str) -> bool:
        folded_header = fold(header_line)
        description_position = first_label_position(
            folded_header,
            DESCRIPTION_LABELS,
        )
        debit_position = first_label_position(
            folded_header,
            DEBIT_LABELS,
        )
        if (
            description_position is None
            or debit_position is None
            or description_position >= debit_position
        ):
            return False

        between_description_and_debit = folded_header[
            description_position:debit_position
        ]

        return bool(
            re.search(
                r"(?<![a-z0-9])(?:date|تاريخ|التاريخ)(?![a-z0-9])",
                between_description_and_debit,
                flags=re.IGNORECASE,
            )
        )

    early_secondary_date_headers = [
        physical_lines[index]
        for index, _columns in headers
        if _header_has_secondary_date_role_early(physical_lines[index])
    ]

    if early_secondary_date_headers:
        print(
            "STANDARD_DATE_PARTICULARS_DCB_EARLY_SKIPPED",
            {
                "reason": "secondary_date_column_belongs_to_specific_family",
                "headers": len(early_secondary_date_headers),
                "samples": early_secondary_date_headers[:5],
                "layout_solver_entered": False,
                "flattened_solver_entered": False,
            },
        )
        return []

    # ------------------------------------------------------------------
    # 2. Layout-preserving multiline geometry.
    # ------------------------------------------------------------------
    geometry_rows: list[dict] = []
    active_columns = None
    current_date = None
    continuation_parts: list[str] = []
    seen = set()

    for source_index, source_line in enumerate(physical_lines):
        role = line_role(source_line)
        if role == "HEADER":
            active_columns = header_columns(source_line)
            current_date = None
            continuation_parts = []
            continue
        if active_columns is None:
            continue
        if role in {"BALANCE", "TOTAL", "SUMMARY", "FOOTER", "LEGAL"}:
            continuation_parts = []
            continue

        date_info = parse_date_match(source_line)
        if date_info is not None:
            current_date, date_match = date_info
            continuation_parts = []
        else:
            date_match = None

        matches = list(money_re.finditer(source_line))
        if not matches:
            cleaned = clean_db_text(source_line)
            if cleaned and role == "CONTINUATION":
                continuation_parts.append(cleaned)
            continue
        if not current_date:
            continue

        debit_position = active_columns["debit"]
        credit_position = active_columns["credit"]
        balance_position = active_columns["balance"]
        description_position = active_columns["description"]
        debit_credit_boundary = (debit_position + credit_position) / 2.0
        credit_balance_boundary = (credit_position + balance_position) / 2.0

        movement_candidates = []
        running_balance = None
        for match in matches:
            value = parse_money(match.group(0))
            if value is None:
                continue
            if match.start() >= credit_balance_boundary:
                running_balance = value
                suffix = source_line[match.end():match.end() + 6]
                if re.search(r"\b(?:Dr|D)\b", suffix, re.IGNORECASE):
                    running_balance = -running_balance
                continue
            if match.start() < description_position:
                continue
            direction = (
                "credit" if match.start() >= debit_credit_boundary else "debit"
            )
            movement_candidates.append((match, direction, value))

        if not movement_candidates:
            continue

        for movement_index, (match, direction, value) in enumerate(movement_candidates):
            description_start = date_match.end() if date_match is not None else 0
            local_description = clean_db_text(
                source_line[description_start:match.start()]
            )
            description = clean_db_text(
                " ".join(continuation_parts + [local_description])
            )[:500] or "accounting movement"
            identity = (
                current_date, source_index, movement_index, direction, value
            )
            if identity in seen:
                continue
            seen.add(identity)
            is_last = movement_index == len(movement_candidates) - 1
            geometry_rows.append({
                "date": current_date,
                "description": description,
                "debit": value if direction == "debit" else None,
                "credit": value if direction == "credit" else None,
                "balance": running_balance if is_last else None,
                "_balance": running_balance if is_last else None,
                "row_role": "TRANSACTION",
                "_source_line_index": source_index,
            })
            continuation_parts = []

    # Use balance deltas only to correct ambiguous column-boundary directions.
    try:
        previous_balance = (
            float(official["opening"])
            if official["opening"] is not None
            else None
        )
    except Exception:
        previous_balance = None

    if geometry_rows and previous_balance is not None:
        group: list[dict] = []
        for row in geometry_rows:
            group.append(row)
            if row.get("balance") is None:
                continue
            current_balance = float(row["balance"])
            target = int(round((current_balance - previous_balance) * 100))
            states = {0: (0, [])}
            for item in group:
                value = int(round(abs(float(
                    item.get("debit") or item.get("credit") or 0
                )) * 100))
                original_sign = 1 if item.get("credit") is not None else -1
                next_states = {}
                for subtotal, (cost, assignment) in states.items():
                    for sign in (-1, 1):
                        candidate_sum = subtotal + sign * value
                        candidate = (
                            cost + int(sign != original_sign),
                            assignment + [sign],
                        )
                        existing = next_states.get(candidate_sum)
                        if existing is None or candidate[0] < existing[0]:
                            next_states[candidate_sum] = candidate
                states = next_states
            solution = states.get(target)
            if solution is not None:
                for item, sign in zip(group, solution[1]):
                    value = round(abs(float(
                        item.get("debit") or item.get("credit") or 0
                    )), 2)
                    item["debit"] = value if sign < 0 else None
                    item["credit"] = value if sign > 0 else None
            previous_balance = current_balance
            group = []

    geometry = finalize(geometry_rows, "multiline_column_geometry")
    if geometry:
        return geometry

    # ------------------------------------------------------------------
    # ADDITIVE v184.2 — structural-family abstention before the expensive
    # flattened subset solver.
    #
    # This generic family represents:
    #     Date | Description | Debit | Credit | Balance
    #
    # A header that exposes a SECOND explicit date role between Description
    # and Debit belongs instead to the more specific family:
    #     Date | Description | Transaction/Value Date | Debit | Credit | Balance
    #
    # That more specific parser participates independently in the common
    # candidate engine. Once both historical paths above have abstained, this
    # generic parser must not reinterpret numeric continuation tokens through
    # solve_signed_subset(). Doing so is both structurally inappropriate and
    # potentially very expensive on long statements containing references,
    # card numbers, dates and auxiliary amounts.
    #
    # The rule is purely structural: no bank, country, currency, merchant,
    # network or language identity is used.
    def _header_has_secondary_date_role(header_line: str) -> bool:
        folded_header = fold(header_line)

        description_position = first_label_position(
            folded_header,
            DESCRIPTION_LABELS,
        )
        debit_position = first_label_position(
            folded_header,
            DEBIT_LABELS,
        )

        if (
            description_position is None
            or debit_position is None
            or description_position >= debit_position
        ):
            return False

        between_description_and_debit = folded_header[
            description_position:debit_position
        ]

        date_role_matches = list(
            re.finditer(
                r"(?<![a-z0-9])(?:date|تاريخ|التاريخ)(?![a-z0-9])",
                between_description_and_debit,
                flags=re.IGNORECASE,
            )
        )

        return bool(date_role_matches)

    secondary_date_headers = [
        physical_lines[index]
        for index, _columns in headers
        if _header_has_secondary_date_role(physical_lines[index])
    ]

    if secondary_date_headers:
        print(
            "STANDARD_DATE_PARTICULARS_DCB_FLATTENED_SKIPPED",
            {
                "reason": "secondary_date_column_belongs_to_specific_family",
                "headers": len(secondary_date_headers),
                "samples": secondary_date_headers[:5],
                "solver_entered": False,
            },
        )
        return []

    # ------------------------------------------------------------------
    # 3. Flattened date/balance blocks. This additive path is activated only
    #    after both historical geometry paths abstain.
    # ------------------------------------------------------------------
    def split_at_posting_dates(lines: list[str]) -> list[dict]:
        logical: list[dict] = []
        for physical_index, physical_line in enumerate(lines):
            value = compact(physical_line)
            if not value:
                continue
            matches = list(textual_date_re.finditer(value))
            matches.extend(numeric_date_re.finditer(value))
            matches = sorted(matches, key=lambda match: match.start())
            # Keep only date matches that parse unambiguously.
            matches = [
                match
                for match in matches
                if parse_date_match(match.group(0)) is not None
            ]
            if not matches:
                logical.append({
                    "text": value,
                    "physical_index": physical_index,
                    "starts_with_date": False,
                })
                continue
            if matches[0].start() > 0:
                prefix = value[:matches[0].start()].strip()
                if prefix:
                    logical.append({
                        "text": prefix,
                        "physical_index": physical_index,
                        "starts_with_date": False,
                    })
            for index, match in enumerate(matches):
                end = matches[index + 1].start() if index + 1 < len(matches) else len(value)
                logical.append({
                    "text": value[match.start():end].strip(),
                    "physical_index": physical_index,
                    "starts_with_date": True,
                })
        return logical

    completed_blocks: list[dict] = []
    active_table = False
    current_block = None

    def close_block() -> None:
        nonlocal current_block
        if current_block is not None:
            completed_blocks.append(current_block)
            current_block = None

    for logical in split_at_posting_dates(physical_lines):
        source = logical["text"]
        role = line_role(source)
        if role == "HEADER":
            close_block()
            active_table = True
            continue
        if not active_table:
            continue
        if role in {"TOTAL", "SUMMARY", "LEGAL"}:
            close_block()
            active_table = False
            continue
        if role == "FOOTER":
            close_block()
            continue
        if role == "BALANCE":
            # Carry rows may contain a useful balance anchor but no movement.
            if current_block is not None:
                current_block["parts"].append(source)
                current_block["source_indexes"].append(logical["physical_index"])
            continue

        date_info = parse_date_match(source)
        if date_info is not None and logical["starts_with_date"]:
            close_block()
            iso_date, date_match = date_info
            current_block = {
                "date": iso_date,
                "parts": [],
                "source_indexes": [logical["physical_index"]],
            }
            remainder = source[date_match.end():].strip()
            if remainder:
                current_block["parts"].append(remainder)
            continue
        if current_block is not None:
            current_block["parts"].append(source)
            current_block["source_indexes"].append(logical["physical_index"])
    close_block()

    def solve_signed_subset(values: list[int], target: int):
        """Return the strongest deterministic -1/0/+1 balance assignment.

        Structural priorities, in order:

        1. exact agreement with the observed balance delta;
        2. retain the largest number of visible monetary observations;
        3. minimize movements opposite to the net balance direction;
        4. deterministic lexical tie-break.

        The historical branch previously rejected every tied solution. That
        discarded complete multiline blocks even when all tied assignments
        reached the same observed running balance. The new behavior remains
        additive and local: it is used only after both historical geometry
        paths have abstained, and the completed ledger must still reconcile
        against the official statement totals before it can return.
        """
        MAX_VALUES = 30
        MAX_STATES = 60000
        MAX_TRANSITIONS = 2_000_000

        if len(values) > MAX_VALUES:
            return None
        if not values:
            return [] if target == 0 else None

        target_direction = 1 if target > 0 else (-1 if target < 0 else 0)

        # subtotal -> (used_count, opposite_direction_count, assignment)
        states: dict[int, tuple[int, int, tuple[int, ...]]] = {
            0: (0, 0, ())
        }
        transitions = 0
        remaining = sum(abs(value) for value in values)

        def better(
            candidate: tuple[int, int, tuple[int, ...]],
            existing: tuple[int, int, tuple[int, ...]] | None,
        ) -> bool:
            if existing is None:
                return True

            candidate_key = (
                -candidate[0],
                candidate[1],
                tuple(
                    0 if sign == target_direction and sign != 0
                    else 1 if sign == 0
                    else 2
                    for sign in candidate[2]
                ),
                candidate[2],
            )
            existing_key = (
                -existing[0],
                existing[1],
                tuple(
                    0 if sign == target_direction and sign != 0
                    else 1 if sign == 0
                    else 2
                    for sign in existing[2]
                ),
                existing[2],
            )
            return candidate_key < existing_key

        for value in values:
            remaining -= abs(value)
            next_states: dict[int, tuple[int, int, tuple[int, ...]]] = {}
            lower = target - remaining
            upper = target + remaining

            # Neutral first, then the direction of the observed delta, then the
            # opposite direction. The explicit comparator below remains the
            # authority; this order only improves deterministic pruning.
            sign_order = (
                (0, target_direction, -target_direction)
                if target_direction
                else (0, -1, 1)
            )

            for subtotal, (used, opposite, assignment) in states.items():
                for sign in sign_order:
                    transitions += 1
                    if transitions > MAX_TRANSITIONS:
                        return None

                    new_total = subtotal + sign * value
                    if new_total < lower or new_total > upper:
                        continue

                    candidate = (
                        used + int(sign != 0),
                        opposite + int(
                            target_direction != 0
                            and sign != 0
                            and sign != target_direction
                        ),
                        assignment + (sign,),
                    )
                    if better(candidate, next_states.get(new_total)):
                        next_states[new_total] = candidate

            if not next_states:
                return None

            if len(next_states) > MAX_STATES:
                retained_totals = sorted(
                    next_states,
                    key=lambda subtotal: (
                        abs(subtotal - target),
                        -next_states[subtotal][0],
                        next_states[subtotal][1],
                        subtotal,
                    ),
                )[:MAX_STATES]
                next_states = {
                    subtotal: next_states[subtotal]
                    for subtotal in retained_totals
                }

            states = next_states

        result = states.get(target)
        if result is None:
            return None
        return list(result[2])

    parsed_blocks: list[dict] = []
    for block in completed_blocks:
        block_text = clean_db_text(" ".join(block["parts"]))
        if not block_text:
            continue
        terminal_matches = list(balance_re.finditer(block_text))
        if not terminal_matches:
            continue
        terminal = terminal_matches[-1]
        terminal_balance = parse_money(terminal.group("amount"))
        if terminal_balance is None:
            continue
        if terminal.group("role").casefold() in {"dr", "d"}:
            terminal_balance = -terminal_balance
        movement_source = block_text[:terminal.start()].strip()
        # Remove structural carry rows without institution-specific wording.
        movement_source = re.sub(
            r"\b(?:brought|carried)\s+forward\s+"
            r"(?:\d{1,3}(?:[,.]\d{3})+|\d+)(?:[.,]\d{2})"
            r"\s*(?:Cr|Dr|C|D)\b",
            " ",
            movement_source,
            flags=re.IGNORECASE,
        )
        candidate_matches = list(money_re.finditer(movement_source))
        candidates = []
        for candidate_match in candidate_matches:
            value = parse_money(candidate_match.group(0))
            if value is None or value <= 0:
                continue
            candidates.append({
                "value": value,
                "start": candidate_match.start(),
                "end": candidate_match.end(),
            })
        parsed_blocks.append({
            **block,
            "movement_source": movement_source,
            "candidates": candidates,
            "terminal_balance": terminal_balance,
        })

    flattened_rows: list[dict] = []
    try:
        anchor_balance = (
            float(official["opening"])
            if official["opening"] is not None
            else None
        )
    except Exception:
        anchor_balance = None

    unresolved_window: list[dict] = []
    resolved_windows = 0
    unresolved_windows = 0
    flattened_branch_failed = False

    # Additive limits for flattened multiline statements. The historical value
    # of three blocks was too small for long statement pages where several
    # posting-date groups share one terminal balance anchor.
    MAX_WINDOW_BLOCKS = 8
    MAX_WINDOW_CANDIDATES = 30

    def emit_window(window: list[dict], start_balance: float, end_balance: float) -> bool:
        nonlocal resolved_windows
        if not window or len(window) > MAX_WINDOW_BLOCKS:
            return False
        all_candidates = [
            (block, candidate)
            for block in window
            for candidate in block["candidates"]
        ]
        if len(all_candidates) > MAX_WINDOW_CANDIDATES:
            return False
        values = [
            int(round(candidate["value"] * 100))
            for _, candidate in all_candidates
        ]
        target = int(round((end_balance - start_balance) * 100))
        assignment = solve_signed_subset(values, target)
        if assignment is None:
            return False
        selected_positions = [
            index for index, sign in enumerate(assignment) if sign in (-1, 1)
        ]
        if not selected_positions and target != 0:
            return False

        emitted: list[dict] = []
        for index in selected_positions:
            sign = assignment[index]
            block, candidate = all_candidates[index]
            candidate_index = block["candidates"].index(candidate)
            previous_end = (
                block["candidates"][candidate_index - 1]["end"]
                if candidate_index > 0 else 0
            )
            description = clean_db_text(
                block["movement_source"][previous_end:candidate["start"]]
            )[:500] or "accounting movement"
            emitted.append({
                "date": block["date"],
                "description": description,
                "debit": candidate["value"] if sign < 0 else None,
                "credit": candidate["value"] if sign > 0 else None,
                "balance": None,
                "_balance": None,
                "row_role": "TRANSACTION",
                "_source_line_indexes": sorted(set(block["source_indexes"])),
            })
        if emitted:
            emitted[-1]["balance"] = end_balance
            emitted[-1]["_balance"] = end_balance
            flattened_rows.extend(emitted)
        resolved_windows += 1
        return True

    if anchor_balance is not None:
        for block in parsed_blocks:
            unresolved_window.append(block)
            candidate_count = sum(
                len(item["candidates"])
                for item in unresolved_window
            )

            end_balance = float(block["terminal_balance"])

            # Resolve the shortest available window first. This preserves every
            # already validated accounting segment and prevents a later complex
            # page from invalidating earlier resolved pages.
            if emit_window(unresolved_window, anchor_balance, end_balance):
                unresolved_window = []
                anchor_balance = end_balance
                continue

            if (
                len(unresolved_window) <= MAX_WINDOW_BLOCKS
                and candidate_count <= MAX_WINDOW_CANDIDATES
            ):
                continue

            # The local window exceeded the bounded structural budget. Abstain
            # from this additive branch without mutating or returning a partial
            # ledger. Historical paths and the neutral position fallback remain
            # available exactly as before.
            unresolved_windows += 1
            flattened_branch_failed = True
            break

        if unresolved_window and not flattened_branch_failed:
            unresolved_windows += 1
            flattened_branch_failed = True

    print("STANDARD_DATE_PARTICULARS_DCB_FLATTENED_BLOCKS", {
        "version": "v2-additive-deterministic-balance-windows",
        "blocks": len(parsed_blocks),
        "resolved_windows": resolved_windows,
        "unresolved_windows": unresolved_windows,
        "branch_failed": flattened_branch_failed,
        "observations": len(flattened_rows),
        "max_window_blocks": MAX_WINDOW_BLOCKS,
        "max_window_candidates": MAX_WINDOW_CANDIDATES,
    })

    if flattened_rows and not flattened_branch_failed and unresolved_windows == 0:
        flattened = finalize(flattened_rows, "flattened_balance_windows")
        if flattened:
            return flattened

    # ------------------------------------------------------------------
    # 4. Final additive fallback: explicit neutral position observations.
    # ------------------------------------------------------------------
    position_re = re.compile(
        r"^MONEY_LEDGER_POSITION_TX\s+"
        r"date=(?P<date>\d{4}-\d{2}-\d{2})\s+"
        r"debit=(?P<debit>[^\s]*)\s+credit=(?P<credit>[^\s]*)\s+"
        r"balance=(?P<balance>[^\s]*)\s+description=(?P<description>.*)$",
        re.IGNORECASE,
    )
    position_rows: list[dict] = []
    seen_positions = set()
    for source_index, source_line in enumerate(raw.splitlines()):
        match = position_re.match(compact(source_line))
        if not match:
            continue
        debit = parse_money(match.group("debit")) if match.group("debit") else None
        credit = parse_money(match.group("credit")) if match.group("credit") else None
        try:
            running_balance = (
                round(float(parse_amount(match.group("balance"))), 2)
                if match.group("balance") else None
            )
        except Exception:
            running_balance = None
        if (debit is None) == (credit is None):
            continue
        description = clean_db_text(match.group("description"))[:500]
        if not description:
            continue
        identity = (
            match.group("date"), debit, credit, running_balance, description
        )
        if identity in seen_positions:
            continue
        seen_positions.add(identity)
        position_rows.append({
            "date": match.group("date"),
            "description": description,
            "debit": debit,
            "credit": credit,
            "balance": running_balance,
            "_balance": running_balance,
            "row_role": "TRANSACTION",
            "_source_line_index": source_index,
        })


    # ------------------------------------------------------------------
    # 5. Additive exact-residual recovery from explicit position evidence.
    # ------------------------------------------------------------------
    def observation_totals(observations: list[dict]) -> tuple[float, float]:
        debit_total = round(
            sum(
                abs(float(row.get("debit") or 0))
                for row in observations
                if isinstance(row, dict) and row.get("debit") is not None
            ),
            2,
        )
        credit_total = round(
            sum(
                abs(float(row.get("credit") or 0))
                for row in observations
                if isinstance(row, dict) and row.get("credit") is not None
            ),
            2,
        )
        return debit_total, credit_total

    def multiplicity_identity(row: dict) -> tuple:
        debit = row.get("debit")
        credit = row.get("credit")
        return (
            str(row.get("date") or ""),
            round(float(debit), 2) if debit is not None else None,
            round(float(credit), 2) if credit is not None else None,
        )

    def exact_subset_by_amount(
        candidates: list[dict],
        target: float,
        amount_field: str,
    ) -> list[dict] | None:
        """Select a deterministic exact subset using integer-cent bitsets."""
        target_cents = int(round(float(target) * 100))
        if target_cents < 0:
            return None
        if target_cents == 0:
            return []

        normalized: list[tuple[int, dict]] = []
        for row in candidates:
            try:
                cents = int(
                    round(abs(float(row.get(amount_field) or 0)) * 100)
                )
            except Exception:
                continue
            if 0 < cents <= target_cents:
                normalized.append((cents, row))

        normalized.sort(
            key=lambda item: (
                0
                if item[1].get("_balance") is not None
                or item[1].get("balance") is not None
                else 1,
                int(
                    item[1].get("_source_line_index")
                    if item[1].get("_source_line_index") is not None
                    else 10**12
                ),
            )
        )

        reachable = 1
        mask = (1 << (target_cents + 1)) - 1
        snapshots: list[int] = []

        for cents, _row in normalized:
            snapshots.append(reachable)
            reachable |= reachable << cents
            reachable &= mask

        if ((reachable >> target_cents) & 1) == 0:
            return None

        selected: list[dict] = []
        remaining = target_cents

        for index in range(len(normalized) - 1, -1, -1):
            cents, row = normalized[index]
            previous_reachable = snapshots[index]

            if (
                remaining >= cents
                and ((previous_reachable >> (remaining - cents)) & 1)
            ):
                selected.append(row)
                remaining -= cents

            if remaining == 0:
                break

        if remaining != 0:
            return None

        selected.reverse()
        return selected

    if (
        flattened_rows
        and position_rows
        and official["debits"] is not None
        and official["credits"] is not None
    ):
        flattened_debits, flattened_credits = observation_totals(
            flattened_rows
        )
        debit_residual = round(
            float(official["debits"]) - flattened_debits,
            2,
        )
        credit_residual = round(
            float(official["credits"]) - flattened_credits,
            2,
        )

        flattened_multiplicity: dict[tuple, int] = {}
        for row in flattened_rows:
            key = multiplicity_identity(row)
            flattened_multiplicity[key] = (
                flattened_multiplicity.get(key, 0) + 1
            )

        consumed_multiplicity: dict[tuple, int] = {}
        available_positions: list[dict] = []

        for row in position_rows:
            key = multiplicity_identity(row)
            consumed = consumed_multiplicity.get(key, 0)
            represented = flattened_multiplicity.get(key, 0)

            if consumed < represented:
                consumed_multiplicity[key] = consumed + 1
                continue

            available_positions.append(row)

        debit_candidates = [
            row for row in available_positions
            if row.get("debit") is not None
        ]
        credit_candidates = [
            row for row in available_positions
            if row.get("credit") is not None
        ]

        selected_debits = (
            exact_subset_by_amount(
                debit_candidates,
                debit_residual,
                "debit",
            )
            if debit_residual >= -0.02
            else None
        )
        selected_credits = (
            exact_subset_by_amount(
                credit_candidates,
                credit_residual,
                "credit",
            )
            if credit_residual >= -0.02
            else None
        )

        if selected_debits is not None and selected_credits is not None:
            selected_ids = {
                id(row)
                for row in selected_debits + selected_credits
            }
            residual_rows: list[dict] = []

            for row in available_positions:
                if id(row) not in selected_ids:
                    continue
                supplemental = dict(row)
                supplemental["classification_source"] = (
                    "exact_official_residual_position_supplement"
                )
                supplemental["_residual_supplement"] = True
                residual_rows.append(supplemental)

            residual_candidate_rows = [
                dict(row)
                for row in flattened_rows
            ] + residual_rows

            residual_transactions = finalize(
                residual_candidate_rows,
                "flattened_windows_plus_exact_position_residual",
            )
            candidate_debits, candidate_credits = observation_totals(
                residual_candidate_rows
            )

            print(
                "STANDARD_DATE_PARTICULARS_DCB_EXACT_RESIDUAL_AUDIT",
                {
                    "version": (
                        "v1-additive-exact-official-residual-recovery"
                    ),
                    "flattened_observations": len(flattened_rows),
                    "available_position_observations": len(
                        available_positions
                    ),
                    "selected_debit_observations": len(
                        selected_debits
                    ),
                    "selected_credit_observations": len(
                        selected_credits
                    ),
                    "supplemental_observations": len(residual_rows),
                    "flattened_debits": flattened_debits,
                    "flattened_credits": flattened_credits,
                    "debit_residual": debit_residual,
                    "credit_residual": credit_residual,
                    "candidate_debits": candidate_debits,
                    "candidate_credits": candidate_credits,
                    "official_debits": official["debits"],
                    "official_credits": official["credits"],
                    "returned": bool(residual_transactions),
                },
            )

            if residual_transactions:
                return residual_transactions
        else:
            print(
                "STANDARD_DATE_PARTICULARS_DCB_EXACT_RESIDUAL_AUDIT",
                {
                    "version": (
                        "v1-additive-exact-official-residual-recovery"
                    ),
                    "flattened_observations": len(flattened_rows),
                    "available_position_observations": len(
                        available_positions
                    ),
                    "flattened_debits": flattened_debits,
                    "flattened_credits": flattened_credits,
                    "debit_residual": debit_residual,
                    "credit_residual": credit_residual,
                    "debit_subset_found": selected_debits is not None,
                    "credit_subset_found": selected_credits is not None,
                    "returned": False,
                },
            )

    # ------------------------------------------------------------------
    # 6. ADDITIVE v122 — sparse running-balance window validation.
    # ------------------------------------------------------------------
    #
    # Structural family:
    #   Date | Description | Debit | Credit | Balance
    #
    # The debit/credit cells may be preserved for every transaction while some
    # balance cells are absent, split into OCR fragments, or locally malformed.
    # Statements may also be printed newest transaction first.
    #
    # Historical branches remain first and unchanged. This branch runs only
    # when no official debit/credit summary exists and explicit physical-column
    # observations are already available.
    #
    # Accounting rule for descending statements:
    #
    #   balance[i] = balance[j] + sum(credit - debit for rows i..j-1)
    #
    # for consecutive visible balance checkpoints i < j.
    #
    # A malformed checkpoint may be removed ONLY when bypassing it produces an
    # exact accounting window between its neighboring checkpoints. Transaction
    # amounts and directions are never changed by this repair.
    def validate_sparse_balance_windows(
        observations: list[dict],
    ) -> dict | None:
        if len(observations) < 3:
            return None

        # ADDITIVE v124 — an incomplete one-sided "official" flow observation
        # must not suppress structural accounting validation.
        #
        # Example from the real statement: a weak summary heuristic promoted
        # the first transaction debit (23.10) to official["debits"] while no
        # official credit total existed. That is not a complete accounting
        # summary and therefore cannot outrank the explicit Debit/Credit table.
        #
        # Only a COMPLETE pair of official flow totals blocks this fallback.
        if (
            official["debits"] is not None
            and official["credits"] is not None
        ):
            return None

        dated_rows = [
            dict(row)
            for row in observations
            if (
                isinstance(row, dict)
                and row.get("date")
                and (
                    row.get("debit") is not None
                    or row.get("credit") is not None
                )
            )
        ]
        if len(dated_rows) < 3:
            return None

        date_values = []
        for row in dated_rows:
            try:
                date_values.append(
                    datetime.strptime(
                        str(row["date"]),
                        "%Y-%m-%d",
                    )
                )
            except Exception:
                return None

        descending_pairs = sum(
            left >= right
            for left, right in zip(
                date_values,
                date_values[1:],
            )
        )
        ascending_pairs = sum(
            left <= right
            for left, right in zip(
                date_values,
                date_values[1:],
            )
        )
        statement_order = (
            "descending"
            if descending_pairs >= ascending_pairs
            else "ascending"
        )

        movements = []
        for row in dated_rows:
            debit_value = round(
                abs(float(row.get("debit") or 0.0)),
                2,
            )
            credit_value = round(
                abs(float(row.get("credit") or 0.0)),
                2,
            )
            movements.append(
                round(
                    credit_value - debit_value,
                    2,
                )
            )

        checkpoints = []
        for index, row in enumerate(dated_rows):
            balance_value = row.get("balance")
            if balance_value is None:
                balance_value = row.get("_balance")
            if balance_value is None:
                continue
            try:
                checkpoints.append(
                    (
                        index,
                        round(
                            float(balance_value),
                            2,
                        ),
                    )
                )
            except Exception:
                continue

        if len(checkpoints) < 2:
            return None

        def window_error(
            left_checkpoint: tuple[int, float],
            right_checkpoint: tuple[int, float],
        ) -> float:
            left_index, left_balance = left_checkpoint
            right_index, right_balance = right_checkpoint

            if right_index <= left_index:
                return float("inf")

            if statement_order == "descending":
                expected_left = round(
                    right_balance
                    + sum(
                        movements[
                            left_index:right_index
                        ]
                    ),
                    2,
                )
                return round(
                    left_balance - expected_left,
                    2,
                )

            expected_right = round(
                left_balance
                + sum(
                    movements[
                        left_index + 1:
                        right_index + 1
                    ]
                ),
                2,
            )
            return round(
                right_balance - expected_right,
                2,
            )

        def window_matches(
            left_checkpoint: tuple[int, float],
            right_checkpoint: tuple[int, float],
        ) -> bool:
            error = window_error(
                left_checkpoint,
                right_checkpoint,
            )
            if error == float("inf"):
                return False

            left_index, left_balance = left_checkpoint
            right_index, right_balance = right_checkpoint

            local_scale = max(
                1.0,
                abs(left_balance),
                abs(right_balance),
                *[
                    abs(value)
                    for value in movements[
                        left_index:
                        right_index + 1
                    ]
                ],
            )
            local_tolerance = max(
                tolerance,
                local_scale * 0.000001,
            )
            return abs(error) <= local_tolerance

        # --------------------------------------------------------------
        # Exact checkpoint pruning.
        # --------------------------------------------------------------
        #
        # Interior checkpoint B may be discarded only if:
        #   A -> C reconciles exactly, and
        #   at least one of A -> B or B -> C does not.
        #
        # This identifies an OCR-corrupted balance without using merchant text,
        # bank identity, country, currency or any hard-coded amount.
        pruned_checkpoints = list(checkpoints)
        removed_checkpoints = []
        changed = True

        while changed and len(pruned_checkpoints) >= 3:
            changed = False

            for checkpoint_index in range(
                1,
                len(pruned_checkpoints) - 1,
            ):
                left_checkpoint = pruned_checkpoints[
                    checkpoint_index - 1
                ]
                middle_checkpoint = pruned_checkpoints[
                    checkpoint_index
                ]
                right_checkpoint = pruned_checkpoints[
                    checkpoint_index + 1
                ]

                left_middle = window_matches(
                    left_checkpoint,
                    middle_checkpoint,
                )
                middle_right = window_matches(
                    middle_checkpoint,
                    right_checkpoint,
                )
                left_right = window_matches(
                    left_checkpoint,
                    right_checkpoint,
                )

                if (
                    left_right
                    and (
                        not left_middle
                        or not middle_right
                    )
                ):
                    removed_checkpoints.append(
                        middle_checkpoint
                    )
                    pruned_checkpoints.pop(
                        checkpoint_index
                    )
                    changed = True
                    break

            if changed:
                continue

            # Endpoint checkpoint can be discarded only when its adjacent
            # internal window is exact while the endpoint window is not.
            if (
                len(pruned_checkpoints) >= 3
                and not window_matches(
                    pruned_checkpoints[0],
                    pruned_checkpoints[1],
                )
                and window_matches(
                    pruned_checkpoints[1],
                    pruned_checkpoints[2],
                )
            ):
                removed_checkpoints.append(
                    pruned_checkpoints.pop(0)
                )
                changed = True
                continue

            if (
                len(pruned_checkpoints) >= 3
                and not window_matches(
                    pruned_checkpoints[-2],
                    pruned_checkpoints[-1],
                )
                and window_matches(
                    pruned_checkpoints[-3],
                    pruned_checkpoints[-2],
                )
            ):
                removed_checkpoints.append(
                    pruned_checkpoints.pop()
                )
                changed = True

        window_checks = max(
            0,
            len(pruned_checkpoints) - 1,
        )
        window_matches_count = 0
        window_mismatches = []
        trusted_checkpoint_indices = set()

        for left_checkpoint, right_checkpoint in zip(
            pruned_checkpoints,
            pruned_checkpoints[1:],
        ):
            if window_matches(
                left_checkpoint,
                right_checkpoint,
            ):
                window_matches_count += 1
                trusted_checkpoint_indices.add(
                    left_checkpoint[0]
                )
                trusted_checkpoint_indices.add(
                    right_checkpoint[0]
                )
            else:
                window_mismatches.append({
                    "left_index": left_checkpoint[0],
                    "right_index": right_checkpoint[0],
                    "left_balance": left_checkpoint[1],
                    "right_balance": right_checkpoint[1],
                    "error": window_error(
                        left_checkpoint,
                        right_checkpoint,
                    ),
                })

        if window_checks < 6:
            return None

        window_match_ratio = (
            window_matches_count
            / window_checks
        )

        internally_supported = bool(
            window_matches_count >= 6
            and window_match_ratio >= 0.90
            and len(trusted_checkpoint_indices) >= 7
            and len(window_mismatches)
            <= max(
                10,
                int(window_checks * 0.10),
            )
        )

        if not internally_supported:
            print(
                "STANDARD_DATE_PARTICULARS_DCB_SPARSE_BALANCE_AUDIT",
                {
                    "version": (
                        "v124-additive-incomplete-summary-does-not-block-sparse-balance"
                    ),
                    "statement_order": statement_order,
                    "transactions": len(dated_rows),
                    "raw_checkpoints": len(checkpoints),
                    "removed_checkpoints": len(
                        removed_checkpoints
                    ),
                    "validated_checkpoints": len(
                        pruned_checkpoints
                    ),
                    "window_checks": window_checks,
                    "window_matches": (
                        window_matches_count
                    ),
                    "window_mismatches": len(
                        window_mismatches
                    ),
                    "window_match_ratio": round(
                        window_match_ratio,
                        6,
                    ),
                    "accepted": False,
                    "mismatch_samples": (
                        window_mismatches[:5]
                    ),
                },
            )
            return None

        trusted_candidates = [
            checkpoint
            for checkpoint in pruned_checkpoints
            if checkpoint[0]
            in trusted_checkpoint_indices
        ]
        if not trusted_candidates:
            return None

        anchor_index, anchor_balance = (
            trusted_candidates[0]
        )

        if statement_order == "descending":
            reconstructed_closing = round(
                anchor_balance
                + sum(
                    movements[:anchor_index]
                ),
                2,
            )
            reconstructed_opening = round(
                anchor_balance
                - sum(
                    movements[
                        anchor_index:
                    ]
                ),
                2,
            )
        else:
            reconstructed_opening = round(
                anchor_balance
                - sum(
                    movements[
                        :anchor_index + 1
                    ]
                ),
                2,
            )
            reconstructed_closing = round(
                anchor_balance
                + sum(
                    movements[
                        anchor_index + 1:
                    ]
                ),
                2,
            )

        debit_total = round(
            sum(
                abs(float(row.get("debit") or 0))
                for row in dated_rows
            ),
            2,
        )
        credit_total = round(
            sum(
                abs(float(row.get("credit") or 0))
                for row in dated_rows
            ),
            2,
        )
        identity_gap = round(
            reconstructed_opening
            + credit_total
            - debit_total
            - reconstructed_closing,
            2,
        )

        if abs(identity_gap) > tolerance:
            return None

        neutral_rows: list[dict] = [{
            "row_role": "BALANCE",
            "balance": reconstructed_opening,
            "balance_role": "opening",
            "parser_family": family,
        }]

        # Sparse running balances have already served as validation evidence.
        # Do NOT feed them back as per-transaction authority: when one or more
        # intermediate balance cells are missing, the next visible checkpoint
        # represents the cumulative delta of several transactions and would
        # incorrectly absorb those missing movements.
        #
        # The common accounting layer therefore receives:
        #   - explicit debit/credit observations for every transaction;
        #   - reconstructed opening/closing BALANCE observations only.
        #
        # Direction/magnitude still finish through infer_balance_delta_rows().
        for dated_row in dated_rows:
            neutral_transaction = dict(dated_row)
            neutral_transaction["balance"] = None
            neutral_transaction["_balance"] = None
            neutral_transaction[
                "validation_balance_source"
            ] = "sparse_checkpoint_window"
            neutral_rows.append(
                neutral_transaction
            )

        neutral_rows.append({
            "row_role": "BALANCE",
            "balance": reconstructed_closing,
            "balance_role": "closing",
            "parser_family": family,
        })

        validated_transactions = (
            infer_balance_delta_rows(
                neutral_rows
            )
            or []
        )
        validated_dated = [
            transaction
            for transaction in validated_transactions
            if (
                isinstance(transaction, dict)
                and transaction.get("date")
                and transaction.get("type")
                in {"income", "expense"}
            )
        ]

        if len(validated_dated) != len(dated_rows):
            return None

        validated_debits = round(
            sum(
                abs(float(
                    transaction.get("signed_amount")
                    if transaction.get("signed_amount")
                    is not None
                    else transaction.get("amount") or 0
                ))
                for transaction in validated_dated
                if float(
                    transaction.get("signed_amount")
                    if transaction.get("signed_amount")
                    is not None
                    else transaction.get("amount") or 0
                ) < 0
            ),
            2,
        )
        validated_credits = round(
            sum(
                abs(float(
                    transaction.get("signed_amount")
                    if transaction.get("signed_amount")
                    is not None
                    else transaction.get("amount") or 0
                ))
                for transaction in validated_dated
                if float(
                    transaction.get("signed_amount")
                    if transaction.get("signed_amount")
                    is not None
                    else transaction.get("amount") or 0
                ) > 0
            ),
            2,
        )

        if (
            abs(
                validated_debits - debit_total
            )
            > tolerance
            or abs(
                validated_credits - credit_total
            )
            > tolerance
        ):
            print(
                "STANDARD_DATE_PARTICULARS_DCB_SPARSE_COMMON_LAYER_REJECT",
                {
                    "expected_debits": debit_total,
                    "actual_debits": validated_debits,
                    "expected_credits": credit_total,
                    "actual_credits": validated_credits,
                },
            )
            return None

        for transaction in validated_dated:
            transaction["parser_family"] = family
            transaction["classification_source"] = (
                "explicit_physical_column"
            )
            transaction["validation_source"] = (
                "sparse_running_balance_windows"
            )
            transaction["accounting_reconciled"] = True
            transaction["balance_reconciled"] = True
            transaction["reconciliation_source"] = (
                "sparse_balance_window_identity"
            )
            transaction[
                "_statement_opening_balance"
            ] = reconstructed_opening
            transaction[
                "_statement_closing_balance"
            ] = reconstructed_closing
            transaction[
                "_local_debit_total"
            ] = debit_total
            transaction[
                "_local_credit_total"
            ] = credit_total

        print(
            "STANDARD_DATE_PARTICULARS_DCB_SPARSE_BALANCE_AUDIT",
            {
                "version": (
                    "v124-additive-incomplete-summary-does-not-block-sparse-balance"
                ),
                "statement_order": statement_order,
                "transactions": len(
                    validated_dated
                ),
                "debit_count": sum(
                    1
                    for row in dated_rows
                    if row.get("debit")
                    is not None
                ),
                "credit_count": sum(
                    1
                    for row in dated_rows
                    if row.get("credit")
                    is not None
                ),
                "debit_total": debit_total,
                "credit_total": credit_total,
                "raw_checkpoints": len(checkpoints),
                "removed_checkpoints": len(
                    removed_checkpoints
                ),
                "validated_checkpoints": len(
                    pruned_checkpoints
                ),
                "window_checks": window_checks,
                "window_matches": (
                    window_matches_count
                ),
                "window_mismatches": len(
                    window_mismatches
                ),
                "window_match_ratio": round(
                    window_match_ratio,
                    6,
                ),
                "reconstructed_opening": (
                    reconstructed_opening
                ),
                "reconstructed_closing": (
                    reconstructed_closing
                ),
                "identity_gap": identity_gap,
                "accepted": True,
            },
        )

        return validated_dated

    sparse_balance_candidate = (
        validate_sparse_balance_windows(
            position_rows
        )
    )
    if sparse_balance_candidate:
        return sparse_balance_candidate

    def position_balance_chain_reconciles(
        observations: list[dict],
    ) -> bool:
        if not observations:
            return False

        try:
            previous_balance = (
                float(official["opening"])
                if official["opening"] is not None
                else None
            )
        except Exception:
            previous_balance = None

        if previous_balance is None:
            return False

        pending_delta = 0.0
        checkpoints = 0

        for observation in observations:
            try:
                pending_delta += (
                    float(observation.get("credit") or 0)
                    - float(observation.get("debit") or 0)
                )
            except Exception:
                return False

            if observation.get("balance") is None:
                continue

            try:
                observed_balance = float(
                    observation.get("balance")
                )
            except Exception:
                return False

            expected_balance = round(
                previous_balance + pending_delta,
                2,
            )

            if abs(
                expected_balance - observed_balance
            ) > tolerance:
                return False

            previous_balance = observed_balance
            pending_delta = 0.0
            checkpoints += 1

        if abs(pending_delta) > tolerance:
            return False

        if official["closing"] is not None:
            try:
                if abs(
                    previous_balance
                    - float(official["closing"])
                ) > tolerance:
                    return False
            except Exception:
                return False

        return checkpoints >= 2

    # ADDITIVE v170 — sparse group balances are accounting observations,
    # not properties of the final movement row in the group.
    #
    # A visible balance printed on the same baseline as the last movement may
    # summarize several movements since the previous balance checkpoint.  Feed
    # that balance to the common accounting layer as a neutral BALANCE row,
    # after the explicit Debit/Credit transaction.  This preserves priority:
    # explicit physical columns establish movement sign and amount; the balance
    # remains available to advance the accounting chain but cannot overwrite a
    # single movement with the whole group delta.
    position_accounting_rows: list[dict] = []

    for source_row in position_rows:
        transaction_row = dict(source_row)
        observed_balance = transaction_row.pop("balance", None)
        transaction_row.pop("_balance", None)

        position_accounting_rows.append(transaction_row)

        if observed_balance is not None:
            position_accounting_rows.append({
                "balance": observed_balance,
                "_balance": observed_balance,
                "row_role": "BALANCE",
                "balance_role": "observed",
                "parser_family": family,
                "classification_source": (
                    "explicit_running_balance_checkpoint"
                ),
            })

    transactions = finalize(
        position_accounting_rows,
        "explicit_position_column",
    )

    position_balance_reconciled = (
        position_balance_chain_reconciles(
            position_rows
        )
        if transactions
        else False
    )

    if transactions and position_balance_reconciled:
        for transaction in transactions:
            if not (
                isinstance(transaction, dict)
                and transaction.get("date")
            ):
                continue

            transaction["accounting_reconciled"] = True
            transaction["balance_reconciled"] = True
            transaction[
                "reconciliation_source"
            ] = (
                "explicit_columns_plus_running_balance_checkpoints"
            )

        print(
            "STANDARD_DATE_PARTICULARS_DCB_POSITION_AUTHORITY",
            {
                "transactions": len([
                    tx
                    for tx in transactions
                    if isinstance(tx, dict)
                    and tx.get("date")
                ]),
                "balance_reconciled": True,
                "official_debits": official["debits"],
                "official_credits": official["credits"],
                "opening": official["opening"],
                "closing": official["closing"],
            },
        )

    return transactions

